const requireAdminTokenJson: express.RequestHandler = (req, res, next) => {
  const expected = String(process.env.TD_ADMIN_TOKEN || "").trim();
  if (!expected) {
    return res.status(503).json({ ok: false, reason: "admin_token_missing" });
  }

  const headerValue = req.headers["x-td-admin-token"];
  const provided = Array.isArray(headerValue)
    ? String(headerValue[0] || "").trim()
    : String(headerValue || "").trim();

  if (!provided || provided !== expected) {
    return res.status(401).json({ ok: false, reason: "admin_token_invalid" });
  }

  return next();
};

app.post("/api/v1/shell-packs/ensure", requireAdminTokenJson, (req, res) => {
  try {
    const body = req.body && typeof req.body === "object" && !Array.isArray(req.body)
      ? req.body as Record<string, unknown>
      : {};

    const result = ensureShellPack(repoRoot, {
      sourceBrandingId: body.sourceBrandingId as string,
      brandingId: body.brandingId as string,
      mode: body.mode as "create_if_missing"
    });

    return res.json({
      ok: true,
      sourceBrandingId: result.sourceBrandingId,
      brandingId: result.brandingId,
      destinationPath: path.relative(repoRoot, result.packRoot).replace(/\\/g, "/"),
      manifestPath: path.relative(repoRoot, result.manifestPath).replace(/\\/g, "/"),
      bootstrapStatus: result.bootstrapStatus
    });
  } catch (err) {
    const msg = String(err instanceof Error ? err.message : err);
    const status =
      msg === "shell_pack_bootstrap_source_invalid" ||
      msg === "shell_pack_bootstrap_destination_invalid" ||
      msg === "shell_pack_bootstrap_mode_invalid"
        ? 400
        : 500;

    return res.status(status).json({
      ok: false,
      reason: msg
    });
  }
});

