// Shared RPC clients (keep connected to avoid resolver roulette / reconnect latency)
const sharedRpcByNetworkId = new Map<string, RpcClient>();
const rpcConnectInFlightByNetworkId = new Map<string, Promise<void>>();

function rpcConnectTimeoutMs(networkId: string): number {
  return networkId === "testnet-10" ? 8000 : 4000;
}

function clearSharedRpc(networkId: string, rpc?: RpcClient | null): void {
  const current = sharedRpcByNetworkId.get(networkId);
  if (!rpc || current === rpc) {
    sharedRpcByNetworkId.delete(networkId);
  }
  rpcConnectInFlightByNetworkId.delete(networkId);
}

async function ensureRpcConnected(networkId: string, rpc: RpcClient): Promise<void> {
  if (rpc.isConnected) return;

  const inFlight = rpcConnectInFlightByNetworkId.get(networkId);
  if (inFlight) {
    await inFlight;
    return;
  }

  let connectTimer: ReturnType<typeof setTimeout> | null = null;

  const p = (async () => {
    try {
      const connectPromise = rpc.connect();
      const timeoutPromise = new Promise<never>((_, reject) => {
        connectTimer = setTimeout(() => reject(new Error("rpc_connect_timeout")), rpcConnectTimeoutMs(networkId));
      });
      await Promise.race([connectPromise, timeoutPromise]);
    } finally {
      if (connectTimer) clearTimeout(connectTimer);
    }
  })();

  rpcConnectInFlightByNetworkId.set(networkId, p);
  try {
    await p;
  } catch (err) {
    clearSharedRpc(networkId, rpc);
    throw err;
  } finally {
    rpcConnectInFlightByNetworkId.delete(networkId);
  }
}

function createRpcClient(networkId: string): RpcClient {
  if (networkId === "testnet-10") {
    return new RpcClient({ url: "ws://tn10.token-depot.co:17210", networkId });
  }
  return new RpcClient({ resolver: new Resolver(), networkId });
}

async function getSharedRpc(networkId: string): Promise<RpcClient> {
  let rpc = sharedRpcByNetworkId.get(networkId);
  if (!rpc) {
    rpc = createRpcClient(networkId);
    sharedRpcByNetworkId.set(networkId, rpc);
  }

  try {
    await ensureRpcConnected(networkId, rpc);
    return rpc;
  } catch {
    const fresh = createRpcClient(networkId);
    sharedRpcByNetworkId.set(networkId, fresh);
    await ensureRpcConnected(networkId, fresh);
    return fresh;
  }
}

type SwapPhase = "offer" | "accept" | "finalize";
type SwapKind = "tick_to_kas" | "ca_to_kas";

type SwapValidationResult = {
  ok: boolean;
  errors: string[];
  warnings: string[];
};

const PSKB_PREFIX = "PSKB";
const HEX_KASPLEX_MARKER = Buffer.from("kasplex", "utf8").toString("hex");
const HEX_KRC20_PROTOCOL = Buffer.from('"p":"krc-20"', "utf8").toString("hex");
const HEX_OP_TRANSFER = Buffer.from('"op":"transfer"', "utf8").toString("hex");
const HEX_OP_SEND = Buffer.from('"op":"send"', "utf8").toString("hex");
const HEX_OP_LIST = Buffer.from('"op":"list"', "utf8").toString("hex");
const HEX_KEY_TICK = Buffer.from('"tick":', "utf8").toString("hex");
const HEX_KEY_CA = Buffer.from('"ca":', "utf8").toString("hex");
const HEX_KEY_TO = Buffer.from('"to":', "utf8").toString("hex");
const HEX_KEY_AMT = Buffer.from('"amt":', "utf8").toString("hex");

function isHexString(s: string): boolean {
  return /^[0-9a-fA-F]+$/.test(s);
}

function safeLowerHex(hex: string): string {
  return String(hex || "").trim().toLowerCase();
}

function decodePskbPayloadArray(pskb: string): any[] {
  const raw = String(pskb || "").trim();
  if (!raw.startsWith(PSKB_PREFIX)) {
    throw new Error("pskb_prefix_missing");
  }
  const hex = raw.slice(PSKB_PREFIX.length);
  if (!hex || hex.length % 2 !== 0 || !isHexString(hex)) {
    throw new Error("pskb_hex_invalid");
  }
  const jsonText = Buffer.from(hex, "hex").toString("utf8");
  const parsed = JSON.parse(jsonText);
  if (!Array.isArray(parsed)) {
    throw new Error("pskb_json_must_be_array");
  }
  return parsed;
}

function encodePskbPayloadArray(payloadArr: any[]): string {
  const jsonText = JSON.stringify(payloadArr, (_k, v) => (typeof v === "bigint" ? v.toString() : v));
  return PSKB_PREFIX + Buffer.from(jsonText, "utf8").toString("hex");
}

function readSompi(v: any): bigint | null {
  if (typeof v === "bigint") return v;
  if (typeof v === "number" && Number.isFinite(v) && v >= 0 && Number.isInteger(v)) return BigInt(v);
  if (typeof v === "string") {
    const s = v.trim();
    if (/^\d+$/.test(s)) return BigInt(s);
  }
  return null;
}

function readBool(obj: any, key: string): boolean | null {
  if (!obj || typeof obj !== "object") return null;
  const v = (obj as any)[key];
  return typeof v === "boolean" ? v : null;
}

function pickFirstHexField(obj: any, keys: string[]): string {
  const toHex = (v: any): string => {
    if (!v) return "";
    if (typeof v === "string" && v) return v;
    if (v instanceof Uint8Array && v.length) return Buffer.from(v).toString("hex");
    if (Array.isArray(v) && v.length && v.every((n) => typeof n === "number")) return Buffer.from(v).toString("hex");

    if (v && typeof v === "object") {
      const o: any = v;

      if (typeof o.hex === "string" && o.hex) return o.hex;

      if (o.data) {
        const h = toHex(o.data);
        if (h) return h;
      }
      if (o.bytes) {
        const h = toHex(o.bytes);
        if (h) return h;
      }
      if (o.value) {
        const h = toHex(o.value);
        if (h) return h;
      }

      const ks = Object.keys(o);
      if (ks.length && ks.every((k) => /^\d+$/.test(k))) {
        ks.sort((a, b) => Number(a) - Number(b));
        const arr = ks.map((k) => o[k]);
        if (arr.length && arr.every((n) => typeof n === "number")) return Buffer.from(arr).toString("hex");
      }
    }

    return "";
  };

  for (const k of keys) {
    const v = obj && typeof obj === "object" ? (obj as any)[k] : null;
    const hex = toHex(v);
    if (hex) return hex;
  }
  return "";
}

function normalizeScriptPublicKeyHex(spkAny: any): string {
  const toHex = (v: any): string => {
    if (!v) return "";
    if (typeof v === "string") {
      const s = v.trim();
      return s && isHexString(s) && s.length % 2 === 0 ? safeLowerHex(s) : "";
    }
    if (v instanceof Uint8Array && v.length) return safeLowerHex(Buffer.from(v).toString("hex"));
    if (Array.isArray(v) && v.length && v.every((n) => typeof n === "number")) {
      return safeLowerHex(Buffer.from(v).toString("hex"));
    }
    return "";
  };

  const hx0 = toHex(spkAny);
  if (hx0) {
    return hx0.startsWith("0000") ? hx0 : safeLowerHex("0000" + hx0);
  }

  if (spkAny && typeof spkAny === "object") {
    const version = (spkAny as any).version;
    const scriptAny = (spkAny as any).script ?? (spkAny as any).scriptPublicKey ?? (spkAny as any).data;
    const scriptHex = toHex(scriptAny);
    if (typeof version === "number" && Number.isInteger(version) && scriptHex) {
      return safeLowerHex(version.toString(16).padStart(4, "0") + scriptHex);
    }
  }

  return "";
}

function containsHexNeedle(hayHex: string, needleHex: string): boolean {
  const hay = safeLowerHex(hayHex);
  const needle = safeLowerHex(needleHex);
  if (!hay || !needle) return false;
  return hay.includes(needle);
}

function parseSighashMaybe(v: any): number | null {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string" && v.trim()) {
    const n = Number(v.trim());
    if (Number.isFinite(n)) return n;
  }
  return null;
}

function readInputSighashType(input0: any): number | null {
  if (!input0 || typeof input0 !== "object") return null;
  const direct = parseSighashMaybe((input0 as any).sighashType);
  if (direct !== null) return direct;
  const alt1 = parseSighashMaybe((input0 as any).sigHashType);
  if (alt1 !== null) return alt1;
  const alt2 = parseSighashMaybe((input0 as any).sighash_type);
  if (alt2 !== null) return alt2;
  return null;
}

async function validateSwapPskb(repoRoot: string, args: { phase: SwapPhase; kind: SwapKind; pskb: string }): Promise<SwapValidationResult> {
  const errors: string[] = [];
  const warnings: string[] = [];

  if (!args || typeof args !== "object") {
    return { ok: false, errors: ["invalid_args"], warnings: [] };
  }
  if (typeof args.pskb !== "string" || !args.pskb) errors.push("missing_pskb");
  if (args.phase !== "offer" && args.phase !== "accept" && args.phase !== "finalize") errors.push("invalid_phase");
  if (args.kind !== "tick_to_kas" && args.kind !== "ca_to_kas") errors.push("invalid_kind");
  if (errors.length) return { ok: false, errors, warnings };

  await ensureKaspaReady(repoRoot);
  try {
    PSKB.deserialize(args.pskb);
  } catch (e) {
    errors.push("pskb_deserialize_failed");
    warnings.push(String(e));
  }

  let arr: any[] = [];
  try {
    arr = decodePskbPayloadArray(args.pskb);
  } catch (e) {
    errors.push(String(e instanceof Error ? e.message : e));
    return { ok: false, errors, warnings };
  }

  if (arr.length !== 1) {
    errors.push("pskb_must_contain_single_pskt_for_m4a");
    return { ok: false, errors, warnings };
  }

  const pskt0: any = arr[0];
  const global0: any = pskt0 && typeof pskt0 === "object" ? (pskt0 as any).global : null;

  const inMod = readBool(global0, "inputsModifiable");
  const outMod = readBool(global0, "outputsModifiable");
  if (inMod === null) errors.push("pskb_global_inputsModifiable_missing");
  if (outMod === null) errors.push("pskb_global_outputsModifiable_missing");

  if (args.phase === "finalize") {
    if (inMod !== false) errors.push("pskb_inputs_must_be_locked_for_finalize");
    if (outMod !== false) errors.push("pskb_outputs_must_be_locked_for_finalize");
  } else {
    if (inMod !== true) errors.push("pskb_inputs_must_be_modifiable_for_offer_accept");
    if (outMod !== true) errors.push("pskb_outputs_must_be_modifiable_for_offer_accept");
  }

  const inputs0: any[] = Array.isArray((pskt0 as any)?.inputs) ? (pskt0 as any).inputs : [];
  if (inputs0.length < 1) {
    errors.push("pskb_missing_input0");
    return { ok: false, errors, warnings };
  }

  const input0 = inputs0[0];
  const probeKeys = ["redeemScript", "finalScriptSig", "finalSignatureScript", "signatureScript"];
  const probeHex = pickFirstHexField(input0, probeKeys);
  if (!probeHex || !isHexString(probeHex)) {
    try {
      warnings.push(`input0_keys=${Object.keys(input0).join(",")}`);
    } catch {
      warnings.push("input0_keys=<unavailable>");
    }

    for (const k of probeKeys) {
      const v = (input0 as any)?.[k];
      if (typeof v === "string") warnings.push(`input0.${k}=string(len=${v.length})`);
      else if (v instanceof Uint8Array) warnings.push(`input0.${k}=Uint8Array(len=${v.length})`);
      else if (Array.isArray(v)) warnings.push(`input0.${k}=Array(len=${v.length})`);
      else if (v && typeof v === "object") warnings.push(`input0.${k}=object(keys=${Object.keys(v).join(",")})`);
      else warnings.push(`input0.${k}=${String(v)}`);
    }

    const nestedCandidates = ["input", "txInput", "transactionInput", "transaction_input"];
    for (const nk of nestedCandidates) {
      const n = (input0 as any)?.[nk];
      if (n && typeof n === "object") {
        warnings.push(`input0.${nk}_keys=${Object.keys(n).join(",")}`);
        for (const k of probeKeys) {
          const v = (n as any)?.[k];
          if (typeof v === "string") warnings.push(`input0.${nk}.${k}=string(len=${v.length})`);
          else if (v instanceof Uint8Array) warnings.push(`input0.${nk}.${k}=Uint8Array(len=${v.length})`);
          else if (Array.isArray(v)) warnings.push(`input0.${nk}.${k}=Array(len=${v.length})`);
          else if (v && typeof v === "object") warnings.push(`input0.${nk}.${k}=object(keys=${Object.keys(v).join(",")})`);
          else if (v !== undefined && v !== null) warnings.push(`input0.${nk}.${k}=${String(v)}`);
        }
      }
    }

    errors.push("input0_script_hex_missing");
    return { ok: false, errors, warnings };
  }

  if (!containsHexNeedle(probeHex, HEX_KASPLEX_MARKER)) errors.push("krc20_kasplex_marker_missing_in_input0");
  if (!containsHexNeedle(probeHex, HEX_KRC20_PROTOCOL)) errors.push("krc20_protocol_field_missing_in_input0");

  const hasTo = containsHexNeedle(probeHex, HEX_KEY_TO);
  const isOpenOffer = args.phase === "offer" && !hasTo;

  if (isOpenOffer) {
    if (!containsHexNeedle(probeHex, HEX_OP_SEND)) errors.push("krc20_op_send_missing_in_input0");
  } else {
    if (!containsHexNeedle(probeHex, HEX_OP_TRANSFER)) errors.push("krc20_op_transfer_missing_in_input0");
  }

  if (args.phase === "offer") {
    warnings.push(hasTo ? "offer_mode_directed" : "offer_mode_open");
  } else {
    if (!hasTo) errors.push("krc20_to_missing_in_input0");
  }

  if (!isOpenOffer) {
    if (!containsHexNeedle(probeHex, HEX_KEY_AMT)) errors.push("krc20_amt_missing_in_input0");
  }

  if (args.kind === "tick_to_kas") {
    if (!containsHexNeedle(probeHex, HEX_KEY_TICK)) errors.push("krc20_tick_missing_in_input0");
  } else {
    if (!containsHexNeedle(probeHex, HEX_KEY_CA)) errors.push("krc20_ca_missing_in_input0");
  }

  const sh = readInputSighashType(input0);
  if (sh === null) {
    errors.push("input0_sighashType_missing");
  } else if (sh !== SighashType.SingleAnyOneCanPay) {
    errors.push("input0_sighashType_must_be_single_anyonecanpay");
  }

  if (errors.length) {
    const g0: any = global0 && typeof global0 === "object" ? global0 : null;
    const i0: any = input0 && typeof input0 === "object" ? input0 : null;
    const gKeys = g0 ? Object.keys(g0) : [];
    const iKeys = i0 ? Object.keys(i0) : [];
    console.log(`[swap_validate] debug phase=${args.phase} kind=${args.kind}`);
    console.log(`[swap_validate] debug global0.keys=${gKeys.join(",")}`);
    console.log(
      `[swap_validate] debug global0.inputsModifiable=${g0 ? (g0 as any).inputsModifiable : undefined} outputsModifiable=${g0 ? (g0 as any).outputsModifiable : undefined} inputs_modifiable=${g0 ? (g0 as any).inputs_modifiable : undefined} outputs_modifiable=${g0 ? (g0 as any).outputs_modifiable : undefined}`
    );
    console.log(`[swap_validate] debug computed inMod=${inMod} outMod=${outMod}`);
    console.log(`[swap_validate] debug input0.keys=${iKeys.join(",")}`);
    console.log(
      `[swap_validate] debug input0.sighashType=${i0 ? (i0 as any).sighashType : undefined} sigHashType=${i0 ? (i0 as any).sigHashType : undefined} sighash_type=${i0 ? (i0 as any).sighash_type : undefined} computedSh=${sh}`
    );
  }

  return { ok: errors.length === 0, errors, warnings };
}

async function validateOpenSwapPskbV2(
  repoRoot: string,
  args: {
    phase: SwapPhase;
    kind: SwapKind;
    pskb: string;
    expectedSendJsonHex?: string;
    expectedFinalizeRoles?: {
      output0KasReceiverSpkHex: string;
      output1TokenReceiverSpkHex: string;
      output2MakerRefundSpkHex: string;
      output3ChangeSpkHex: string;
    };
  }
): Promise<SwapValidationResult> {
  const errors: string[] = [];
  const warnings: string[] = [];

  if (!args || typeof args !== "object") {
    return { ok: false, errors: ["invalid_args"], warnings: [] };
  }
  if (typeof args.pskb !== "string" || !args.pskb) errors.push("missing_pskb");
  if (args.phase !== "offer" && args.phase !== "accept" && args.phase !== "finalize") errors.push("invalid_phase");
  if (args.kind !== "tick_to_kas" && args.kind !== "ca_to_kas") errors.push("invalid_kind");
  if (errors.length) return { ok: false, errors, warnings };

  await ensureKaspaReady(repoRoot);

  try {
    PSKB.deserialize(args.pskb);
  } catch (e) {
    const sdkDeserializeWarning = String(e);
    if (args.phase === "finalize") {
      warnings.push(`sdk_pskb_deserialize_failed_finalize_custom_wrapper: ${sdkDeserializeWarning}`);
    } else {
      errors.push("pskb_deserialize_failed");
      warnings.push(sdkDeserializeWarning);
    }
  }

  let arr: any[] = [];
  try {
    arr = decodePskbPayloadArray(args.pskb);
  } catch (e) {
    errors.push(String(e instanceof Error ? e.message : e));
    return { ok: false, errors, warnings };
  }

  if (arr.length !== 1) {
    errors.push("pskb_must_contain_single_pskt_for_open_v2");
    return { ok: false, errors, warnings };
  }

  const pskt0: any = arr[0];
  const global0: any = pskt0 && typeof pskt0 === "object" ? (pskt0 as any).global : null;

  const inMod = readBool(global0, "inputsModifiable");
  const outMod = readBool(global0, "outputsModifiable");
  if (inMod === null) errors.push("pskb_global_inputsModifiable_missing");
  if (outMod === null) errors.push("pskb_global_outputsModifiable_missing");

  if (args.phase === "finalize") {
    if (inMod !== false) errors.push("pskb_inputs_must_be_locked_for_finalize");
    if (outMod !== false) errors.push("pskb_outputs_must_be_locked_for_finalize");
  } else {
    if (inMod !== true) errors.push("pskb_inputs_must_be_modifiable_for_offer_accept");
    if (outMod !== true) errors.push("pskb_outputs_must_be_modifiable_for_offer_accept");
  }

  const inputs0: any[] = Array.isArray((pskt0 as any)?.inputs) ? (pskt0 as any).inputs : [];
  if (inputs0.length < 1) {
    errors.push("pskb_missing_input0");
    return { ok: false, errors, warnings };
  }

  const input0 = inputs0[0];
  const probeKeys = ["redeemScript", "finalScriptSig", "finalSignatureScript", "signatureScript"];
  const probeHex = pickFirstHexField(input0, probeKeys);
  if (!probeHex || !isHexString(probeHex)) {
    errors.push("input0_script_hex_missing");
    return { ok: false, errors, warnings };
  }

  if (!containsHexNeedle(probeHex, HEX_KASPLEX_MARKER)) errors.push("krc20_kasplex_marker_missing_in_input0");
  if (!containsHexNeedle(probeHex, HEX_KRC20_PROTOCOL)) errors.push("krc20_protocol_field_missing_in_input0");

  if (args.phase === "offer") {
    if (containsHexNeedle(probeHex, HEX_KEY_TO)) errors.push("krc20_to_must_be_absent_in_offer_input0");
    if (!containsHexNeedle(probeHex, HEX_OP_LIST)) errors.push("krc20_op_list_missing_in_input0");
    if (!containsHexNeedle(probeHex, HEX_KEY_AMT)) errors.push("krc20_amt_missing_in_input0");

    if (args.kind === "tick_to_kas") {
      if (!containsHexNeedle(probeHex, HEX_KEY_TICK)) errors.push("krc20_tick_missing_in_input0");
    } else {
      if (!containsHexNeedle(probeHex, HEX_KEY_CA)) errors.push("krc20_ca_missing_in_input0");
    }

    const sh = readInputSighashType(input0);
    if (sh === null) {
      errors.push("input0_sighashType_missing");
    } else if (sh !== SighashType.SingleAnyOneCanPay) {
      errors.push("input0_sighashType_must_be_single_anyonecanpay");
    }

    warnings.push("open_v2_offer_surface_list");
  } else if (args.phase === "accept") {
    const expectedSendJsonHex = safeLowerHex(typeof args.expectedSendJsonHex === "string" ? args.expectedSendJsonHex : "");
    if (!expectedSendJsonHex) {
      errors.push("expected_send_json_hex_missing");
    } else if (!containsHexNeedle(probeHex, expectedSendJsonHex)) {
      errors.push("krc20_send_json_noncanonical_in_input0");
    }

    if (containsHexNeedle(probeHex, HEX_KEY_TO)) errors.push("krc20_to_must_be_absent_in_accept_input0");

    const sh = readInputSighashType(input0);
    if (sh === null) {
      errors.push("input0_sighashType_missing");
    } else if (sh !== SighashType.SingleAnyOneCanPay) {
      errors.push("input0_sighashType_must_be_single_anyonecanpay");
    }

    warnings.push("open_v2_accept_surface_send");
  } else if (args.phase === "finalize") {
    const expectedSendJsonHex = safeLowerHex(typeof args.expectedSendJsonHex === "string" ? args.expectedSendJsonHex : "");
    if (!expectedSendJsonHex) {
      errors.push("expected_send_json_hex_missing");
    } else if (!containsHexNeedle(probeHex, expectedSendJsonHex)) {
      errors.push("krc20_send_json_noncanonical_in_input0");
    }

    if (containsHexNeedle(probeHex, HEX_KEY_TO)) errors.push("krc20_to_must_be_absent_in_finalize_input0");

    const sh = readInputSighashType(input0);
    if (sh === null) {
      errors.push("input0_sighashType_missing");
    } else if (sh !== SighashType.SingleAnyOneCanPay) {
      errors.push("input0_sighashType_must_be_single_anyonecanpay");
    }

    if (inputs0.length < 2) errors.push("finalize_pskb_requires_taker_inputs");
    const outputs0: any[] = Array.isArray((pskt0 as any)?.outputs) ? (pskt0 as any).outputs : [];
    if (outputs0.length !== 4) {
      errors.push("finalize_pskb_requires_exactly_four_outputs");
    } else {
      const roles = args.expectedFinalizeRoles;
      if (!roles || typeof roles !== "object") {
        errors.push("finalize_expected_roles_missing");
      } else {
        const expected0 = normalizeScriptPublicKeyHex(roles.output0KasReceiverSpkHex);
        const expected1 = normalizeScriptPublicKeyHex(roles.output1TokenReceiverSpkHex);
        const expected2 = normalizeScriptPublicKeyHex(roles.output2MakerRefundSpkHex);
        const expected3 = normalizeScriptPublicKeyHex(roles.output3ChangeSpkHex);

        if (!expected0 || !expected1 || !expected2 || !expected3) {
          errors.push("finalize_expected_roles_missing");
        } else {
          const actual0 = normalizeScriptPublicKeyHex(outputs0[0]?.scriptPublicKey);
          const actual1 = normalizeScriptPublicKeyHex(outputs0[1]?.scriptPublicKey);
          const actual2 = normalizeScriptPublicKeyHex(outputs0[2]?.scriptPublicKey);
          const actual3 = normalizeScriptPublicKeyHex(outputs0[3]?.scriptPublicKey);

          if (actual0 !== expected0) errors.push("finalize_output0_must_be_maker_kas_receiver");
          if (actual1 !== expected1) errors.push("finalize_output1_must_be_taker_token_receiver");
          if (actual2 !== expected2) errors.push("finalize_output2_must_be_maker_refund");
          if (actual3 !== expected3) errors.push("finalize_output3_must_be_taker_kas_change");
        }
      }
    }

    warnings.push("open_v2_finalize_surface_send");
  } else {
    warnings.push("open_v2_non_offer_surface_pending_cb1");
  }

  return { ok: errors.length === 0, errors, warnings };
}

type AppConfig = {
  cn_url: string;
  cn_timeout_ms: number;
  fee_rate_min: number;

  // Optional: local dev shortcut to read CN policy from disk.
  // If empty, defaults to ../Compliance_Node/data/policy/recipient_policy.json
  cn_policy_path?: string;

  // NOTE (M3 Polish): Broker fee policy is sourced from the CN recipient_policy.json file.
  // Fee keys were removed from config.yaml to avoid drift/confusion.
};

let cachedConfig: AppConfig | null = null;

function parseSimpleYaml(raw: string): Record<string, string> {
  const out: Record<string, string> = {};
  const lines = String(raw || "").split(/\r?\n/);
  for (const lineRaw of lines) {
    const line = lineRaw.trim();
    if (!line || line.startsWith("#")) continue;
    const idx = line.indexOf(":");
    if (idx <= 0) continue;
    const key = line.slice(0, idx).trim();
    let val = line.slice(idx + 1).trim();
    if (!key) continue;
    if (val.startsWith("\"") && val.endsWith("\"") && val.length >= 2) {
      val = val.slice(1, -1);
    }
    out[key] = val;
  }
  return out;
}

function readAppConfig(repoRootPath: string): AppConfig {
  const p = path.join(repoRootPath, "config.yaml");
  if (!fs.existsSync(p)) {
    throw new Error("config_yaml_missing");
  }
  const raw = fs.readFileSync(p, "utf-8");
  const kv = parseSimpleYaml(raw);

  const cn_url = typeof kv.cn_url === "string" ? kv.cn_url.trim() : "";
  if (!cn_url) throw new Error("config_cn_url_missing");

  const cn_timeout_ms_raw = typeof kv.cn_timeout_ms === "string" ? kv.cn_timeout_ms.trim() : "";
  const cn_timeout_ms_parsed = Number(cn_timeout_ms_raw || "15000");
  const cn_timeout_ms = Number.isFinite(cn_timeout_ms_parsed)
    ? Math.max(1000, Math.floor(cn_timeout_ms_parsed))
    : 15000;

  const fee_rate_min_raw = typeof kv.fee_rate_min === "string" ? kv.fee_rate_min.trim() : "";
  const fee_rate_min_parsed = Number(fee_rate_min_raw || "2");
  const fee_rate_min = Number.isFinite(fee_rate_min_parsed)
    ? Math.max(1, Math.floor(fee_rate_min_parsed))
    : 2;

  const cn_policy_path = typeof kv.cn_policy_path === "string" ? kv.cn_policy_path.trim() : "";

  return {
    cn_url,
    cn_timeout_ms,
    fee_rate_min,
    cn_policy_path: cn_policy_path || undefined
  };
}

function getAppConfig(repoRootPath: string): AppConfig {
  if (!cachedConfig) cachedConfig = readAppConfig(repoRootPath);
  return cachedConfig;
}

function cnBaseUrl(repoRootPath: string): string {
  const cfg = getAppConfig(repoRootPath);
  return cfg.cn_url.replace(/\/+$/, "");
}

type CnFeeMode = "none" | "fixed_kas" | "percent_of_send";

type CnFeePolicyNetwork = {
  mode: CnFeeMode;
  fixed_kas: string;
  percent: string;
  feeDestination: string;
};

function parseDecimalToScaledInt(valueRaw: string, scale: number): bigint {
  const v = (valueRaw ?? "").trim();
  if (!v) return 0n;

  if (!/^[0-9]+(\.[0-9]+)?$/.test(v)) {
    throw new Error("invalid_decimal");
  }

  const [wholeRaw, fracRaw = ""] = v.split(".");
  const whole = BigInt(wholeRaw);
  const frac = (fracRaw + "0".repeat(scale)).slice(0, scale);
  const fracInt = frac.length ? BigInt(frac) : 0n;

  return whole * 10n ** BigInt(scale) + fracInt;
}

function percentToScaledInt(percentRaw: string, scale: number): bigint {
  return parseDecimalToScaledInt(percentRaw, scale);
}

function cnFeePolicyForNetwork(cfg: AppConfig, networkId: "mainnet" | "testnet-10"): CnFeePolicyNetwork {
  const defaultPath = path.resolve(repoRoot, "../Compliance_Node/data/policy/recipient_policy.json");
  const configured = typeof cfg.cn_policy_path === "string" ? cfg.cn_policy_path.trim() : "";
  const policyPath = configured
    ? (path.isAbsolute(configured) ? configured : path.resolve(repoRoot, configured))
    : defaultPath;

  if (!fs.existsSync(policyPath)) {
    throw new Error(`cn_policy_missing:${policyPath}`);
  }

  const raw = fs.readFileSync(policyPath, "utf-8");
  const policy: any = JSON.parse(raw);

  const fee = policy && policy.fee ? policy.fee : null;
  const modeRaw = fee && typeof fee.mode === "string" ? fee.mode.trim() : "fixed_kas";
  const mode: CnFeeMode =
    !modeRaw || modeRaw === "none"
      ? "none"
      : modeRaw === "fixed_kas"
        ? "fixed_kas"
        : modeRaw === "percent_of_send"
          ? "percent_of_send"
          : (() => {
              throw new Error(`cn_policy_invalid_fee_mode:${modeRaw}`);
            })();

  const fixed_kas = fee && typeof fee.fixed_kas === "string" ? fee.fixed_kas.trim() : "0.00";
  const percent = fee && typeof fee.percent === "string" ? fee.percent.trim() : "0.00";

  // Validate numeric shapes early (fail closed).
  if (mode === "fixed_kas") {
    const sompi = kaspaToSompi(fixed_kas);
    if (sompi === undefined || sompi < 0n) throw new Error("cn_policy_fee_fixed_kas_invalid");
  } else if (mode === "percent_of_send") {
    percentToScaledInt(percent, 8);
  }

  const destinations = fee && fee.destinations ? fee.destinations : null;
  const feeDestination =
    destinations && typeof destinations[networkId] === "string" ? String(destinations[networkId]).trim() : "";

  return { mode, fixed_kas, percent, feeDestination };
}

function cnRecipientGatesFromPolicy(cfg: AppConfig): { regulated_cas: string[]; recipient_allowlist: string[] } {
  const defaultPath = path.resolve(repoRoot, "../Compliance_Node/data/policy/recipient_policy.json");
  const configured = typeof cfg.cn_policy_path === "string" ? cfg.cn_policy_path.trim() : "";
  const policyPath = configured
    ? (path.isAbsolute(configured) ? configured : path.resolve(repoRoot, configured))
    : defaultPath;

  if (!fs.existsSync(policyPath)) {
    throw new Error(`cn_policy_missing:${policyPath}`);
  }

  const raw = fs.readFileSync(policyPath, "utf-8");
  const policy: any = JSON.parse(raw);

  const regulatedRaw = Array.isArray(policy && policy.regulated_cas) ? policy.regulated_cas : [];
  const regulated_cas = regulatedRaw
    .map((x: any) => safeLowerHex(x))
    .filter((h: string) => /^[0-9a-f]{64}$/.test(h));

  const allowRaw = Array.isArray(policy && policy.recipient_allowlist) ? policy.recipient_allowlist : [];
  const recipient_allowlist = allowRaw.map((x: any) => String(x || "").trim()).filter((s: string) => Boolean(s));

  return { regulated_cas, recipient_allowlist };
}

function cnFeeSompiForSendAmount(policy: CnFeePolicyNetwork, sendAmountSompi: bigint): bigint {
  if (policy.mode === "none") return 0n;

  if (policy.mode === "fixed_kas") {
    const sompi = kaspaToSompi(policy.fixed_kas);
    if (sompi === undefined || sompi < 0n) throw new Error("cn_policy_fee_fixed_kas_invalid");
    return sompi;
  }

  const percentScaled = percentToScaledInt(policy.percent, 8);
  const denom = 100n * 10n ** 8n; // percent scaled by 1e8
  return denom === 0n ? 0n : (sendAmountSompi * percentScaled) / denom;
}

function maxSendableSompiForFeePolicy(balanceSompi: bigint, policy: CnFeePolicyNetwork): bigint {
  if (balanceSompi <= 0n) return 0n;

  if (policy.mode === "none") return balanceSompi;

  if (policy.mode === "fixed_kas") {
    const feeSompi = cnFeeSompiForSendAmount(policy, 0n);
    return feeSompi > 0n ? (balanceSompi > feeSompi ? balanceSompi - feeSompi : 0n) : balanceSompi;
  }

  const percentScaled = percentToScaledInt(policy.percent, 8);
  const denom = 100n * 10n ** 8n; // percent scaled by 1e8
  const base = denom + percentScaled;
  let amt = base === 0n ? 0n : (balanceSompi * denom) / base;

  // Conservative adjust to satisfy: amt + fee(amt) <= balance
  for (let i = 0; i < 3; i++) {
    const feeSompi = cnFeeSompiForSendAmount(policy, amt);
    if (amt + feeSompi <= balanceSompi) break;
    amt = amt > 0n ? amt - 1n : 0n;
  }

  return amt;
}

async function bcwOpenSwapFinalizeSubmit(params: {
  repoRootPath: string;
  intent: unknown;
  authSignature: string;
  txSafeJson: string;
}): Promise<{ ok: boolean; status: number; data: any }> {
  const { repoRootPath, intent, authSignature, txSafeJson } = params;
  const cfg = getAppConfig(repoRootPath);
  const cnUrl = cnBaseUrl(repoRootPath);
  const adminToken = String(process.env.TD_ADMIN_TOKEN || "").trim();

  if (!adminToken) {
    return { ok: false, status: 500, data: { ok: false, reason: "td_admin_token_missing" } };
  }

  const url = `${cnUrl}/api/cn/bcw/open-swap/finalize`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), cfg.cn_timeout_ms);

  try {
    const r = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        "x-td-admin-token": adminToken
      },
      body: JSON.stringify({
        intent,
        auth_signature: authSignature,
        tx_safe_json: txSafeJson
      }),
      signal: controller.signal
    });

    const data = await r.json().catch(() => null);
    return { ok: r.ok && data && data.ok === true, status: r.status, data };
  } catch (err) {
    const e: any = err;
    const name = e && typeof e.name === "string" ? e.name : "";
    const msg = e && typeof e.message === "string" ? e.message : String(e);
    const reason = name === "AbortError" ? "cn_timeout" : "cn_fetch_failed";
    return { ok: false, status: 502, data: { ok: false, reason, error: msg, url } };
  } finally {
    clearTimeout(timeout);
  }
}

