function kasplexBaseUrl(network: string) {
  const appNetworkKey = normalizeAppNetworkKey(network) ?? "tn10";
  return kasplexBaseUrlFromAppNetworkKey(appNetworkKey);
}

function kasplexAmount(balance: unknown, dec: unknown): number {
  const balStr = typeof balance === "string" ? balance : String(balance ?? "0");
  const decStr = typeof dec === "string" ? dec : String(dec ?? "0");

  let d = Number.parseInt(decStr, 10);
  if (!Number.isFinite(d) || d < 0) d = 0;

  try {
    const iv = BigInt(balStr);
    if (d === 0) return Number(iv.toString());

    const scale = 10n ** BigInt(d);
    const whole = iv / scale;
    const frac = iv % scale;

    const fracTrimmed = frac
      .toString()
      .padStart(d, "0")
      .replace(/0+$/, "");

    const s = fracTrimmed ? `${whole.toString()}.${fracTrimmed}` : whole.toString();
    const n = Number(s);
    return Number.isFinite(n) ? n : 0;
  } catch {
    return 0;
  }
}

type CanonicalKrc20TokenMetadata = {
  provider: "kasplex";
  networkId: "mainnet" | "tn10";
  lookup: {
    kind: "ca" | "tick";
    value: string;
    found: boolean;
    foundBy: "ca" | "tick" | null;
  };
  identity: {
    ca: string | null;
    tick: string | null;
    name: string | null;
    decimals: number | null;
  };
  issuance: {
    maxRaw: string | null;
    limitRaw: string | null;
    preRaw: string | null;
    toAddress: string | null;
    mod: string | null;
    state: string | null;
  };
  stats: {
    mintedRaw: string | null;
    burnedRaw: string | null;
    holderTotal: string | null;
    transferTotal: string | null;
    mintTotal: string | null;
    opScoreAdd: string | null;
    opScoreMod: string | null;
    hashRev: string | null;
    mtsAdd: string | null;
  };
  fetchedAtMs: number;
};

type ResolveKrc20TokenMetadataInput = {
  networkId: "mainnet" | "tn10";
  lookup: {
    kind: "ca" | "tick";
    value: string;
  };
  options?: {
    timeoutMs?: number;
  };
};

type ResolveKrc20TokenMetadataResult =
  | { ok: true; data: CanonicalKrc20TokenMetadata }
  | {
      ok: false;
      reason:
        | "invalid_input"
        | "unsupported_network"
        | "provider_timeout"
        | "provider_http_error"
        | "provider_parse_error"
        | "not_found"
        | "provider_shape_invalid";
      provider: "kasplex";
      networkId: "mainnet" | "tn10" | null;
      lookup: {
        kind: "ca" | "tick" | null;
        value: string;
      };
      status?: number | null;
      message?: string | null;
    };

function kasplexStringOrNull(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

async function resolveKrc20TokenMetadata(
  input: ResolveKrc20TokenMetadataInput
): Promise<ResolveKrc20TokenMetadataResult> {
  const networkId = input?.networkId === "mainnet" || input?.networkId === "tn10" ? input.networkId : null;
  const lookupKind = input?.lookup?.kind === "ca" || input?.lookup?.kind === "tick" ? input.lookup.kind : null;
  const lookupValue = typeof input?.lookup?.value === "string" ? input.lookup.value.trim() : "";

  if (!networkId) {
    return {
      ok: false,
      reason: "unsupported_network",
      provider: "kasplex",
      networkId: null,
      lookup: { kind: lookupKind, value: lookupValue }
    };
  }

  if (!lookupKind || !lookupValue) {
    return {
      ok: false,
      reason: "invalid_input",
      provider: "kasplex",
      networkId,
      lookup: { kind: lookupKind, value: lookupValue }
    };
  }

  const normalizedLookupValue = lookupKind === "ca" ? lookupValue.toLowerCase() : lookupValue;
  const base = kasplexBaseUrl(networkId);
  const url = `${base}/krc20/token/${encodeURIComponent(normalizedLookupValue)}`;
  const controller = new AbortController();
  const timeoutMs = Number.isFinite(input?.options?.timeoutMs)
    ? Math.max(1, Math.trunc(Number(input.options?.timeoutMs)))
    : 8000;
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const r = await fetch(url, {
      headers: { Accept: "application/json" },
      signal: controller.signal
    });

    if (!r.ok) {
      const message = await r.text().catch(() => "");
      return {
        ok: false,
        reason: "provider_http_error",
        provider: "kasplex",
        networkId,
        lookup: { kind: lookupKind, value: normalizedLookupValue },
        status: r.status,
        message: message || r.statusText || null
      };
    }

    let data: any;
    try {
      data = await r.json();
    } catch (err) {
      return {
        ok: false,
        reason: "provider_parse_error",
        provider: "kasplex",
        networkId,
        lookup: { kind: lookupKind, value: normalizedLookupValue },
        status: r.status,
        message: err instanceof Error ? err.message : String(err)
      };
    }

    const result = data?.result;
    const token =
      result && typeof result === "object" && !Array.isArray(result)
        ? result
        : Array.isArray(result) && result.length && result[0] && typeof result[0] === "object"
          ? result[0]
          : null;

    if (!token) {
      return {
        ok: false,
        reason: "not_found",
        provider: "kasplex",
        networkId,
        lookup: { kind: lookupKind, value: normalizedLookupValue },
        status: r.status,
        message: null
      };
    }

    const ca = kasplexStringOrNull(token.ca);

    const decRaw = token.dec ?? token.decimal;
    const decimals = decRaw !== undefined && /^[0-9]+$/.test(String(decRaw).trim())
      ? Number.parseInt(String(decRaw).trim(), 10)
      : null;

    return {
      ok: true,
      data: {
        provider: "kasplex",
        networkId,
        lookup: {
          kind: lookupKind,
          value: normalizedLookupValue,
          found: true,
          foundBy: lookupKind
        },
        identity: {
          ca: ca || null,
          tick: kasplexStringOrNull(token.tick),
          name: kasplexStringOrNull(token.name),
          decimals
        },
        issuance: {
          maxRaw: kasplexStringOrNull(token.max),
          limitRaw: kasplexStringOrNull(token.lim),
          preRaw: kasplexStringOrNull(token.pre),
          toAddress: kasplexStringOrNull(token.to),
          mod: kasplexStringOrNull(token.mod),
          state: kasplexStringOrNull(token.state)
        },
        stats: {
          mintedRaw: kasplexStringOrNull(token.minted),
          burnedRaw: kasplexStringOrNull(token.burned),
          holderTotal: kasplexStringOrNull(token.holderTotal),
          transferTotal: kasplexStringOrNull(token.transferTotal),
          mintTotal: kasplexStringOrNull(token.mintTotal),
          opScoreAdd: kasplexStringOrNull(token.opScoreAdd),
          opScoreMod: kasplexStringOrNull(token.opScoreMod),
          hashRev: kasplexStringOrNull(token.hashRev),
          mtsAdd: kasplexStringOrNull(token.mtsAdd)
        },
        fetchedAtMs: Date.now()
      }
    };
  } catch (err) {
    const name = err && typeof (err as any).name === "string" ? String((err as any).name) : "";
    const message = err instanceof Error ? err.message : String(err);
    return {
      ok: false,
      reason: name === "AbortError" ? "provider_timeout" : "provider_http_error",
      provider: "kasplex",
      networkId,
      lookup: { kind: lookupKind, value: normalizedLookupValue },
      message
    };
  } finally {
    clearTimeout(timeout);
  }
}

async function kasplexGetAddressTokenList(network: string, address: string) {
  const base = kasplexBaseUrl(network);
  const tokens: Record<string, number> = {};
  const token_dec: Record<string, number> = {};
  const issue: Array<{ ca: string; name?: string | null; amount: number; dec?: number }> = [];

  let next: string | null = null;
  let pages = 0;

  while (pages < 20) {
    const url =
      next && next.length
        ? `${base}/krc20/address/${address}/tokenlist?next=${encodeURIComponent(next)}`
        : `${base}/krc20/address/${address}/tokenlist`;

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 8000);

    try {
      const r = await fetch(url, {
        headers: { Accept: "application/json" },
        signal: controller.signal
      });

      if (!r.ok) {
        const txt = await r.text().catch(() => "");
        throw new Error(`kasplex_http_${r.status}: ${txt || r.statusText}`);
      }

      const data: any = await r.json();
      const result = Array.isArray(data?.result) ? data.result : [];

      for (const it of result) {
        if (!it || typeof it !== "object") continue;

        const decRaw = (it as any).dec ?? (it as any).decimal ?? "0";
        const balRaw = (it as any).balance ?? "0";
        const amt = kasplexAmount(balRaw, decRaw);

        const tick = typeof (it as any).tick === "string" ? (it as any).tick : "";
        const ca = typeof (it as any).ca === "string" ? (it as any).ca : "";

        if (tick) {
          const t = tick.toUpperCase();
          tokens[t] = amt;
          token_dec[t] = Number.parseInt(String(decRaw), 10) || 0;
          continue;
        }

        if (ca) {
          issue.push({
            ca,
            name: typeof (it as any).name === "string" ? (it as any).name : null,
            amount: amt,
            dec: Number.parseInt(String(decRaw), 10) || 0
          });
          continue;
        }
      }

      next = typeof data?.next === "string" && data.next ? data.next : null;
      if (!next) break;
      pages += 1;
    } finally {
      clearTimeout(timeout);
    }
  }

  const metadataNetworkId = network === "mainnet" ? "mainnet" : "tn10";

  // Enrich Issue-Mode entries with missing name/dec (Kasplex token info endpoint)
  for (const it of issue) {
    if (!it || typeof it !== "object") continue;
    if (it.name) continue;
    const ca = it.ca;
    if (!ca) continue;

    const metadata = await resolveKrc20TokenMetadata({
      networkId: metadataNetworkId,
      lookup: { kind: "ca", value: ca }
    });
    if (!metadata.ok) continue;

    if (metadata.data.identity.name) it.name = metadata.data.identity.name;
    if (typeof metadata.data.identity.decimals === "number") it.dec = metadata.data.identity.decimals;
  }

  return { source: base, tokens, token_dec, issue };
}

const PRO_PACKAGE_LABEL = "PRO";
const PRO_PACKAGE_CA = "";

async function requireMainnetLicenseOrReject(args: {
  networkId: "mainnet" | "testnet-10";
  userId: string;
}): Promise<
  | { ok: true }
  | { ok: false; status: number; reason: string; tick: string; ca: string; error?: string }
> {
  const net = args.networkId;
  if (net !== "mainnet") return { ok: true };

  const userId = String(args.userId || "").trim();
  if (!userId) {
    return { ok: false, status: 500, reason: "license_missing_user_id", tick: PRO_PACKAGE_LABEL, ca: PRO_PACKAGE_CA };
  }

  try {
    const status = calculateEntitlementPackageForUserIds(repoRoot, "PRO", [userId]);
    if (status.active || status.in_grace) {
      clearLicenseLocation(repoRoot, userId);
      return { ok: true };
    }
  } catch (e) {
    return {
      ok: false,
      status: 500,
      reason: "license_query_failed",
      tick: PRO_PACKAGE_LABEL,
      ca: PRO_PACKAGE_CA,
      error: String(e)
    };
  }

  clearLicenseLocation(repoRoot, userId);
  return { ok: false, status: 403, reason: "license_required", tick: PRO_PACKAGE_LABEL, ca: PRO_PACKAGE_CA };
}

app.get("/api/wallet/holdings", async (req, res) => {
  let rpc: RpcClient | null = null;

  try {
    await ensureKaspaReady(repoRoot);

    const strict =
      req.query.strict === "1" ||
      req.query.strict === "true" ||
      req.query.strict === "yes";

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      if (strict) {
        return res.status(409).json({ ok: false, reason: "no_active_wallet" });
      }
      return res.json({ kas: 0, address: "", tokens: {}, issue: [], krc20: { ok: false, reason: "no_active_wallet" } });
    }

    const appNetworkKey = appNetworkKeyFromWalletNetwork(active.network);
    const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKey);
    rpc = await getSharedRpc(networkId);

    const balanceTimeoutMs = defaultBalanceLookupTimeoutMsFromAppNetworkKey(appNetworkKey);

    const readBalanceOnce = async (client: RpcClient): Promise<any> => {
      let balanceTimer: ReturnType<typeof setTimeout> | null = null;
      try {
        const balancePromise = client.getBalanceByAddress({ address: active.address0 });
        const timeoutPromise = new Promise<never>((_, reject) => {
          balanceTimer = setTimeout(() => reject(new Error("balance_lookup_timeout")), balanceTimeoutMs);
        });
        const r = await Promise.race([balancePromise, timeoutPromise]);
        return r.balance;
      } finally {
        if (balanceTimer) clearTimeout(balanceTimer);
      }
    };

    let sompi: any;
    try {
      sompi = await readBalanceOnce(rpc);
    } catch {
      sharedRpcByNetworkId.delete(networkId);
      rpcConnectInFlightByNetworkId.delete(networkId);
      rpc = await getSharedRpc(networkId);
      sompi = await readBalanceOnce(rpc);
    }

    const kas = Number(sompi) / 100000000;

    let tokens: Record<string, number> = {};
    let token_dec: Record<string, number> = {};
    let issue: Array<{ ca: string; name?: string | null; amount: number; dec?: number }> = [];
    let krc20: any = null;

    try {
      const out = await kasplexGetAddressTokenList(active.network, active.address0);
      tokens = out.tokens;
      issue = out.issue;
      token_dec = out.token_dec;
      krc20 = { ok: true, source: out.source };
    } catch (e) {
      krc20 = { ok: false, source: kasplexBaseUrl(active.network), error: String(e) };
    }

    const holdingsResponse: any = {
      wid: active.id,
      kas,
      sompi: sompi.toString(),
      address: active.address0,
      network: active.network,
      networkId,
      tokens,
      token_dec,
      issue,
      krc20
    };

    await attachTrackedOmaL1HoldingsToResponse({
      repoRootPath: repoRoot,
      userId,
      activeWallet: active,
      networkId,
      holdings: holdingsResponse
    });

    return res.json(holdingsResponse);
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "holdings_failed",
      error: String(err)
    });
  } finally {
    // keep shared RPC connected
  }
});

app.get("/api/wallet/status", async (_req, res) => {
  try {
    await ensureKaspaReady(repoRoot);

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      return res.json({
        ok: false,
        reason: "no_active_wallet",
        sdk_version: sdkVersion()
      });
    }

    return res.json({
      ok: true,
      wallet_id: active.id,
      wallet_type: active.wallet_type,
      network: active.network,
      address0: active.address0,
      state: active.state,
      custody_model: active.custody_model || null,
      broker_custody_key_ref: active.broker_custody_key_ref || null,
      user_auth_pubkey: active.user_auth_pubkey || null,
      sdk_version: sdkVersion(),
      cn_timeout_ms: getAppConfig(repoRoot).cn_timeout_ms
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "wasm_init_failed",
      error: String(err)
    });
  }
});

