function covenantPrintable(value: any): string | null {
  if (value === null || value === undefined) return null;
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  if (typeof value.toString === "function" && value.toString !== Object.prototype.toString) {
    return value.toString();
  }
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function covenantEntriesFromResponse(response: any): any[] {
  if (Array.isArray(response)) return response;
  if (response && Array.isArray(response.entries)) return response.entries;
  if (response && Array.isArray(response.utxos)) return response.utxos;
  if (response && Array.isArray(response.result)) return response.result;
  return [];
}

function covenantInspectionEntryAmountSortValue(reference: any): bigint {
  const amountText = covenantAmountSompiFromReference(reference);
  if (!amountText || !/^[0-9]+$/.test(amountText)) return -1n;
  try {
    return BigInt(amountText);
  } catch {
    return -1n;
  }
}

function covenantInspectionEntryOutpointSortValue(reference: any): string {
  const outpoint = covenantOutpointFromReference(reference);
  return String(outpoint.text || outpoint.transaction_id || "").trim().toLowerCase();
}

function sortCovenantInspectionEntries(entries: any[], sortMode: string): any[] {
  const normalizedSortMode = sortMode || "amount_desc_outpoint";
  const sortable = entries.map((entry, originalIndex) => ({
    entry,
    originalIndex,
    amount_sompi_sort: covenantInspectionEntryAmountSortValue(entry),
    outpoint_sort: covenantInspectionEntryOutpointSortValue(entry)
  }));

  sortable.sort((a, b) => {
    if (normalizedSortMode === "utxo_asc") {
      const outpointCompare = a.outpoint_sort.localeCompare(b.outpoint_sort);
      return outpointCompare || a.originalIndex - b.originalIndex;
    }

    if (a.amount_sompi_sort !== b.amount_sompi_sort) {
      return normalizedSortMode === "amount_asc_outpoint"
        ? (a.amount_sompi_sort < b.amount_sompi_sort ? -1 : 1)
        : (a.amount_sompi_sort > b.amount_sompi_sort ? -1 : 1);
    }

    const outpointCompare = a.outpoint_sort.localeCompare(b.outpoint_sort);
    return outpointCompare || a.originalIndex - b.originalIndex;
  });

  return sortable.map((item) => item.entry);
}

function covenantReferenceEntry(reference: any): any | null {
  return reference && typeof reference === "object" && reference.entry ? reference.entry : null;
}

function covenantSafeDebugType(value: any): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

function covenantSafeDebugKeys(value: any, limit = 80): string[] {
  if (!value || typeof value !== "object") return [];
  return Object.keys(value).sort().slice(0, limit);
}

function covenantDebugKeyIsUnsafe(key: string): boolean {
  return /private|priv|seed|mnemonic|passphrase|signatureScript|signature_script|signed_safe_json|signedTransaction|signed_transaction|auth|secret|password|session|submit_token|api[_-]?key|cookie/i.test(key);
}

function covenantSafeDebugPreview(value: any): any {
  if (value === null || value === undefined) return null;
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "string") return value.length > 160 ? `${value.slice(0, 160)}...` : value;
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (Array.isArray(value)) {
    return {
      type: "array",
      length: value.length,
      item_types: value.slice(0, 8).map((item) => covenantSafeDebugType(item))
    };
  }
  if (typeof value === "object") {
    return {
      type: "object",
      keys: covenantSafeDebugKeys(value, 40)
    };
  }
  return covenantPrintable(value);
}

function covenantNestedDebugKeys(label: string, value: any): Array<{ path: string; type: string; keys: string[]; length?: number }> {
  if (!value || typeof value !== "object") return [];
  return Object.entries(value)
    .filter(([key, child]) => !covenantDebugKeyIsUnsafe(key) && child && typeof child === "object")
    .slice(0, 60)
    .map(([key, child]) => ({
      path: `${label}.${key}`,
      type: covenantSafeDebugType(child),
      keys: covenantSafeDebugKeys(child, 50),
      ...(Array.isArray(child) ? { length: child.length } : {})
    }));
}

function covenantRelatedDebugPreviews(label: string, value: any): Array<{ path: string; type: string; preview: any }> {
  if (!value || typeof value !== "object") return [];
  return Object.entries(value)
    .filter(([key]) => /covenant|state|script|public|amount|owner|issuer|supply|schema|role|payload|data|token|address/i.test(key))
    .filter(([key]) => !covenantDebugKeyIsUnsafe(key))
    .slice(0, 60)
    .map(([key, child]) => ({
      path: `${label}.${key}`,
      type: covenantSafeDebugType(child),
      preview: covenantSafeDebugPreview(child)
    }));
}

function covenantSafeDebugHashableStringPreview(value: string): any {
  return {
    type: "string",
    length: value.length,
    sha256: createHash("sha256").update(value).digest("hex"),
    preview: value.length > 160 ? `${value.slice(0, 160)}...` : value
  };
}

function covenantSafeAccessorPreview(value: any): any {
  if (value === null || value === undefined) return null;
  if (typeof value === "bigint") return { type: "bigint", value: value.toString() };
  if (typeof value === "string") return covenantSafeDebugHashableStringPreview(value);
  if (typeof value === "number" || typeof value === "boolean") return { type: typeof value, value };
  if (Array.isArray(value)) {
    return {
      type: "array",
      length: value.length,
      item_types: value.slice(0, 8).map((item) => covenantSafeDebugType(item))
    };
  }
  if (typeof value === "object") {
    const keys = covenantSafeDebugKeys(value, 30);
    const fields: Record<string, any> = {};
    for (const key of keys.slice(0, 20)) {
      if (covenantDebugKeyIsUnsafe(key)) continue;
      try {
        fields[key] = covenantSafeDebugPreview(value[key]);
      } catch (err: any) {
        fields[key] = { error: err?.message || String(err) };
      }
    }
    return { type: "object", keys, fields };
  }
  return { type: covenantSafeDebugType(value), preview: covenantPrintable(value) };
}

function covenantPrototypeDebug(value: any): { present: boolean; type: string; prototype_keys: string[] } {
  if (!value || typeof value !== "object") {
    return { present: false, type: covenantSafeDebugType(value), prototype_keys: [] };
  }
  try {
    const proto = Object.getPrototypeOf(value);
    return {
      present: !!proto,
      type: covenantSafeDebugType(value),
      prototype_keys: proto ? Object.getOwnPropertyNames(proto).sort().slice(0, 120) : []
    };
  } catch (err: any) {
    return { present: false, type: covenantSafeDebugType(value), prototype_keys: [`ERROR: ${err?.message || String(err)}`] };
  }
}

function covenantAccessorProbe(pathName: string, getter: () => any): { path: string; ok: boolean; type?: string; preview?: any; error?: string } {
  try {
    const value = getter();
    return {
      path: pathName,
      ok: true,
      type: covenantSafeDebugType(value),
      preview: covenantSafeAccessorPreview(value)
    };
  } catch (err: any) {
    return { path: pathName, ok: false, error: err?.message || String(err) };
  }
}

function covenantMethodProbe(pathName: string, target: any, methodName: string): { path: string; ok: boolean; skipped?: boolean; type?: string; preview?: any; error?: string } {
  try {
    const method = target?.[methodName];
    if (typeof method !== "function") {
      return { path: `${pathName}.${methodName}()`, ok: false, skipped: true, error: "method_not_present" };
    }
    const value = method.call(target);
    return {
      path: `${pathName}.${methodName}()`,
      ok: true,
      type: covenantSafeDebugType(value),
      preview: covenantSafeAccessorPreview(value)
    };
  } catch (err: any) {
    return { path: `${pathName}.${methodName}()`, ok: false, error: err?.message || String(err) };
  }
}

function covenantKnownAccessorProbes(label: string, value: any): any[] {
  const probes: any[] = [
    covenantMethodProbe(label, value, "toJSON"),
    covenantMethodProbe(label, value, "toString")
  ];

  for (const key of [
    "entry",
    "amount",
    "scriptPublicKey",
    "blockDaaScore",
    "isCoinbase",
    "covenantId",
    "address",
    "outpoint",
    "version",
    "script"
  ]) {
    probes.push(covenantAccessorProbe(`${label}.${key}`, () => value?.[key]));
  }

  if (value?.scriptPublicKey) {
    const spk = value.scriptPublicKey;
    probes.push(covenantMethodProbe(`${label}.scriptPublicKey`, spk, "toJSON"));
    probes.push(covenantMethodProbe(`${label}.scriptPublicKey`, spk, "toString"));
    probes.push(covenantAccessorProbe(`${label}.scriptPublicKey.version`, () => spk.version));
    probes.push(covenantAccessorProbe(`${label}.scriptPublicKey.script`, () => spk.script));
    probes.push(covenantMethodProbe(`${label}.scriptPublicKey`, spk, "version"));
    probes.push(covenantMethodProbe(`${label}.scriptPublicKey`, spk, "script"));
  }

  return probes;
}

function covenantCallOptionalNoArg(target: any, methodName: string): any {
  const method = target?.[methodName];
  if (typeof method !== "function") return undefined;
  return method.call(target);
}

function covenantScriptPublicKeyPublicFields(reference: any): {
  script_public_key_present: boolean;
  script_public_key_source: string | null;
  script_public_key_script: string | null;
  script_public_key_version: number | null;
  script_public_key_json_sha256: string | null;
} {
  const entry = covenantReferenceEntry(reference);
  const source = entry?.scriptPublicKey ? "reference.entry.scriptPublicKey" : reference?.scriptPublicKey ? "reference.scriptPublicKey" : null;
  const scriptPublicKey = entry?.scriptPublicKey || reference?.scriptPublicKey || null;
  if (!scriptPublicKey) {
    return {
      script_public_key_present: false,
      script_public_key_source: null,
      script_public_key_script: null,
      script_public_key_version: null,
      script_public_key_json_sha256: null
    };
  }

  let json: any = null;
  try {
    json = covenantCallOptionalNoArg(scriptPublicKey, "toJSON") || null;
  } catch {
    json = null;
  }

  let scriptValue: any = null;
  let versionValue: any = null;
  try {
    const propertyValue = scriptPublicKey.script;
    const methodValue = covenantCallOptionalNoArg(scriptPublicKey, "script");
    scriptValue = json?.script ?? (typeof propertyValue === "function" ? methodValue : propertyValue) ?? methodValue;
  } catch {
    scriptValue = json?.script ?? null;
  }

  try {
    const propertyValue = scriptPublicKey.version;
    const methodValue = covenantCallOptionalNoArg(scriptPublicKey, "version");
    versionValue = json?.version ?? (typeof propertyValue === "function" ? methodValue : propertyValue) ?? methodValue;
  } catch {
    versionValue = json?.version ?? null;
  }

  const script = covenantPrintable(scriptValue);
  const versionNumber = Number(versionValue);
  const version = Number.isFinite(versionNumber) ? versionNumber : null;
  const jsonForHash = script && version !== null ? JSON.stringify({ script, version }) : null;

  return {
    script_public_key_present: true,
    script_public_key_source: source,
    script_public_key_script: script,
    script_public_key_version: version,
    script_public_key_json_sha256: jsonForHash ? createHash("sha256").update(jsonForHash).digest("hex") : null
  };
}

function covenantAddressFromReference(reference: any, networkId: string): string | null {
  const entry = covenantReferenceEntry(reference);
  const scriptPublicKey = entry?.scriptPublicKey || reference?.scriptPublicKey || null;
  if (!scriptPublicKey) return null;
  try {
    const address = addressFromScriptPublicKey(scriptPublicKey, networkId);
    return address ? address.toString() : null;
  } catch {
    return null;
  }
}

function covenantUtxoEntryShapeDebug(reference: any): any {
  const entry = covenantReferenceEntry(reference);
  return {
    debug_kind: "oma_covenant_utxo_entry_shape_debug_v1",
    safety: {
      read_only: true,
      private_key_included: false,
      signature_script_included: false,
      signed_transaction_included: false,
      submit_token_included: false,
      signing_enabled: false,
      broadcasting_enabled: false,
      minting_enabled: false
    },
    prototype_probe: {
      reference: covenantPrototypeDebug(reference),
      entry: covenantPrototypeDebug(entry),
      reference_script_public_key: covenantPrototypeDebug(reference?.scriptPublicKey),
      entry_script_public_key: covenantPrototypeDebug(entry?.scriptPublicKey),
      reference_outpoint: covenantPrototypeDebug(reference?.outpoint),
      entry_outpoint: covenantPrototypeDebug(entry?.outpoint),
      reference_address: covenantPrototypeDebug(reference?.address),
      entry_address: covenantPrototypeDebug(entry?.address)
    },
    accessor_probe: {
      reference: covenantKnownAccessorProbes("reference", reference),
      entry: covenantKnownAccessorProbes("reference.entry", entry)
    },
    reference: {
      type: covenantSafeDebugType(reference),
      keys: covenantSafeDebugKeys(reference),
      nested_keys: covenantNestedDebugKeys("reference", reference),
      covenant_related_previews: covenantRelatedDebugPreviews("reference", reference)
    },
    entry: {
      present: !!entry,
      type: covenantSafeDebugType(entry),
      keys: covenantSafeDebugKeys(entry),
      nested_keys: covenantNestedDebugKeys("reference.entry", entry),
      covenant_related_previews: covenantRelatedDebugPreviews("reference.entry", entry)
    },
    covenant_probe: {
      reference_covenant_id_present: reference?.covenantId !== null && reference?.covenantId !== undefined,
      entry_covenant_id_present: entry?.covenantId !== null && entry?.covenantId !== undefined,
      entry_covenant_id_text: covenantPrintable(entry?.covenantId),
      reference_covenant_present: reference?.covenant !== null && reference?.covenant !== undefined,
      entry_covenant_present: entry?.covenant !== null && entry?.covenant !== undefined,
      reference_covenant_keys: covenantSafeDebugKeys(reference?.covenant, 40),
      entry_covenant_keys: covenantSafeDebugKeys(entry?.covenant, 40)
    },
    script_public_key_probe: {
      reference_script_public_key_present: reference?.scriptPublicKey !== null && reference?.scriptPublicKey !== undefined,
      entry_script_public_key_present: entry?.scriptPublicKey !== null && entry?.scriptPublicKey !== undefined,
      reference_script_public_key_type: covenantSafeDebugType(reference?.scriptPublicKey),
      entry_script_public_key_type: covenantSafeDebugType(entry?.scriptPublicKey),
      reference_script_public_key_preview: covenantSafeDebugPreview(reference?.scriptPublicKey),
      entry_script_public_key_preview: covenantSafeDebugPreview(entry?.scriptPublicKey)
    }
  };
}

function covenantIdFromReference(reference: any): { present: boolean; value: string | null; path: string; direct_top_level_ignored: boolean } {
  const entry = covenantReferenceEntry(reference);
  const canonical = entry ? entry.covenantId : undefined;

  if (canonical !== null && canonical !== undefined) {
    return {
      present: true,
      value: covenantPrintable(canonical),
      path: "reference.entry.covenantId",
      direct_top_level_ignored: !!(reference && reference.covenantId !== undefined)
    };
  }

  return {
    present: false,
    value: null,
    path: "reference.entry.covenantId",
    direct_top_level_ignored: !!(reference && reference.covenantId !== undefined)
  };
}

function covenantAmountSompiFromReference(reference: any): string | null {
  const entry = covenantReferenceEntry(reference);
  const candidates = [
    reference && reference.amount,
    entry && entry.amount,
    reference && reference.utxo && reference.utxo.amount,
    reference && reference.utxoEntry && reference.utxoEntry.amount
  ];

  for (const value of candidates) {
    const text = covenantPrintable(value);
    if (text !== null && text !== undefined) return text;
  }
  return null;
}

function covenantBlockDaaScoreFromReference(reference: any): string | null {
  const entry = covenantReferenceEntry(reference);
  const candidates = [
    reference && reference.blockDaaScore,
    entry && entry.blockDaaScore,
    reference && reference.utxo && reference.utxo.blockDaaScore,
    reference && reference.utxoEntry && reference.utxoEntry.blockDaaScore
  ];

  for (const value of candidates) {
    const text = covenantPrintable(value);
    if (text !== null && text !== undefined && /^[0-9]+$/.test(text)) return text;
  }
  return null;
}

function covenantOutpointFromReference(reference: any): { transaction_id: string | null; index: number | null; text: string | null } {
  const entry = covenantReferenceEntry(reference);
  const candidates = [
    reference && reference.outpoint,
    entry && entry.outpoint,
    reference && reference.utxo && reference.utxo.outpoint,
    reference && reference.utxoEntry && reference.utxoEntry.outpoint
  ];

  for (const outpoint of candidates) {
    if (!outpoint) continue;

    if (typeof outpoint === "string") {
      const parts = outpoint.split(":");
      if (parts.length === 2) {
        const idx = Number(parts[1]);
        return { transaction_id: parts[0] || null, index: Number.isFinite(idx) ? idx : null, text: outpoint };
      }
      return { transaction_id: outpoint, index: null, text: outpoint };
    }

    const transactionId = covenantPrintable(outpoint.transactionId ?? outpoint.transaction_id ?? outpoint.txid);
    const rawIndex = outpoint.index ?? outpoint.outputIndex ?? outpoint.output_index;
    const index = rawIndex === null || rawIndex === undefined ? null : Number(rawIndex);
    const safeIndex = Number.isFinite(index) ? index : null;

    if (transactionId || safeIndex !== null) {
      return {
        transaction_id: transactionId,
        index: safeIndex,
        text: transactionId && safeIndex !== null ? `${transactionId}:${safeIndex}` : covenantPrintable(outpoint)
      };
    }
  }

  return { transaction_id: null, index: null, text: null };
}

function sompiTextToKasText(sompiText: string | null): string | null {
  if (!sompiText || !/^[0-9]+$/.test(sompiText)) return null;
  const sompi = BigInt(sompiText);
  const whole = sompi / 100000000n;
  const fraction = sompi % 100000000n;
  const fractionText = fraction.toString().padStart(8, "0").replace(/0+$/, "");
  return fractionText ? `${whole.toString()}.${fractionText}` : whole.toString();
}

function readCovenantTemplateRegistry(): CovenantTemplateRegistry & { registry_hash_sha256: string } {
  const text = fs.readFileSync(COVENANT_TEMPLATE_REGISTRY_PATH, "utf8");
  const registry = JSON.parse(text) as CovenantTemplateRegistry;
  return {
    ...registry,
    registry_hash_sha256: createHash("sha256").update(text).digest("hex")
  };
}

function covenantRegistryNetworkSupport(registry: CovenantTemplateRegistry): string[] {
  return Array.isArray(registry.network_policy?.registry_network_support)
    ? registry.network_policy.registry_network_support.map((network) => String(network || "").trim()).filter(Boolean)
    : [];
}

function covenantRegistryTemplateForCovenantId(
  registry: CovenantTemplateRegistry,
  networkId: string,
  covenantId: string | null
): CovenantTemplateRegistryEntry | null {
  const normalized = String(covenantId || "").trim().toLowerCase();
  if (!normalized) return null;

  const templates = Array.isArray(registry.templates) ? registry.templates : [];
  for (const template of templates) {
    const templateCovenantId = String(template.covenant_id || "").trim().toLowerCase();
    if (!templateCovenantId || templateCovenantId !== normalized) continue;
    const supportedNetworks = Array.isArray(template.network_support) ? template.network_support.map(String) : [];
    if (!supportedNetworks.includes(networkId)) continue;
    return template;
  }

  return null;
}

function createToccataCovenantRpcClient(networkId: string): InstanceType<typeof ToccataRpcClient> {
  if (networkId === "testnet-10") {
    return new ToccataRpcClient({ url: TN10_COVENANT_RPC_URL, networkId });
  }
  return new ToccataRpcClient({ resolver: new ToccataResolver(), networkId });
}

function createCovenantControlsBuildRpcClient(networkId: string): InstanceType<typeof RpcClient> {
  if (networkId === "testnet-10") {
    return new RpcClient({ url: TN10_COVENANT_RPC_URL, networkId });
  }
  return new RpcClient({ resolver: new Resolver(), networkId });
}

function covenantControlsUtxoContextId(label: string): string {
  const id = sha256FromText(label);
  if (typeof id !== "string" || !/^[0-9a-f]{64}$/i.test(id)) {
    throw new Error("covenant_controls_utxo_context_id_invalid");
  }
  return id;
}

function covenantKnownInspectionAddressSource(address: string): string | null {
  if (!address) return null;
  if (address === LOWLEVEL_TN10_PROOF_ADDRESS) return "known_lab_public_address";
  if (address === OMA_L1_TN10_CONTROLLER_ADDRESS) return "oma_l1_controller_public_address";
  if (address === OMA_L1_TN10_HOLDER_ADDRESS) return "oma_l1_holder_public_address";
  return null;
}

function covenantKnownInspectionAllowedAddresses(): Array<{ role: string; address: string }> {
  return [
    { role: "known_lab_public_address", address: LOWLEVEL_TN10_PROOF_ADDRESS },
    { role: "oma_l1_controller_public_address", address: OMA_L1_TN10_CONTROLLER_ADDRESS },
    { role: "oma_l1_holder_public_address", address: OMA_L1_TN10_HOLDER_ADDRESS }
  ];
}

