type ProgrammableKasProtectKasStore = {
  schema_kind: "programmable_kas_protect_kas_locks_v1";
  schema_version: 1;
  records: ProgrammableKasProtectKasRecord[];
};

const PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_FILE_NAME = "programmable-kas-protect-kas-locks.v1.json";
const PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_SCHEMA_KIND = "programmable_kas_protect_kas_locks_v1";

function programmableKasProtectKasLocksPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_FILE_NAME);
}

function emptyProgrammableKasProtectKasLockStore(): ProgrammableKasProtectKasStore {
  return { schema_kind: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_SCHEMA_KIND, schema_version: 1, records: [] };
}

function readProgrammableKasProtectKasLockStore(repoRootPath: string, userId: string): ProgrammableKasProtectKasStore {
  const p = programmableKasProtectKasLocksPath(repoRootPath, userId);
  if (!fs.existsSync(p)) return emptyProgrammableKasProtectKasLockStore();

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.records)) return emptyProgrammableKasProtectKasLockStore();

  return {
    schema_kind: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: parsed.records.filter((record: any) => record && typeof record === "object")
  };
}

function writeProgrammableKasProtectKasLockStore(repoRootPath: string, userId: string, store: ProgrammableKasProtectKasStore): void {
  const p = programmableKasProtectKasLocksPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function upsertProgrammableKasProtectKasLockRecord(repoRootPath: string, userId: string, record: ProgrammableKasProtectKasRecord): void {
  const store = readProgrammableKasProtectKasLockStore(repoRootPath, userId);
  const sourceOutpoint = String(record.source_outpoint_key || "").trim();
  const covenantId = String(record.covenant_id || "").trim().toLowerCase();
  const filtered = store.records.filter((existing: any) => {
    const sameSource = String(existing?.source_outpoint_key || "").trim() === sourceOutpoint;
    const sameCovenant = String(existing?.covenant_id || "").trim().toLowerCase() === covenantId;
    return !(sameSource && sameCovenant);
  });

  writeProgrammableKasProtectKasLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, record]
  });
}

function programmableKasProtectKasLockRecordIsReleased(record: any): boolean {
  const status = String(record?.record_status || "").trim();
  return status === "released_live_verified" || status === "release_submitted_pending_visibility";
}

function markProgrammableKasProtectKasLockRecordReleased(
  repoRootPath: string,
  userId: string,
  sourceOutpointKey: string,
  expectedCovenantId: string,
  patch: {
    record_status: string;
    release_status: string;
    release_txid: string;
    release_amount_sompi: string;
    release_amount_kas: string | null;
    released_output_outpoint: string | null;
  }
): ProgrammableKasProtectKasRecord | null {
  const store = readProgrammableKasProtectKasLockStore(repoRootPath, userId);
  const normalizedSource = String(sourceOutpointKey || "").trim();
  const normalizedCovenantId = String(expectedCovenantId || "").trim().toLowerCase();
  const nowIso = new Date().toISOString();
  let updatedRecord: ProgrammableKasProtectKasRecord | null = null;

  const records = store.records.map((record: any) => {
    const sameSource = String(record?.source_outpoint_key || "").trim() === normalizedSource;
    const sameCovenant = String(record?.covenant_id || "").trim().toLowerCase() === normalizedCovenantId;
    if (!sameSource || !sameCovenant) return record;

    updatedRecord = {
      ...(record as ProgrammableKasProtectKasRecord),
      record_status: patch.record_status,
      updated_at: nowIso,
      released_at: nowIso,
      release_status: patch.release_status,
      release_txid: patch.release_txid,
      release_amount_sompi: patch.release_amount_sompi,
      release_amount_kas: patch.release_amount_kas,
      released_output_outpoint: patch.released_output_outpoint
    };
    return updatedRecord;
  });

  if (!updatedRecord) return null;

  writeProgrammableKasProtectKasLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records
  });

  return updatedRecord;
}

function programmableKasProtectKasSafeRecord(record: ProgrammableKasProtectKasRecord): any {
  return {
    record_kind: record.record_kind,
    record_status: record.record_status,
    tracking_source: record.tracking_source,
    created_at: record.created_at,
    updated_at: record.updated_at,
    released_at: record.released_at || null,
    network: record.network,
    networkId: record.networkId,
    wallet_id: record.wallet_id,
    wallet_type: record.wallet_type,
    creator_address: record.creator_address,
    from_address: record.from_address,
    destination_address: record.destination_address,
    destination_address_source: record.destination_address_source,
    destination_address_version: record.destination_address_version,
    change_address: record.change_address,
    selected_outpoint_key: record.selected_outpoint_key,
    selected_source_amount_sompi: record.selected_source_amount_sompi,
    amount_sompi: record.amount_sompi,
    amount_kas: record.amount_kas,
    fee_reserve_sompi: record.fee_reserve_sompi,
    calculated_fee_sompi: record.calculated_fee_sompi,
    change_sompi: record.change_sompi,
    covenant_id: record.covenant_id,
    source_outpoint_key: record.source_outpoint_key,
    submitted_txid: record.submitted_txid,
    post_submit_scan_status: record.post_submit_scan_status,
    protected_output_visible: record.protected_output_visible,
    normal_send_exclusion_expected: record.normal_send_exclusion_expected,
    release_status: record.release_status || null,
    release_txid: record.release_txid || null,
    release_amount_sompi: record.release_amount_sompi || null,
    release_amount_kas: record.release_amount_kas || null,
    released_output_outpoint: record.released_output_outpoint || null
  };
}

type ProgrammableKasP2shOwnerReleaseInspectionAddress = {
  role: string;
  address: string;
  owner_address: string;
  owner_address_version: string;
  owner_address_from_public_key: string;
  owner_public_key_sha256: string;
  p2sh_owner_release_redeem_script_hex: string;
  p2sh_owner_release_redeem_script_sha256: string;
  p2sh_owner_release_redeem_script_byte_len: number;
  p2sh_owner_release_redeem_script_push_limit_bytes: number;
  p2sh_owner_release_redeem_script_pushable: boolean;
  p2sh_owner_release_script_public_key_json_sha256: string | null;
  p2sh_owner_release_script_public_key_script_byte_len: number | null;
  protected_output_script_form: string;
};

function programmableKasP2shOwnerReleaseInspectionAddressForActiveWallet(
  activeAddress: string,
  networkId: string
): ProgrammableKasP2shOwnerReleaseInspectionAddress | null {
  try {
    const activeAddressObject = new Address(activeAddress);
    const ownerAddressVersion = String(activeAddressObject.version || "");
    const ownerXOnlyPublicKey = XOnlyPublicKey.fromAddress(activeAddressObject as any);
    const ownerXOnlyPublicKeyHex = ownerXOnlyPublicKey.toString();

    if (!/^[0-9a-f]{64}$/i.test(ownerXOnlyPublicKeyHex)) {
      return null;
    }

    const ownerAddressFromPublicKey = ownerXOnlyPublicKey.toAddress(networkId as any).toString();
    if (ownerAddressFromPublicKey !== activeAddress) {
      return null;
    }

    const ownerReleaseScriptBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
      .addData(ownerXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig);
    const ownerReleaseScriptPublicKey = ownerReleaseScriptBuilder.createPayToScriptHashScript();
    const ownerReleaseRedeemScriptHex = ownerReleaseScriptBuilder.drain();
    const ownerReleaseRedeemScriptByteLen = ownerReleaseRedeemScriptHex.length / 2;
    const ownerReleaseRedeemScriptPushable =
      ownerReleaseRedeemScriptByteLen <= COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;

    if (!ownerReleaseRedeemScriptPushable) {
      return null;
    }

    const ownerReleaseP2shAddress = addressFromScriptPublicKey(ownerReleaseScriptPublicKey as any, networkId as any);
    if (!ownerReleaseP2shAddress) {
      return null;
    }

    const ownerReleaseScriptPublicKeyJson = typeof ownerReleaseScriptPublicKey.toJSON === "function"
      ? ownerReleaseScriptPublicKey.toJSON()
      : null;
    const ownerReleaseScriptPublicKeyScript = covenantPrintable((ownerReleaseScriptPublicKeyJson as any)?.script ?? (ownerReleaseScriptPublicKey as any).script);

    return {
      role: "programmable_kas_p2sh_owner_release_active_wallet_address",
      address: ownerReleaseP2shAddress.toString(),
      owner_address: activeAddress,
      owner_address_version: ownerAddressVersion,
      owner_address_from_public_key: ownerAddressFromPublicKey,
      owner_public_key_sha256: covenantSha256Text(ownerXOnlyPublicKeyHex),
      p2sh_owner_release_redeem_script_hex: ownerReleaseRedeemScriptHex,
      p2sh_owner_release_redeem_script_sha256: covenantSha256Text(ownerReleaseRedeemScriptHex),
      p2sh_owner_release_redeem_script_byte_len: ownerReleaseRedeemScriptByteLen,
      p2sh_owner_release_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_owner_release_redeem_script_pushable: ownerReleaseRedeemScriptPushable,
      p2sh_owner_release_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: ownerReleaseScriptPublicKey }),
      p2sh_owner_release_script_public_key_script_byte_len: ownerReleaseScriptPublicKeyScript ? ownerReleaseScriptPublicKeyScript.length / 2 : null,
      protected_output_script_form: "p2sh_owner_release_commitment"
    };
  } catch {
    return null;
  }
}


type ProgrammableKasImmediateRecoveryPolicy = {
  owner_address: string;
  owner_address_version: string;
  owner_address_from_public_key: string;
  owner_public_key_sha256: string;
  recovery_address: string;
  recovery_address_version: string;
  recovery_address_from_public_key: string;
  recovery_public_key_sha256: string;
  recovery_address_matches_owner: boolean;
  p2sh_immediate_recovery_address: string;
  p2sh_immediate_recovery_redeem_script_hex: string;
  p2sh_immediate_recovery_redeem_script_sha256: string;
  p2sh_immediate_recovery_redeem_script_byte_len: number;
  p2sh_immediate_recovery_redeem_script_push_limit_bytes: number;
  p2sh_immediate_recovery_redeem_script_pushable: boolean;
  p2sh_immediate_recovery_script_public_key_json_sha256: string | null;
  p2sh_immediate_recovery_script_public_key_script_byte_len: number | null;
  protected_output_script_form: string;
  p2sh_immediate_recovery_script_public_key: any;
};

function programmableKasImmediateRecoveryPolicyForOwnerAndRecovery(
  ownerAddress: string,
  networkId: string,
  recoveryAddress: string
): ProgrammableKasImmediateRecoveryPolicy | null {
  try {
    const ownerAddressObject = new Address(ownerAddress);
    const ownerAddressVersion = String(ownerAddressObject.version || "");
    const ownerXOnlyPublicKey = XOnlyPublicKey.fromAddress(ownerAddressObject as any);
    const ownerXOnlyPublicKeyHex = ownerXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(ownerXOnlyPublicKeyHex)) return null;

    const ownerAddressFromPublicKey = ownerXOnlyPublicKey.toAddress(networkId as any).toString();
    if (ownerAddressFromPublicKey !== ownerAddress) return null;

    const recoveryAddressObject = new Address(recoveryAddress);
    const recoveryAddressVersion = String(recoveryAddressObject.version || "");
    const recoveryXOnlyPublicKey = XOnlyPublicKey.fromAddress(recoveryAddressObject as any);
    const recoveryXOnlyPublicKeyHex = recoveryXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(recoveryXOnlyPublicKeyHex)) return null;

    const recoveryAddressFromPublicKey = recoveryXOnlyPublicKey.toAddress(networkId as any).toString();
    if (recoveryAddressFromPublicKey !== recoveryAddress) return null;

    const immediateRecoveryScriptBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
      .addOp(Opcodes.OpDup)
      .addData(ownerXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig)
      .addOp(Opcodes.OpSwap)
      .addData(recoveryXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig)
      .addOp(Opcodes.OpBoolOr);
    const immediateRecoveryScriptPublicKey = immediateRecoveryScriptBuilder.createPayToScriptHashScript();
    const immediateRecoveryRedeemScriptHex = immediateRecoveryScriptBuilder.drain();
    const redeemScriptByteLen = immediateRecoveryRedeemScriptHex.length / 2;
    const redeemScriptPushable = redeemScriptByteLen <= COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;
    if (!redeemScriptPushable) return null;

    const immediateRecoveryP2shAddress = addressFromScriptPublicKey(immediateRecoveryScriptPublicKey as any, networkId as any);
    if (!immediateRecoveryP2shAddress) return null;

    const immediateRecoveryScriptPublicKeyJson = typeof immediateRecoveryScriptPublicKey.toJSON === "function"
      ? immediateRecoveryScriptPublicKey.toJSON()
      : null;
    const immediateRecoveryScriptPublicKeyScript = covenantPrintable((immediateRecoveryScriptPublicKeyJson as any)?.script ?? (immediateRecoveryScriptPublicKey as any).script);

    return {
      owner_address: ownerAddress,
      owner_address_version: ownerAddressVersion,
      owner_address_from_public_key: ownerAddressFromPublicKey,
      owner_public_key_sha256: covenantSha256Text(ownerXOnlyPublicKeyHex),
      recovery_address: recoveryAddress,
      recovery_address_version: recoveryAddressVersion,
      recovery_address_from_public_key: recoveryAddressFromPublicKey,
      recovery_public_key_sha256: covenantSha256Text(recoveryXOnlyPublicKeyHex),
      recovery_address_matches_owner: recoveryAddress === ownerAddress,
      p2sh_immediate_recovery_address: immediateRecoveryP2shAddress.toString(),
      p2sh_immediate_recovery_redeem_script_hex: immediateRecoveryRedeemScriptHex,
      p2sh_immediate_recovery_redeem_script_sha256: covenantSha256Text(immediateRecoveryRedeemScriptHex),
      p2sh_immediate_recovery_redeem_script_byte_len: redeemScriptByteLen,
      p2sh_immediate_recovery_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_immediate_recovery_redeem_script_pushable: redeemScriptPushable,
      p2sh_immediate_recovery_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: immediateRecoveryScriptPublicKey }),
      p2sh_immediate_recovery_script_public_key_script_byte_len: immediateRecoveryScriptPublicKeyScript ? immediateRecoveryScriptPublicKeyScript.length / 2 : null,
      protected_output_script_form: "p2sh_immediate_recovery_commitment",
      p2sh_immediate_recovery_script_public_key: immediateRecoveryScriptPublicKey
    };
  } catch {
    return null;
  }
}


