type ProgrammableKasAbsoluteTimeLockStore = {
  schema_kind: "programmable_kas_absolute_time_locks_v1";
  schema_version: 1;
  records: ProgrammableKasAbsoluteTimeLockRecord[];
};

const PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCKS_FILE_NAME = "programmable-kas-locks.v1.json";
const PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCKS_SCHEMA_KIND = "programmable_kas_absolute_time_locks_v1";

function programmableKasAbsoluteTimeLocksPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCKS_FILE_NAME);
}

function emptyProgrammableKasAbsoluteTimeLockStore(): ProgrammableKasAbsoluteTimeLockStore {
  return { schema_kind: PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCKS_SCHEMA_KIND, schema_version: 1, records: [] };
}

function readProgrammableKasAbsoluteTimeLockStore(repoRootPath: string, userId: string): ProgrammableKasAbsoluteTimeLockStore {
  const p = programmableKasAbsoluteTimeLocksPath(repoRootPath, userId);
  if (!fs.existsSync(p)) return emptyProgrammableKasAbsoluteTimeLockStore();

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.records)) return emptyProgrammableKasAbsoluteTimeLockStore();

  return {
    schema_kind: PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: parsed.records.filter((record: any) => record && typeof record === "object")
  };
}

function writeProgrammableKasAbsoluteTimeLockStore(repoRootPath: string, userId: string, store: ProgrammableKasAbsoluteTimeLockStore): void {
  const p = programmableKasAbsoluteTimeLocksPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function upsertProgrammableKasAbsoluteTimeLockRecord(repoRootPath: string, userId: string, record: ProgrammableKasAbsoluteTimeLockRecord): void {
  const store = readProgrammableKasAbsoluteTimeLockStore(repoRootPath, userId);
  const sourceOutpoint = String(record.source_outpoint_key || "").trim();
  const covenantId = String(record.covenant_id || "").trim().toLowerCase();
  const lockTargetDaa = String(record.lock_target_daa || "").trim();
  const filtered = store.records.filter((existing: any) => {
    const sameSource = String(existing?.source_outpoint_key || "").trim() === sourceOutpoint;
    const sameCovenant = String(existing?.covenant_id || "").trim().toLowerCase() === covenantId;
    const sameLock = String(existing?.lock_target_daa || "").trim() === lockTargetDaa;
    return !(sameSource && sameCovenant && sameLock);
  });

  writeProgrammableKasAbsoluteTimeLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, record]
  });
}

function markProgrammableKasAbsoluteTimeLockRecordReleased(
  repoRootPath: string,
  userId: string,
  sourceOutpointKey: string,
  covenantId: string,
  lockTargetDaa: string,
  releaseUpdate: {
    record_status: string;
    release_status: string;
    release_txid: string;
    release_amount_sompi: string;
    release_amount_kas: string | null;
    released_output_outpoint: string | null;
  }
): ProgrammableKasAbsoluteTimeLockRecord | null {
  const store = readProgrammableKasAbsoluteTimeLockStore(repoRootPath, userId);
  const nowIso = new Date().toISOString();
  let updatedRecord: ProgrammableKasAbsoluteTimeLockRecord | null = null;
  const records = store.records.map((record: any) => {
    const sameSource = String(record?.source_outpoint_key || "").trim() === String(sourceOutpointKey || "").trim();
    const sameCovenant = String(record?.covenant_id || "").trim().toLowerCase() === String(covenantId || "").trim().toLowerCase();
    const sameLock = String(record?.lock_target_daa || "").trim() === String(lockTargetDaa || "").trim();
    if (!sameSource || !sameCovenant || !sameLock) return record;
    updatedRecord = {
      ...record,
      record_status: releaseUpdate.record_status,
      updated_at: nowIso,
      released_at: nowIso,
      release_status: releaseUpdate.release_status,
      release_txid: releaseUpdate.release_txid,
      release_amount_sompi: releaseUpdate.release_amount_sompi,
      release_amount_kas: releaseUpdate.release_amount_kas,
      released_output_outpoint: releaseUpdate.released_output_outpoint
    } as ProgrammableKasAbsoluteTimeLockRecord;
    return updatedRecord;
  });

  if (updatedRecord) {
    writeProgrammableKasAbsoluteTimeLockStore(repoRootPath, userId, {
      schema_kind: PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCKS_SCHEMA_KIND,
      schema_version: 1,
      records
    });
  }

  return updatedRecord;
}

function programmableKasAbsoluteTimeLockRecordIsReleased(record: any): boolean {
  const status = String(record?.record_status || "").trim();
  return status === "released_live_verified" || status === "release_submitted_pending_visibility";
}

function programmableKasAbsoluteTimeLockPolicyForOwnerAddress(
  ownerAddress: string,
  networkId: string,
  lockTargetDaa: bigint
): ProgrammableKasAbsoluteTimeLockPolicy | null {
  try {
    const ownerAddressObject = new Address(ownerAddress);
    const ownerAddressVersion = String(ownerAddressObject.version || "");
    const ownerXOnlyPublicKey = XOnlyPublicKey.fromAddress(ownerAddressObject as any);
    const ownerXOnlyPublicKeyHex = ownerXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(ownerXOnlyPublicKeyHex)) return null;

    const ownerAddressFromPublicKey = ownerXOnlyPublicKey.toAddress(networkId as any).toString();
    if (ownerAddressFromPublicKey !== ownerAddress) return null;

    const absoluteTimeLockScriptBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
      .addLockTime(lockTargetDaa)
      .addOp(Opcodes.OpCheckLockTimeVerify)
      .addData(ownerXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig);
    const absoluteTimeLockScriptPublicKey = absoluteTimeLockScriptBuilder.createPayToScriptHashScript();
    const absoluteTimeLockRedeemScriptHex = absoluteTimeLockScriptBuilder.drain();
    const redeemScriptByteLen = absoluteTimeLockRedeemScriptHex.length / 2;
    const redeemScriptPushable = redeemScriptByteLen <= COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;
    if (!redeemScriptPushable) return null;

    const absoluteTimeLockP2shAddress = addressFromScriptPublicKey(absoluteTimeLockScriptPublicKey as any, networkId as any);
    if (!absoluteTimeLockP2shAddress) return null;

    const absoluteTimeLockScriptPublicKeyJson = typeof absoluteTimeLockScriptPublicKey.toJSON === "function"
      ? absoluteTimeLockScriptPublicKey.toJSON()
      : null;
    const absoluteTimeLockScriptPublicKeyScript = covenantPrintable((absoluteTimeLockScriptPublicKeyJson as any)?.script ?? (absoluteTimeLockScriptPublicKey as any).script);

    return {
      owner_address: ownerAddress,
      owner_address_version: ownerAddressVersion,
      owner_address_from_public_key: ownerAddressFromPublicKey,
      owner_public_key_sha256: covenantSha256Text(ownerXOnlyPublicKeyHex),
      p2sh_absolute_time_lock_address: absoluteTimeLockP2shAddress.toString(),
      p2sh_absolute_time_lock_redeem_script_sha256: covenantSha256Text(absoluteTimeLockRedeemScriptHex),
      p2sh_absolute_time_lock_redeem_script_byte_len: redeemScriptByteLen,
      p2sh_absolute_time_lock_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_absolute_time_lock_redeem_script_pushable: redeemScriptPushable,
      p2sh_absolute_time_lock_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: absoluteTimeLockScriptPublicKey }),
      p2sh_absolute_time_lock_script_public_key_script_byte_len: absoluteTimeLockScriptPublicKeyScript ? absoluteTimeLockScriptPublicKeyScript.length / 2 : null,
      protected_output_script_form: "p2sh_absolute_time_lock_commitment"
    };
  } catch {
    return null;
  }
}

function programmableKasAbsoluteTimeLockSafeRecord(record: ProgrammableKasAbsoluteTimeLockRecord, currentVirtualDaaScore: string | null): any {
  const targetText = String(record.lock_target_daa || "").trim();
  const currentText = String(currentVirtualDaaScore || "").trim();
  const targetSatisfied = /^[0-9]+$/.test(targetText) && /^[0-9]+$/.test(currentText)
    ? BigInt(currentText) >= BigInt(targetText)
    : false;

  return {
    record_kind: record.record_kind,
    record_status: record.record_status,
    tracking_source: record.tracking_source,
    created_at: record.created_at,
    updated_at: record.updated_at,
    released_at: record.released_at || null,
    network: record.network,
    networkId: record.networkId,
    wallet_id: record.wallet_id,
    wallet_type: record.wallet_type,
    creator_address: record.creator_address,
    owner_address: record.owner_address,
    owner_address_source: record.owner_address_source,
    owner_public_key_sha256: record.owner_public_key_sha256,
    p2sh_absolute_time_lock_address: record.p2sh_absolute_time_lock_address,
    p2sh_absolute_time_lock_redeem_script_sha256: record.p2sh_absolute_time_lock_redeem_script_sha256,
    p2sh_absolute_time_lock_redeem_script_byte_len: record.p2sh_absolute_time_lock_redeem_script_byte_len,
    p2sh_absolute_time_lock_redeem_script_push_limit_bytes: record.p2sh_absolute_time_lock_redeem_script_push_limit_bytes,
    p2sh_absolute_time_lock_redeem_script_pushable: record.p2sh_absolute_time_lock_redeem_script_pushable,
    p2sh_absolute_time_lock_script_public_key_json_sha256: record.p2sh_absolute_time_lock_script_public_key_json_sha256,
    protected_output_script_form: record.protected_output_script_form,
    amount_sompi: record.amount_sompi,
    amount_kas: record.amount_kas,
    lock_daa_delta: record.lock_daa_delta,
    current_virtual_daa_score: currentVirtualDaaScore,
    current_virtual_daa_score_at_build: record.current_virtual_daa_score_at_build,
    lock_target_daa: record.lock_target_daa,
    target_satisfied: targetSatisfied,
    covenant_id: record.covenant_id,
    source_outpoint_key: record.source_outpoint_key,
    submitted_txid: record.submitted_txid,
    post_submit_scan_status: record.post_submit_scan_status,
    protected_output_visible: record.protected_output_visible,
    release_status: record.release_status || null,
    release_txid: record.release_txid || null,
    release_amount_sompi: record.release_amount_sompi || null,
    release_amount_kas: record.release_amount_kas || null,
    released_output_outpoint: record.released_output_outpoint || null
  };
}


