function programmableKasRelativeSequenceLockPolicyForOwnerAddress(
  ownerAddress: string,
  networkId: string,
  relativeDaaDelta: bigint
): ProgrammableKasRelativeSequenceLockPolicy | null {
  try {
    if (relativeDaaDelta <= 0n) return null;
    if ((relativeDaaDelta & COVENANT_CONTROLS_RELATIVE_SEQUENCE_DISABLED_BIT) !== 0n || relativeDaaDelta > COVENANT_CONTROLS_RELATIVE_SEQUENCE_LOCK_TIME_MASK) return null;

    const ownerAddressObject = new Address(ownerAddress);
    const ownerAddressVersion = String(ownerAddressObject.version || "");
    const ownerXOnlyPublicKey = XOnlyPublicKey.fromAddress(ownerAddressObject as any);
    const ownerXOnlyPublicKeyHex = ownerXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(ownerXOnlyPublicKeyHex)) return null;

    const ownerAddressFromPublicKey = ownerXOnlyPublicKey.toAddress(networkId as any).toString();
    if (ownerAddressFromPublicKey !== ownerAddress) return null;

    const relativeSequenceLockScriptBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
      .addSequence(relativeDaaDelta)
      .addOp(Opcodes.OpCheckSequenceVerify)
      .addData(ownerXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig);
    const relativeSequenceLockScriptPublicKey = relativeSequenceLockScriptBuilder.createPayToScriptHashScript();
    const relativeSequenceLockRedeemScriptHex = relativeSequenceLockScriptBuilder.drain();
    const redeemScriptByteLen = relativeSequenceLockRedeemScriptHex.length / 2;
    const redeemScriptPushable = redeemScriptByteLen <= COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;
    if (!redeemScriptPushable) return null;

    const relativeSequenceLockP2shAddress = addressFromScriptPublicKey(relativeSequenceLockScriptPublicKey as any, networkId as any);
    if (!relativeSequenceLockP2shAddress) return null;

    const relativeSequenceLockScriptPublicKeyJson = typeof relativeSequenceLockScriptPublicKey.toJSON === "function"
      ? relativeSequenceLockScriptPublicKey.toJSON()
      : null;
    const relativeSequenceLockScriptPublicKeyScript = covenantPrintable((relativeSequenceLockScriptPublicKeyJson as any)?.script ?? (relativeSequenceLockScriptPublicKey as any).script);

    return {
      owner_address: ownerAddress,
      owner_address_version: ownerAddressVersion,
      owner_address_from_public_key: ownerAddressFromPublicKey,
      owner_public_key_sha256: covenantSha256Text(ownerXOnlyPublicKeyHex),
      p2sh_relative_sequence_lock_address: relativeSequenceLockP2shAddress.toString(),
      p2sh_relative_sequence_lock_redeem_script_sha256: covenantSha256Text(relativeSequenceLockRedeemScriptHex),
      p2sh_relative_sequence_lock_redeem_script_byte_len: redeemScriptByteLen,
      p2sh_relative_sequence_lock_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_relative_sequence_lock_redeem_script_pushable: redeemScriptPushable,
      p2sh_relative_sequence_lock_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: relativeSequenceLockScriptPublicKey }),
      p2sh_relative_sequence_lock_script_public_key_script_byte_len: relativeSequenceLockScriptPublicKeyScript ? relativeSequenceLockScriptPublicKeyScript.length / 2 : null,
      protected_output_script_form: "p2sh_relative_sequence_lock_commitment"
    };
  } catch {
    return null;
  }
}

function programmableKasRelativeSequenceLockSafeRecord(record: ProgrammableKasRelativeSequenceLockRecord, currentVirtualDaaScore: string | null): any {
  const relativeText = String(record.relative_daa_delta || "").trim();
  const sourceDaaText = String(record.source_block_daa_score || "").trim();
  const currentText = String(currentVirtualDaaScore || "").trim();
  const derivedUnlockDaaScore = /^[0-9]+$/.test(relativeText) && /^[0-9]+$/.test(sourceDaaText)
    ? (BigInt(sourceDaaText) + BigInt(relativeText)).toString()
    : String(record.relative_unlock_daa_score || "").trim() || null;
  const targetSatisfied = derivedUnlockDaaScore && /^[0-9]+$/.test(derivedUnlockDaaScore) && /^[0-9]+$/.test(currentText)
    ? BigInt(currentText) >= BigInt(derivedUnlockDaaScore)
    : false;

  return {
    record_kind: record.record_kind,
    record_status: record.record_status,
    tracking_source: record.tracking_source,
    created_at: record.created_at,
    updated_at: record.updated_at,
    released_at: record.released_at || null,
    network: record.network,
    networkId: record.networkId,
    wallet_id: record.wallet_id,
    wallet_type: record.wallet_type,
    creator_address: record.creator_address,
    owner_address: record.owner_address,
    owner_address_source: record.owner_address_source,
    owner_public_key_sha256: record.owner_public_key_sha256,
    p2sh_relative_sequence_lock_address: record.p2sh_relative_sequence_lock_address,
    p2sh_relative_sequence_lock_redeem_script_sha256: record.p2sh_relative_sequence_lock_redeem_script_sha256,
    p2sh_relative_sequence_lock_redeem_script_byte_len: record.p2sh_relative_sequence_lock_redeem_script_byte_len,
    p2sh_relative_sequence_lock_redeem_script_push_limit_bytes: record.p2sh_relative_sequence_lock_redeem_script_push_limit_bytes,
    p2sh_relative_sequence_lock_redeem_script_pushable: record.p2sh_relative_sequence_lock_redeem_script_pushable,
    p2sh_relative_sequence_lock_script_public_key_json_sha256: record.p2sh_relative_sequence_lock_script_public_key_json_sha256,
    protected_output_script_form: record.protected_output_script_form,
    amount_sompi: record.amount_sompi,
    amount_kas: record.amount_kas,
    relative_daa_delta: record.relative_daa_delta,
    source_block_daa_score: record.source_block_daa_score || null,
    current_virtual_daa_score: currentVirtualDaaScore,
    relative_unlock_daa_score: derivedUnlockDaaScore,
    target_satisfied: targetSatisfied,
    covenant_id: record.covenant_id,
    source_outpoint_key: record.source_outpoint_key,
    submitted_txid: record.submitted_txid,
    post_submit_scan_status: record.post_submit_scan_status,
    protected_output_visible: record.protected_output_visible,
    release_status: record.release_status || null,
    release_txid: record.release_txid || null,
    release_amount_sompi: record.release_amount_sompi || null,
    release_amount_kas: record.release_amount_kas || null,
    released_output_outpoint: record.released_output_outpoint || null
  };
}


