type ProgrammableKasEscrowRefundStore = {
  schema_kind: "programmable_kas_escrow_refund_locks_v1";
  schema_version: 1;
  records: ProgrammableKasEscrowRefundRecord[];
};

const PROGRAMMABLE_KAS_ESCROW_REFUND_LOCKS_FILE_NAME = "programmable-kas-escrow-refund-locks.v1.json";
const PROGRAMMABLE_KAS_ESCROW_REFUND_LOCKS_SCHEMA_KIND = "programmable_kas_escrow_refund_locks_v1";

function programmableKasEscrowRefundLocksPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, PROGRAMMABLE_KAS_ESCROW_REFUND_LOCKS_FILE_NAME);
}

function emptyProgrammableKasEscrowRefundLockStore(): ProgrammableKasEscrowRefundStore {
  return { schema_kind: PROGRAMMABLE_KAS_ESCROW_REFUND_LOCKS_SCHEMA_KIND, schema_version: 1, records: [] };
}

function readProgrammableKasEscrowRefundLockStore(repoRootPath: string, userId: string): ProgrammableKasEscrowRefundStore {
  const p = programmableKasEscrowRefundLocksPath(repoRootPath, userId);
  if (!fs.existsSync(p)) return emptyProgrammableKasEscrowRefundLockStore();

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.records)) return emptyProgrammableKasEscrowRefundLockStore();

  return {
    schema_kind: PROGRAMMABLE_KAS_ESCROW_REFUND_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: parsed.records.filter((record: any) => record && typeof record === "object")
  };
}

function writeProgrammableKasEscrowRefundLockStore(repoRootPath: string, userId: string, store: ProgrammableKasEscrowRefundStore): void {
  const p = programmableKasEscrowRefundLocksPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function upsertProgrammableKasEscrowRefundLockRecord(repoRootPath: string, userId: string, record: ProgrammableKasEscrowRefundRecord): void {
  const store = readProgrammableKasEscrowRefundLockStore(repoRootPath, userId);
  const sourceOutpoint = String(record.source_outpoint_key || "").trim();
  const covenantId = String(record.covenant_id || "").trim().toLowerCase();
  const buyerRefundAddress = String(record.buyer_refund_address || "").trim();
  const sellerReleaseAddress = String(record.seller_release_address || "").trim();
  const refundLockDaa = String(record.refund_lock_daa || "").trim();
  const filtered = store.records.filter((existing: any) => {
    const sameSource = String(existing?.source_outpoint_key || "").trim() === sourceOutpoint;
    const sameCovenant = String(existing?.covenant_id || "").trim().toLowerCase() === covenantId;
    const sameBuyer = String(existing?.buyer_refund_address || "").trim() === buyerRefundAddress;
    const sameSeller = String(existing?.seller_release_address || "").trim() === sellerReleaseAddress;
    const sameRefundLock = String(existing?.refund_lock_daa || "").trim() === refundLockDaa;
    return !(sameSource && sameCovenant && sameBuyer && sameSeller && sameRefundLock);
  });

  writeProgrammableKasEscrowRefundLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_ESCROW_REFUND_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, record]
  });
}

function programmableKasEscrowRefundLockRecordIsReleased(record: any): boolean {
  const status = String(record?.record_status || "").trim();
  return status === "released_live_verified" || status === "release_submitted_pending_visibility" || status === "refund_submitted_pending_visibility";
}

function markProgrammableKasEscrowRefundLockRecordReleased(
  repoRootPath: string,
  userId: string,
  sourceOutpointKey: string,
  expectedCovenantId: string,
  patch: {
    record_status: string;
    release_status: string;
    release_txid: string;
    release_amount_sompi: string;
    release_amount_kas: string | null;
    released_output_outpoint: string | null;
  }
): ProgrammableKasEscrowRefundRecord | null {
  const store = readProgrammableKasEscrowRefundLockStore(repoRootPath, userId);
  const normalizedSource = String(sourceOutpointKey || "").trim();
  const normalizedCovenantId = String(expectedCovenantId || "").trim().toLowerCase();
  const nowIso = new Date().toISOString();
  let updatedRecord: ProgrammableKasEscrowRefundRecord | null = null;

  const records = store.records.map((record: any) => {
    const sameSource = String(record?.source_outpoint_key || "").trim() === normalizedSource;
    const sameCovenant = String(record?.covenant_id || "").trim().toLowerCase() === normalizedCovenantId;
    if (!sameSource || !sameCovenant) return record;

    updatedRecord = {
      ...(record as ProgrammableKasEscrowRefundRecord),
      record_status: patch.record_status,
      updated_at: nowIso,
      released_at: nowIso,
      release_status: patch.release_status,
      release_txid: patch.release_txid,
      release_amount_sompi: patch.release_amount_sompi,
      release_amount_kas: patch.release_amount_kas,
      released_output_outpoint: patch.released_output_outpoint
    };
    return updatedRecord;
  });

  if (!updatedRecord) return null;

  writeProgrammableKasEscrowRefundLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_ESCROW_REFUND_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records
  });

  return updatedRecord;
}

function programmableKasEscrowRefundSafeRecord(record: ProgrammableKasEscrowRefundRecord, currentVirtualDaaScore: string | null): any {
  const refundLockDaa = String(record.refund_lock_daa || "").trim();
  const currentDaa = String(currentVirtualDaaScore || "").trim();
  const refundTargetSatisfied = /^[0-9]+$/.test(refundLockDaa) && /^[0-9]+$/.test(currentDaa)
    ? BigInt(currentDaa) >= BigInt(refundLockDaa)
    : false;

  return {
    record_kind: record.record_kind,
    record_status: record.record_status,
    tracking_source: record.tracking_source,
    created_at: record.created_at,
    updated_at: record.updated_at,
    released_at: record.released_at || null,
    network: record.network,
    networkId: record.networkId,
    wallet_id: record.wallet_id,
    wallet_type: record.wallet_type,
    creator_address: record.creator_address,
    buyer_refund_address: record.buyer_refund_address,
    buyer_refund_address_source: record.buyer_refund_address_source,
    buyer_refund_address_version: record.buyer_refund_address_version,
    buyer_refund_public_key_sha256: record.buyer_refund_public_key_sha256,
    buyer_refund_script_public_key_version: record.buyer_refund_script_public_key_version,
    buyer_refund_script_public_key_script_byte_len: record.buyer_refund_script_public_key_script_byte_len,
    buyer_refund_script_public_key_bytes_sha256: record.buyer_refund_script_public_key_bytes_sha256,
    seller_release_address: record.seller_release_address,
    seller_release_address_version: record.seller_release_address_version,
    seller_release_public_key_sha256: record.seller_release_public_key_sha256,
    seller_release_script_public_key_version: record.seller_release_script_public_key_version,
    seller_release_script_public_key_script_byte_len: record.seller_release_script_public_key_script_byte_len,
    seller_release_script_public_key_bytes_sha256: record.seller_release_script_public_key_bytes_sha256,
    refund_lock_daa: refundLockDaa,
    current_virtual_daa_score: currentVirtualDaaScore,
    refund_target_satisfied: refundTargetSatisfied,
    p2sh_escrow_refund_address: record.p2sh_escrow_refund_address,
    p2sh_escrow_refund_redeem_script_sha256: record.p2sh_escrow_refund_redeem_script_sha256,
    p2sh_escrow_refund_redeem_script_byte_len: record.p2sh_escrow_refund_redeem_script_byte_len,
    p2sh_escrow_refund_redeem_script_push_limit_bytes: record.p2sh_escrow_refund_redeem_script_push_limit_bytes,
    p2sh_escrow_refund_redeem_script_pushable: record.p2sh_escrow_refund_redeem_script_pushable,
    p2sh_escrow_refund_script_public_key_json_sha256: record.p2sh_escrow_refund_script_public_key_json_sha256,
    protected_output_script_form: record.protected_output_script_form,
    amount_sompi: record.amount_sompi,
    amount_kas: record.amount_kas,
    covenant_id: record.covenant_id,
    source_outpoint_key: record.source_outpoint_key,
    submitted_txid: record.submitted_txid,
    post_submit_scan_status: record.post_submit_scan_status,
    protected_output_visible: record.protected_output_visible,
    release_status: record.release_status || null,
    release_txid: record.release_txid || null,
    release_amount_sompi: record.release_amount_sompi || null,
    release_amount_kas: record.release_amount_kas || null,
    released_output_outpoint: record.released_output_outpoint || null
  };
}

