function upsertProgrammableKasAbsoluteTimeLockAllowedDestinationRecord(repoRootPath: string, userId: string, record: ProgrammableKasAbsoluteTimeLockAllowedDestinationRecord): void {
  const store = readProgrammableKasAbsoluteTimeLockAllowedDestinationLockStore(repoRootPath, userId);
  const sourceOutpoint = String(record.source_outpoint_key || "").trim();
  const covenantId = String(record.covenant_id || "").trim().toLowerCase();
  const allowedDestinationAddress = String(record.allowed_destination_address || "").trim();
  const lockTargetDaa = String(record.lock_target_daa || "").trim();
  const filtered = store.records.filter((existing: any) => {
    const sameSource = String(existing?.source_outpoint_key || "").trim() === sourceOutpoint;
    const sameCovenant = String(existing?.covenant_id || "").trim().toLowerCase() === covenantId;
    const sameAllowedDestination = String(existing?.allowed_destination_address || "").trim() === allowedDestinationAddress;
    const sameLockTarget = String(existing?.lock_target_daa || "").trim() === lockTargetDaa;
    return !(sameSource && sameCovenant && sameAllowedDestination && sameLockTarget);
  });

  writeProgrammableKasAbsoluteTimeLockAllowedDestinationLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCK_ALLOWED_DESTINATION_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, record]
  });
}

function programmableKasAbsoluteTimeLockAllowedDestinationRecordIsReleased(record: any): boolean {
  const status = String(record?.record_status || "").trim();
  return status === "released_live_verified" || status === "release_submitted_pending_visibility";
}

function markProgrammableKasAbsoluteTimeLockAllowedDestinationRecordReleased(
  repoRootPath: string,
  userId: string,
  sourceOutpointKey: string,
  expectedCovenantId: string,
  lockTargetDaa: string,
  allowedDestinationAddress: string,
  patch: {
    record_status: string;
    release_status: string;
    release_txid: string;
    release_amount_sompi: string;
    release_amount_kas: string | null;
    released_output_outpoint: string | null;
  }
): ProgrammableKasAbsoluteTimeLockAllowedDestinationRecord | null {
  const store = readProgrammableKasAbsoluteTimeLockAllowedDestinationLockStore(repoRootPath, userId);
  const normalizedSource = String(sourceOutpointKey || "").trim();
  const normalizedCovenantId = String(expectedCovenantId || "").trim().toLowerCase();
  const normalizedLockTargetDaa = String(lockTargetDaa || "").trim();
  const normalizedAllowedDestinationAddress = String(allowedDestinationAddress || "").trim();
  const nowIso = new Date().toISOString();
  let updatedRecord: ProgrammableKasAbsoluteTimeLockAllowedDestinationRecord | null = null;

  const records = store.records.map((record: any) => {
    const sameSource = String(record?.source_outpoint_key || "").trim() === normalizedSource;
    const sameCovenant = String(record?.covenant_id || "").trim().toLowerCase() === normalizedCovenantId;
    const sameLockTarget = String(record?.lock_target_daa || "").trim() === normalizedLockTargetDaa;
    const sameAllowedDestination = String(record?.allowed_destination_address || "").trim() === normalizedAllowedDestinationAddress;
    if (!sameSource || !sameCovenant || !sameLockTarget || !sameAllowedDestination) return record;

    updatedRecord = {
      ...(record as ProgrammableKasAbsoluteTimeLockAllowedDestinationRecord),
      record_status: patch.record_status,
      updated_at: nowIso,
      released_at: nowIso,
      release_status: patch.release_status,
      release_txid: patch.release_txid,
      release_amount_sompi: patch.release_amount_sompi,
      release_amount_kas: patch.release_amount_kas,
      released_output_outpoint: patch.released_output_outpoint
    };
    return updatedRecord;
  });

  if (!updatedRecord) return null;

  writeProgrammableKasAbsoluteTimeLockAllowedDestinationLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_ABSOLUTE_TIME_LOCK_ALLOWED_DESTINATION_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records
  });

  return updatedRecord;
}

function programmableKasAbsoluteTimeLockAllowedDestinationPolicyForOwnerLockAndDestination(
  ownerAddress: string,
  networkId: string,
  lockTargetDaa: bigint,
  allowedDestinationAddress: string
): ProgrammableKasAbsoluteTimeLockAllowedDestinationPolicy | null {
  try {
    const ownerAddressObject = new Address(ownerAddress);
    const ownerAddressVersion = String(ownerAddressObject.version || "");
    const ownerXOnlyPublicKey = XOnlyPublicKey.fromAddress(ownerAddressObject as any);
    const ownerXOnlyPublicKeyHex = ownerXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(ownerXOnlyPublicKeyHex)) return null;

    const ownerAddressFromPublicKey = ownerXOnlyPublicKey.toAddress(networkId as any).toString();
    if (ownerAddressFromPublicKey !== ownerAddress) return null;

    const allowedDestinationAddressObject = new Address(allowedDestinationAddress);
    const allowedDestinationAddressVersion = String(allowedDestinationAddressObject.version || "");
    const allowedDestinationScriptPublicKey = payToAddressScript(allowedDestinationAddressObject as any);
    const allowedDestinationScriptPublicKeyBytes = programmableKasScriptPublicKeyOutputBytesForSpk(allowedDestinationScriptPublicKey as any);
    if (!allowedDestinationScriptPublicKeyBytes) return null;

    const c5ScriptBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
      .addLockTime(lockTargetDaa)
      .addOp(Opcodes.OpCheckLockTimeVerify)
      .addOp(Opcodes.OpTxOutputCount)
      .addI64(1n)
      .addOp(Opcodes.OpEqualVerify)
      .addI64(0n)
      .addOp(Opcodes.OpTxOutputSpk)
      .addData(allowedDestinationScriptPublicKeyBytes.bytes_hex)
      .addOp(Opcodes.OpEqualVerify)
      .addData(ownerXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig);
    const c5ScriptPublicKey = c5ScriptBuilder.createPayToScriptHashScript();
    const c5RedeemScriptHex = c5ScriptBuilder.drain();
    const redeemScriptByteLen = c5RedeemScriptHex.length / 2;
    const redeemScriptPushable = redeemScriptByteLen <= COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;
    if (!redeemScriptPushable) return null;

    const c5P2shAddress = addressFromScriptPublicKey(c5ScriptPublicKey as any, networkId as any);
    if (!c5P2shAddress) return null;

    const c5ScriptPublicKeyJson = typeof c5ScriptPublicKey.toJSON === "function"
      ? c5ScriptPublicKey.toJSON()
      : null;
    const c5ScriptPublicKeyScript = covenantPrintable((c5ScriptPublicKeyJson as any)?.script ?? (c5ScriptPublicKey as any).script);

    return {
      owner_address: ownerAddress,
      owner_address_version: ownerAddressVersion,
      owner_address_from_public_key: ownerAddressFromPublicKey,
      owner_public_key_sha256: covenantSha256Text(ownerXOnlyPublicKeyHex),
      allowed_destination_address: allowedDestinationAddressObject.toString(),
      allowed_destination_address_version: allowedDestinationAddressVersion,
      allowed_destination_script_public_key_version: allowedDestinationScriptPublicKeyBytes.version,
      allowed_destination_script_public_key_script_byte_len: allowedDestinationScriptPublicKeyBytes.script_byte_len,
      allowed_destination_script_public_key_bytes_sha256: covenantSha256Text(allowedDestinationScriptPublicKeyBytes.bytes_hex),
      lock_target_daa: lockTargetDaa.toString(),
      p2sh_absolute_time_lock_allowed_destination_address: c5P2shAddress.toString(),
      p2sh_absolute_time_lock_allowed_destination_redeem_script_hex: c5RedeemScriptHex,
      p2sh_absolute_time_lock_allowed_destination_redeem_script_sha256: covenantSha256Text(c5RedeemScriptHex),
      p2sh_absolute_time_lock_allowed_destination_redeem_script_byte_len: redeemScriptByteLen,
      p2sh_absolute_time_lock_allowed_destination_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_absolute_time_lock_allowed_destination_redeem_script_pushable: redeemScriptPushable,
      p2sh_absolute_time_lock_allowed_destination_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: c5ScriptPublicKey }),
      p2sh_absolute_time_lock_allowed_destination_script_public_key_script_byte_len: c5ScriptPublicKeyScript ? c5ScriptPublicKeyScript.length / 2 : null,
      protected_output_script_form: "p2sh_absolute_time_lock_allowed_destination_commitment",
      p2sh_absolute_time_lock_allowed_destination_script_public_key: c5ScriptPublicKey
    };
  } catch {
    return null;
  }
}

function programmableKasAbsoluteTimeLockAllowedDestinationSafeRecord(record: ProgrammableKasAbsoluteTimeLockAllowedDestinationRecord, currentVirtualDaaScore: string | null): any {
  const targetText = String(record.lock_target_daa || "").trim();
  const currentText = String(currentVirtualDaaScore || "").trim();
  const targetSatisfied = /^[0-9]+$/.test(targetText) && /^[0-9]+$/.test(currentText)
    ? BigInt(currentText) >= BigInt(targetText)
    : false;

  return {
    record_kind: record.record_kind,
    record_status: record.record_status,
    tracking_source: record.tracking_source,
    created_at: record.created_at,
    updated_at: record.updated_at,
    released_at: record.released_at || null,
    network: record.network,
    networkId: record.networkId,
    wallet_id: record.wallet_id,
    wallet_type: record.wallet_type,
    creator_address: record.creator_address,
    owner_address: record.owner_address,
    owner_address_source: record.owner_address_source,
    owner_public_key_sha256: record.owner_public_key_sha256,
    allowed_destination_address: record.allowed_destination_address,
    allowed_destination_address_version: record.allowed_destination_address_version,
    allowed_destination_script_public_key_version: record.allowed_destination_script_public_key_version,
    allowed_destination_script_public_key_script_byte_len: record.allowed_destination_script_public_key_script_byte_len,
    allowed_destination_script_public_key_bytes_sha256: record.allowed_destination_script_public_key_bytes_sha256,
    lock_daa_delta: record.lock_daa_delta,
    current_virtual_daa_score: currentVirtualDaaScore,
    current_virtual_daa_score_at_build: record.current_virtual_daa_score_at_build,
    lock_target_daa: record.lock_target_daa,
    target_satisfied: targetSatisfied,
    p2sh_absolute_time_lock_allowed_destination_address: record.p2sh_absolute_time_lock_allowed_destination_address,
    p2sh_absolute_time_lock_allowed_destination_redeem_script_sha256: record.p2sh_absolute_time_lock_allowed_destination_redeem_script_sha256,
    p2sh_absolute_time_lock_allowed_destination_redeem_script_byte_len: record.p2sh_absolute_time_lock_allowed_destination_redeem_script_byte_len,
    p2sh_absolute_time_lock_allowed_destination_redeem_script_push_limit_bytes: record.p2sh_absolute_time_lock_allowed_destination_redeem_script_push_limit_bytes,
    p2sh_absolute_time_lock_allowed_destination_redeem_script_pushable: record.p2sh_absolute_time_lock_allowed_destination_redeem_script_pushable,
    p2sh_absolute_time_lock_allowed_destination_script_public_key_json_sha256: record.p2sh_absolute_time_lock_allowed_destination_script_public_key_json_sha256,
    protected_output_script_form: record.protected_output_script_form,
    amount_sompi: record.amount_sompi,
    amount_kas: record.amount_kas,
    covenant_id: record.covenant_id,
    source_outpoint_key: record.source_outpoint_key,
    submitted_txid: record.submitted_txid,
    post_submit_scan_status: record.post_submit_scan_status,
    protected_output_visible: record.protected_output_visible,
    release_status: record.release_status || null,
    release_txid: record.release_txid || null,
    release_amount_sompi: record.release_amount_sompi || null,
    release_amount_kas: record.release_amount_kas || null,
    released_output_outpoint: record.released_output_outpoint || null
  };
}


