type Kcc20AtomicSwapMakerLockStore = {
  schema_kind: "kcc20_atomic_swap_locks_v1";
  schema_version: 1;
  records: Kcc20AtomicSwapMakerLockRecord[];
};

const KCC20_ATOMIC_SWAP_LOCKS_FILE_NAME = "programmable-kas-atomic-swap-locks.v1.json";
const KCC20_ATOMIC_SWAP_LOCKS_SCHEMA_KIND = "kcc20_atomic_swap_locks_v1";
const KCC20_ATOMIC_DIRECT_SWAP_POLICY_KIND_V1 = "direct_fixed_recipient_atomic_swap_claim_or_refund_v1";
const KCC20_ATOMIC_DIRECT_SWAP_POLICY_KIND_V2 = "direct_fixed_recipient_atomic_swap_claim_or_refund_with_taker_change_v2";
const KCC20_ATOMIC_DIRECT_SWAP_POLICY_KIND_V3 = "direct_fixed_recipient_atomic_swap_claim_or_refund_with_taker_change_final_true_v3";
const KCC20_ATOMIC_DIRECT_SWAP_POLICY_KIND_V4 = "direct_fixed_recipient_atomic_swap_claim_or_maker_cancel_v4";
const KCC20_ATOMIC_OPEN_SWAP_POLICY_KIND_V1 = "open_dynamic_taker_atomic_swap_claim_or_maker_cancel_v1";
const KCC20_ATOMIC_OPEN_SWAP_TAKER_CLAIM_SELECTOR_COMPUTE_BUDGET = 0;
const KCC20_ATOMIC_SWAP_MIN_KAS_PRICE_SOMPI = 100000000n;

function kcc20AtomicSwapLocksPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, KCC20_ATOMIC_SWAP_LOCKS_FILE_NAME);
}

function emptyKcc20AtomicSwapLockStore(): Kcc20AtomicSwapMakerLockStore {
  return { schema_kind: KCC20_ATOMIC_SWAP_LOCKS_SCHEMA_KIND, schema_version: 1, records: [] };
}

function readKcc20AtomicSwapLockStore(repoRootPath: string, userId: string): Kcc20AtomicSwapMakerLockStore {
  const p = kcc20AtomicSwapLocksPath(repoRootPath, userId);
  if (!fs.existsSync(p)) return emptyKcc20AtomicSwapLockStore();

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.records)) return emptyKcc20AtomicSwapLockStore();

  return {
    schema_kind: KCC20_ATOMIC_SWAP_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: parsed.records.filter((record: any) => record && typeof record === "object")
  };
}

function writeKcc20AtomicSwapLockStore(repoRootPath: string, userId: string, store: Kcc20AtomicSwapMakerLockStore): void {
  const p = kcc20AtomicSwapLocksPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function upsertKcc20AtomicSwapMakerLockRecord(repoRootPath: string, userId: string, record: Kcc20AtomicSwapMakerLockRecord): void {
  const store = readKcc20AtomicSwapLockStore(repoRootPath, userId);
  const sourceOutpoint = String(record.source_outpoint_key || "").trim();
  const covenantId = String(record.covenant_id || "").trim().toLowerCase();
  const policyBodyHash = String(record.policy_body_redeem_script_sha256 || "").trim().toLowerCase();
  const filtered = store.records.filter((existing: any) => {
    const sameSource = String(existing?.source_outpoint_key || "").trim() === sourceOutpoint;
    const sameCovenant = String(existing?.covenant_id || "").trim().toLowerCase() === covenantId;
    const samePolicy = String(existing?.policy_body_redeem_script_sha256 || "").trim().toLowerCase() === policyBodyHash;
    return !(sameSource && sameCovenant && samePolicy);
  });

  writeKcc20AtomicSwapLockStore(repoRootPath, userId, {
    schema_kind: KCC20_ATOMIC_SWAP_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, record]
  });
}

function kcc20AtomicSwapLockRecordIsReleased(record: any): boolean {
  const status = String(record?.record_status || "").trim();
  return status === "claimed_live_verified" || status === "claim_submitted_pending_visibility" || status === "refunded_live_verified" || status === "refund_submitted_pending_visibility" || status === "released_live_verified" || status === "release_submitted_pending_visibility";
}

function kcc20AtomicSwapMakerLockViewerRole(record: any, activeWallet: any): "maker" | null {
  const activeWalletId = String(activeWallet?.id || "").trim();
  const activeAddress = String(activeWallet?.address0 || "").trim();
  if (activeWalletId) {
    if (String(record?.wallet_id || "").trim() === activeWalletId) return "maker";
    if (String(record?.maker_wallet_id || "").trim() === activeWalletId) return "maker";
  }
  if (activeAddress) {
    if (String(record?.maker_address || "").trim() === activeAddress) return "maker";
    if (String(record?.maker_kas_receive_address || "").trim() === activeAddress) return "maker";
    if (String(record?.maker_token_refund_address || "").trim() === activeAddress) return "maker";
  }
  return null;
}

function kcc20AtomicSwapMakerLockRecordVisibleToActiveWallet(record: any, activeWallet: any): boolean {
  return kcc20AtomicSwapMakerLockViewerRole(record, activeWallet) !== null;
}

function kcc20AtomicSwapNormalizeOfferTtlSeconds(input: unknown): number {
  if (input === undefined || input === null || String(input).trim() === "") return 0;
  const raw = Number(input);
  const ttl = Number.isFinite(raw) ? Math.round(raw) : NaN;
  if (!Number.isFinite(ttl)) throw new Error("ttl_invalid");
  if (ttl !== 0 && (ttl < 60 || ttl > 168 * 60 * 60)) throw new Error("ttl_out_of_range");
  return ttl;
}

function kcc20AtomicSwapOfferExpiresAt(createdAtMs: number, ttlSeconds: number): string | null {
  return ttlSeconds > 0 ? new Date(createdAtMs + ttlSeconds * 1000).toISOString() : null;
}

function kcc20AtomicSwapLockRecordIsOfferExpired(record: any, nowMs = Date.now()): boolean {
  const expiresAt = String(record?.offer_expires_at || "").trim();
  if (!expiresAt) return false;
  const expiresAtMs = Date.parse(expiresAt);
  return Number.isFinite(expiresAtMs) && expiresAtMs <= nowMs;
}

function kcc20AtomicSwapMakerLockSafeRecord(record: Kcc20AtomicSwapMakerLockRecord, currentVirtualDaaScore: string | null): any {
  const refundTargetText = String(record.refund_lock_daa || "").trim();
  const currentText = String(currentVirtualDaaScore || "").trim();
  const makerCancelAnytime = String(record.policy_body_kind || "").trim() === KCC20_ATOMIC_DIRECT_SWAP_POLICY_KIND_V4;
  const refundTargetSatisfied = makerCancelAnytime
    ? true
    : /^[0-9]+$/.test(refundTargetText) && /^[0-9]+$/.test(currentText)
      ? BigInt(currentText) >= BigInt(refundTargetText)
      : false;

  return {
    record_kind: record.record_kind,
    record_status: record.record_status,
    tracking_source: record.tracking_source,
    created_at: record.created_at,
    updated_at: record.updated_at,
    network: record.network,
    networkId: record.networkId,
    wallet_id: record.wallet_id,
    wallet_type: record.wallet_type,
    maker_address: record.maker_address,
    maker_wallet_id: record.maker_wallet_id,
    maker_kas_receive_address: record.maker_kas_receive_address,
    maker_token_refund_address: record.maker_token_refund_address,
    taker_token_receive_address: record.taker_token_receive_address,
    asset_covenant_id: record.asset_covenant_id,
    token_name: record.token_name,
    token_symbol: record.token_symbol,
    decimals: record.decimals,
    max_supply_raw: record.max_supply_raw,
    issued_supply_raw: record.issued_supply_raw,
    transfer_rule: record.transfer_rule,
    policy_hash: record.policy_hash,
    issuer_identifier: record.issuer_identifier,
    policy_body_kind: record.policy_body_kind,
    policy_body_redeem_script_sha256: record.policy_body_redeem_script_sha256,
    policy_body_redeem_script_byte_len: record.policy_body_redeem_script_byte_len,
    swap_locked_owner_identifier_type: record.swap_locked_owner_identifier_type,
    swap_locked_owner_identifier: record.swap_locked_owner_identifier,
    lock_amount_raw: record.lock_amount_raw,
    lock_amount_human: record.lock_amount_human,
    kas_price_sompi: record.kas_price_sompi,
    kas_price_kas: record.kas_price_kas,
    refund_lock_daa: record.refund_lock_daa,
    offer_ttl_seconds: Number.isFinite(Number(record.offer_ttl_seconds)) ? Number(record.offer_ttl_seconds) : 0,
    offer_expires_at: record.offer_expires_at || null,
    offer_expired: kcc20AtomicSwapLockRecordIsOfferExpired(record),
    maker_cancel_anytime: makerCancelAnytime,
    current_virtual_daa_score: currentVirtualDaaScore,
    refund_target_satisfied: refundTargetSatisfied,
    selected_source_count: record.selected_source_count,
    source_holder_outpoints: record.source_holder_outpoints,
    source_holder_amount_raw_total: record.source_holder_amount_raw_total,
    source_holder_carrier_sompi_total: record.source_holder_carrier_sompi_total,
    maker_change_amount_raw: record.maker_change_amount_raw,
    swap_locked_holder_amount_raw: record.swap_locked_holder_amount_raw,
    swap_locked_holder_address: record.swap_locked_holder_address,
    swap_locked_holder_carrier_sompi: record.swap_locked_holder_carrier_sompi,
    swap_locked_holder_script_public_key_json_sha256: record.swap_locked_holder_script_public_key_json_sha256,
    maker_change_holder_outpoint: record.maker_change_holder_outpoint || null,
    maker_change_holder_address: record.maker_change_holder_address || null,
    maker_change_holder_amount_raw: record.maker_change_holder_amount_raw || null,
    maker_change_holder_script_public_key_json_sha256: record.maker_change_holder_script_public_key_json_sha256 || null,
    native_refund_outpoint: record.native_refund_outpoint || null,
    native_refund_address: record.native_refund_address || null,
    native_refund_sompi: record.native_refund_sompi || null,
    native_refund_kas: record.native_refund_kas || null,
    native_kas_funding_input_outpoint: record.native_kas_funding_input_outpoint,
    native_kas_funding_input_index: record.native_kas_funding_input_index,
    native_kas_funding_input_used: record.native_kas_funding_input_used,
    amount_sompi: record.amount_sompi,
    amount_kas: record.amount_kas,
    covenant_id: record.covenant_id,
    source_outpoint_key: record.source_outpoint_key,
    submitted_txid: record.submitted_txid,
    unsigned_safe_json_sha256: record.unsigned_safe_json_sha256,
    signed_safe_json_sha256: record.signed_safe_json_sha256 || null,
    post_submit_scan_status: record.post_submit_scan_status,
    swap_locked_output_visible: record.swap_locked_output_visible,
    claim_status: record.claim_status || null,
    claim_txid: record.claim_txid || null,
    refund_status: record.refund_status || null,
    refund_txid: record.refund_txid || null,
    released_output_outpoint: record.released_output_outpoint || null
  };
}


function kcc20AtomicSwapMakerChangeTrackedAssetCandidate(params: {
  atomicRecord: Kcc20AtomicSwapMakerLockRecord;
  templateRecord: OmaL1TrackedAssetRecord | null;
  outputRow: CovenantControlsBuildSourceRow | null;
}): OmaL1TrackedAssetRecord | null {
  const { atomicRecord, templateRecord, outputRow } = params;
  if (!templateRecord) return null;

  const assetCovenantId = String(atomicRecord.asset_covenant_id || "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(assetCovenantId)) return null;

  const holderOutpoint = String(atomicRecord.maker_change_holder_outpoint || "").trim();
  const holderAmountRaw = String(atomicRecord.maker_change_holder_amount_raw || atomicRecord.maker_change_amount_raw || "0").trim();
  const holderAddress = String(atomicRecord.maker_change_holder_address || atomicRecord.maker_token_refund_address || atomicRecord.maker_address || "").trim();
  const holderScriptSha = String(atomicRecord.maker_change_holder_script_public_key_json_sha256 || "").trim() || null;
  if (!holderOutpoint || !/^\d+$/.test(holderAmountRaw) || BigInt(holderAmountRaw) <= 0n || !holderAddress) return null;

  if (outputRow) {
    const rowOutpoint = covenantInputOutpointKey(outputRow);
    const rowCovenantId = String(outputRow.covenant_id || "").trim().toLowerCase();
    if (rowOutpoint !== holderOutpoint) return null;
    if (rowCovenantId !== assetCovenantId) return null;
  }

  const now = new Date().toISOString();
  return {
    record_kind: "oma_l1_tracked_asset_record_v1",
    record_status: "candidate_requires_live_reverification",
    created_at: now,
    updated_at: now,
    source: "kcc20_atomic_swap_maker_change_auto_track_v1",
    networkId: atomicRecord.networkId,
    wallet_id: atomicRecord.maker_wallet_id || atomicRecord.wallet_id || templateRecord.wallet_id,
    owner_public_key: String(templateRecord.owner_public_key || ""),
    owner_identifier: holderAddress,
    issuer_identifier: atomicRecord.issuer_identifier,
    token_name: atomicRecord.token_name,
    token_symbol: atomicRecord.token_symbol,
    decimals: atomicRecord.decimals,
    max_supply_raw: atomicRecord.max_supply_raw,
    issued_supply_raw: atomicRecord.issued_supply_raw,
    holder_amount_raw: holderAmountRaw,
    transfer_rule: atomicRecord.transfer_rule,
    policy_hash: atomicRecord.policy_hash,
    asset_covenant_id: assetCovenantId,
    controller: { ...templateRecord.controller },
    holder: {
      address: holderAddress,
      outpoint: holderOutpoint,
      carrier_sompi: outputRow?.amount_sompi || templateRecord.holder?.carrier_sompi || "0",
      script_public_key_script: null,
      script_public_key_json_sha256: holderScriptSha,
      redeem_script_hex_sha256: null,
      state_schema: OMA_L1_TOKEN_HOLDER_STATE_SCHEMA
    }
  };
}

function kcc20AtomicSwapMakerChangeTemplateRecord(store: OmaL1TrackedAssetStore, atomicRecord: Kcc20AtomicSwapMakerLockRecord): OmaL1TrackedAssetRecord | null {
  const sourceOutpoints = new Set((Array.isArray(atomicRecord.source_holder_outpoints) ? atomicRecord.source_holder_outpoints : [])
    .map((outpoint) => String(outpoint || "").trim())
    .filter(Boolean));
  const assetCovenantId = String(atomicRecord.asset_covenant_id || "").trim().toLowerCase();
  const makerAddress = String(atomicRecord.maker_address || atomicRecord.maker_token_refund_address || "").trim();

  return store.records.find((record: any) => sourceOutpoints.has(String(record?.holder?.outpoint || "").trim()))
    || store.records.find((record: any) => String(record?.asset_covenant_id || "").trim().toLowerCase() === assetCovenantId && String(record?.owner_identifier || "").trim() === makerAddress)
    || store.records.find((record: any) => String(record?.asset_covenant_id || "").trim().toLowerCase() === assetCovenantId)
    || null;
}

function kcc20AtomicSwapReplaceSourceHoldersWithMakerChange(params: {
  repoRootPath: string;
  userId: string;
  atomicRecord: Kcc20AtomicSwapMakerLockRecord;
  makerChangeOutputRow: CovenantControlsBuildSourceRow | null;
}): { tracked: boolean; removed_source_holder_outpoints: string[]; maker_change_holder_outpoint: string | null } {
  const store = readOmaL1TrackedAssetStore(params.repoRootPath, params.userId);
  const templateRecord = kcc20AtomicSwapMakerChangeTemplateRecord(store, params.atomicRecord);
  const makerChangeRecord = kcc20AtomicSwapMakerChangeTrackedAssetCandidate({
    atomicRecord: params.atomicRecord,
    templateRecord,
    outputRow: params.makerChangeOutputRow
  });
  const sourceOutpoints = Array.isArray(params.atomicRecord.source_holder_outpoints)
    ? params.atomicRecord.source_holder_outpoints.map((outpoint) => String(outpoint || "").trim()).filter(Boolean)
    : [];

  replaceOmaL1TrackedAssetRecordsAfterHolderTransfer(params.repoRootPath, params.userId, sourceOutpoints, makerChangeRecord ? [makerChangeRecord] : []);

  return {
    tracked: !!makerChangeRecord,
    removed_source_holder_outpoints: sourceOutpoints,
    maker_change_holder_outpoint: makerChangeRecord?.holder?.outpoint || null
  };
}


function kcc20AtomicSwapTakerClaimTrackedAssetCandidate(params: {
  atomicRecord: Kcc20AtomicSwapMakerLockRecord;
  templateRecord: OmaL1TrackedAssetRecord | null;
  submittedTxid: string;
  holderOutputIndex: number;
  holderOutputRow: CovenantControlsBuildSourceRow | null;
  holderScriptPublicKeyJsonSha256: string | null;
  walletId: string;
}): OmaL1TrackedAssetRecord | null {
  const { atomicRecord, templateRecord, submittedTxid, holderOutputIndex, holderOutputRow, holderScriptPublicKeyJsonSha256, walletId } = params;
  if (!templateRecord) return null;

  const assetCovenantId = String(atomicRecord.asset_covenant_id || atomicRecord.covenant_id || "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(assetCovenantId)) return null;

  const ownerAddress = String(atomicRecord.taker_token_receive_address || "").trim();
  const holderAmountRaw = String(atomicRecord.lock_amount_raw || atomicRecord.swap_locked_holder_amount_raw || "0").trim();
  const holderCarrierSompi = String(holderOutputRow?.amount_sompi || atomicRecord.swap_locked_holder_carrier_sompi || atomicRecord.amount_sompi || "0").trim();
  const holderOutpoint = holderOutputRow ? (covenantInputOutpointKey(holderOutputRow) || `${submittedTxid}:${holderOutputIndex}`) : `${submittedTxid}:${holderOutputIndex}`;
  const holderScriptSha = String(holderScriptPublicKeyJsonSha256 || "").trim() || null;
  const holderDecimals = Number(atomicRecord.decimals ?? templateRecord.decimals ?? 0);
  if (!ownerAddress || !/^\d+$/.test(holderAmountRaw) || BigInt(holderAmountRaw) <= 0n || !holderOutpoint || !Number.isSafeInteger(holderDecimals) || holderDecimals < 0) return null;
  const compactHolder = omaBuildL1CompactAddressHolderEnvelopeProof({
    tokenSymbol: String(atomicRecord.token_symbol || templateRecord.token_symbol || ""),
    decimals: holderDecimals,
    holderAmountRaw: BigInt(holderAmountRaw),
    ownerAddress,
    networkId: String(atomicRecord.networkId || templateRecord.networkId || "")
  });
  const holderAddress = String(compactHolder.p2sh_address || "").trim();
  if (!holderAddress) return null;
  if (holderOutputRow) {
    const rowCovenantId = String(holderOutputRow.covenant_id || "").trim().toLowerCase();
    if (rowCovenantId !== assetCovenantId) return null;
  }

  let ownerPublicKey = "";
  try {
    ownerPublicKey = XOnlyPublicKey.fromAddress(new Address(ownerAddress) as any).toString();
  } catch {
    ownerPublicKey = String(templateRecord.owner_public_key || "");
  }
  if (!/^[0-9a-f]{64}$/i.test(ownerPublicKey)) return null;

  const now = new Date().toISOString();
  return {
    record_kind: "oma_l1_tracked_asset_record_v1",
    record_status: "candidate_requires_live_reverification",
    created_at: now,
    updated_at: now,
    source: "kcc20_atomic_swap_taker_claim_auto_track_v1",
    networkId: atomicRecord.networkId,
    wallet_id: String(walletId || templateRecord.wallet_id || ""),
    owner_public_key: ownerPublicKey,
    owner_identifier: ownerAddress,
    issuer_identifier: atomicRecord.issuer_identifier,
    token_name: atomicRecord.token_name,
    token_symbol: atomicRecord.token_symbol,
    decimals: atomicRecord.decimals,
    max_supply_raw: atomicRecord.max_supply_raw,
    issued_supply_raw: atomicRecord.issued_supply_raw,
    holder_amount_raw: holderAmountRaw,
    transfer_rule: atomicRecord.transfer_rule,
    policy_hash: atomicRecord.policy_hash,
    asset_covenant_id: assetCovenantId,
    controller: { ...templateRecord.controller },
    holder: {
      address: holderAddress,
      outpoint: holderOutpoint,
      carrier_sompi: holderCarrierSompi,
      script_public_key_script: null,
      script_public_key_json_sha256: holderScriptSha,
      redeem_script_hex_sha256: compactHolder.redeem_script_hex_sha256,
      state_schema: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA
    }
  };
}

function kcc20AtomicSwapTrackTakerClaimHolder(params: {
  repoRootPath: string;
  userId: string;
  atomicRecord: Kcc20AtomicSwapMakerLockRecord;
  submittedTxid: string;
  holderOutputIndex: number;
  holderOutputRow: CovenantControlsBuildSourceRow | null;
  holderScriptPublicKeyJsonSha256: string | null;
  walletId: string;
}): { tracked: boolean; holder_outpoint: string | null } {
  const store = readOmaL1TrackedAssetStore(params.repoRootPath, params.userId);
  const templateRecord = kcc20AtomicSwapMakerChangeTemplateRecord(store, params.atomicRecord);
  const takerRecord = kcc20AtomicSwapTakerClaimTrackedAssetCandidate({
    atomicRecord: params.atomicRecord,
    templateRecord,
    submittedTxid: params.submittedTxid,
    holderOutputIndex: params.holderOutputIndex,
    holderOutputRow: params.holderOutputRow,
    holderScriptPublicKeyJsonSha256: params.holderScriptPublicKeyJsonSha256,
    walletId: params.walletId
  });

  replaceOmaL1TrackedAssetRecordsAfterHolderTransfer(params.repoRootPath, params.userId, [], takerRecord ? [takerRecord] : []);

  return {
    tracked: !!takerRecord,
    holder_outpoint: takerRecord?.holder?.outpoint || null
  };
}

