function programmableKasMetadataText(value: any): string | null {

  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  if (!text || text === "null" || text === "undefined") return null;
  return text;
}

function programmableKasMetadataField(label: string, value: any, valueKind = "text"): { label: string; value: string; value_kind: string } | null {
  const text = programmableKasMetadataText(value);
  if (!text) return null;
  return { label, value: text, value_kind: valueKind };
}

function programmableKasMetadataFields(fields: Array<{ label: string; value: any; value_kind?: string }>): Array<{ label: string; value: string; value_kind: string }> {
  return fields
    .map((field) => programmableKasMetadataField(field.label, field.value, field.value_kind || "text"))
    .filter((field): field is { label: string; value: string; value_kind: string } => !!field);
}

function programmableKasMetadataAreaForInspectionRow(args: {
  classified: {
    classification?: string;
    label?: string;
    asset_kind?: string;
    normal_send_eligible?: boolean;
    warning?: string | null;
    warning_class?: string | null;
    template_id?: string | null;
    template_name?: string | null;
    template_version?: string | null;
    proof_status?: string | null;
  };
  amount_kas: string | null;
  amount_sompi: string | null;
  covenant_id: string | null;
  outpoint_text: string | null;
  safe_record_kind: string | null;
  safe_record: any | null;
}): any {
  const classified = args.classified || {};
  const record = args.safe_record || {};
  const safeRecordKind = programmableKasMetadataText(args.safe_record_kind) || null;
  const title = programmableKasMetadataText(classified.label) || programmableKasMetadataText(classified.classification) || "KAS UTXO";
  const warning = programmableKasMetadataText(classified.warning);
  let purpose = warning || "Native KAS output.";
  const policyFields: Array<{ label: string; value: any; value_kind?: string }> = [];

  if (safeRecordKind === "protect_kas") {
    purpose = "Protect KAS: KAS transferred into a covenant-bearing output assigned to the configured holder address. Normal KAS send must not spend this output until it is released.";
    policyFields.push(
      { label: "Creator address", value: record.from_address || record.creator_address, value_kind: "address" },
      { label: "Protected holder address", value: record.destination_address, value_kind: "address" },
      { label: "Destination source", value: record.destination_address_source },
      { label: "Change address", value: record.change_address, value_kind: "address" },
      { label: "Funding source outpoint", value: record.selected_outpoint_key, value_kind: "outpoint" }
    );
  } else if (safeRecordKind === "immediate_recovery") {
    purpose = "Immediate Recovery KAS: the owner wallet or the configured recovery wallet can release this covenanted KAS output.";
    policyFields.push(
      { label: "Owner release address", value: record.owner_address, value_kind: "address" },
      { label: "Recovery address", value: record.recovery_address, value_kind: "address" },
      { label: "Viewer role", value: record.viewer_role },
      { label: "P2SH policy address", value: record.p2sh_immediate_recovery_address, value_kind: "address" }
    );
  } else if (safeRecordKind === "owner_release_delayed_recovery") {
    purpose = "Owner Release + Delayed Recovery KAS: the owner wallet can release immediately; the recovery wallet can release only after the configured DAA target is satisfied.";
    policyFields.push(
      { label: "Owner release address", value: record.owner_address, value_kind: "address" },
      { label: "Recovery address", value: record.recovery_address, value_kind: "address" },
      { label: "Recovery DAA delta", value: record.recovery_lock_daa_delta, value_kind: "daa" },
      { label: "Recovery target DAA", value: record.recovery_lock_target_daa, value_kind: "daa" },
      { label: "Current DAA", value: record.current_virtual_daa_score, value_kind: "daa" },
      { label: "Recovery target satisfied", value: record.recovery_target_satisfied === true ? "yes" : record.recovery_target_satisfied === false ? "no" : null },
      { label: "Viewer role", value: record.viewer_role },
      { label: "P2SH policy address", value: record.p2sh_owner_release_delayed_recovery_address, value_kind: "address" }
    );
  } else if (safeRecordKind === "absolute_time_lock") {
    purpose = "Absolute Time Lock KAS: the owner wallet can release this covenanted KAS only after the configured DAA target is satisfied.";
    policyFields.push(
      { label: "Owner release address", value: record.owner_address, value_kind: "address" },
      { label: "Lock DAA delta", value: record.lock_daa_delta, value_kind: "daa" },
      { label: "Start DAA at build", value: record.current_virtual_daa_score_at_build, value_kind: "daa" },
      { label: "Lock target DAA", value: record.lock_target_daa, value_kind: "daa" },
      { label: "Current DAA", value: record.current_virtual_daa_score, value_kind: "daa" },
      { label: "Target satisfied", value: record.target_satisfied === true ? "yes" : record.target_satisfied === false ? "no" : null },
      { label: "P2SH policy address", value: record.p2sh_absolute_time_lock_address, value_kind: "address" }
    );
  } else if (safeRecordKind === "relative_sequence_lock") {
    purpose = "Relative Sequence Lock KAS: the owner wallet can release this covenanted KAS only after the source output reaches the configured relative DAA age.";
    policyFields.push(
      { label: "Owner release address", value: record.owner_address, value_kind: "address" },
      { label: "Relative DAA delta", value: record.relative_daa_delta, value_kind: "daa" },
      { label: "Source block DAA", value: record.source_block_daa_score, value_kind: "daa" },
      { label: "Relative unlock DAA", value: record.relative_unlock_daa_score, value_kind: "daa" },
      { label: "Current DAA", value: record.current_virtual_daa_score, value_kind: "daa" },
      { label: "Target satisfied", value: record.target_satisfied === true ? "yes" : record.target_satisfied === false ? "no" : null },
      { label: "P2SH policy address", value: record.p2sh_relative_sequence_lock_address, value_kind: "address" }
    );
  } else if (safeRecordKind === "allowed_destination") {
    purpose = "Allowed Destination KAS: release must pay exactly one output to the configured destination and must be signed by the owner wallet.";
    policyFields.push(
      { label: "Owner release address", value: record.owner_address, value_kind: "address" },
      { label: "Allowed destination address", value: record.allowed_destination_address, value_kind: "address" },
      { label: "P2SH policy address", value: record.p2sh_allowed_destination_address, value_kind: "address" }
    );
  } else if (safeRecordKind === "absolute_time_lock_allowed_destination") {
    purpose = "Time Lock + Allowed Destination KAS: the owner wallet can release only after the configured DAA target, and release must pay exactly one output to the configured destination.";
    policyFields.push(
      { label: "Owner release address", value: record.owner_address, value_kind: "address" },
      { label: "Allowed destination address", value: record.allowed_destination_address, value_kind: "address" },
      { label: "Lock DAA delta", value: record.lock_daa_delta, value_kind: "daa" },
      { label: "Start DAA at build", value: record.current_virtual_daa_score_at_build, value_kind: "daa" },
      { label: "Lock target DAA", value: record.lock_target_daa, value_kind: "daa" },
      { label: "Current DAA", value: record.current_virtual_daa_score, value_kind: "daa" },
      { label: "Target satisfied", value: record.target_satisfied === true ? "yes" : record.target_satisfied === false ? "no" : null },
      { label: "P2SH policy address", value: record.p2sh_absolute_time_lock_allowed_destination_address, value_kind: "address" }
    );
  } else if (safeRecordKind === "escrow_refund") {
    purpose = "Escrow / Refund KAS: seller release can pay the configured seller address; buyer refund can pay the configured buyer/refund address only after the configured DAA timeout.";
    policyFields.push(
      { label: "Buyer/refund address", value: record.buyer_refund_address, value_kind: "address" },
      { label: "Seller release address", value: record.seller_release_address, value_kind: "address" },
      { label: "Refund lock DAA", value: record.refund_lock_daa, value_kind: "daa" },
      { label: "Current DAA", value: record.current_virtual_daa_score, value_kind: "daa" },
      { label: "Refund target satisfied", value: record.refund_target_satisfied === true ? "yes" : record.refund_target_satisfied === false ? "no" : null },
      { label: "P2SH policy address", value: record.p2sh_escrow_refund_address, value_kind: "address" }
    );
  } else if (safeRecordKind === "atomic_swap") {
    purpose = "KCC20 Atomic Swap maker lock: token holder state is locked to a script-hash policy. Taker claim must pay the configured KAS amount to the maker and send the token to the configured taker address; maker refund requires the DAA timeout.";
    policyFields.push(
      { label: "Token", value: record.token_symbol },
      { label: "Locked token amount", value: record.lock_amount_raw },
      { label: "Maker KAS receive address", value: record.maker_kas_receive_address, value_kind: "address" },
      { label: "Maker token refund address", value: record.maker_token_refund_address, value_kind: "address" },
      { label: "Taker token receive address", value: record.taker_token_receive_address, value_kind: "address" },
      { label: "KAS price sompi", value: record.kas_price_sompi },
      { label: "Refund lock DAA", value: record.refund_lock_daa, value_kind: "daa" },
      { label: "Current DAA", value: record.current_virtual_daa_score, value_kind: "daa" },
      { label: "Refund target satisfied", value: record.refund_target_satisfied === true ? "yes" : record.refund_target_satisfied === false ? "no" : null },
      { label: "Policy body hash", value: record.policy_body_redeem_script_sha256 },
      { label: "Swap locked holder address", value: record.swap_locked_holder_address, value_kind: "address" }
    );
  } else if (classified.classification === "programmable_kas_p2sh_owner_release_kas") {
    purpose = "P2SH Owner-Release KAS: release requires the owner wallet signature. Normal KAS send must not spend this covenanted output.";
  } else if (args.covenant_id) {
    purpose = warning || "Covenant-bearing KAS under contract. Normal KAS send must not spend this output unless the policy release path is used.";
  }

  const commonFields = programmableKasMetadataFields([
    { label: "What this UTXO covenant does", value: purpose },
    { label: "Policy label", value: title },
    { label: "Classification", value: classified.classification },
    { label: "Normal KAS send", value: classified.normal_send_eligible === true ? "eligible" : "blocked" },
    { label: "Amount", value: args.amount_kas ? `${args.amount_kas} KAS` : null },
    { label: "Amount sompi", value: args.amount_sompi },
    { label: "Source outpoint", value: record.source_outpoint_key || args.outpoint_text, value_kind: "outpoint" },
    { label: "Covenant ID", value: args.covenant_id || record.covenant_id, value_kind: "covenant_id" },
    { label: "Record status", value: record.record_status },
    { label: "Created", value: record.created_at, value_kind: "timestamp" },
    { label: "Submitted txid", value: record.submitted_txid, value_kind: "txid" },
    { label: "Release status", value: record.release_status },
    { label: "Release txid", value: record.release_txid, value_kind: "txid" },
    { label: "Released output", value: record.released_output_outpoint, value_kind: "outpoint" },
    { label: "Template ID", value: classified.template_id },
    { label: "Proof status", value: classified.proof_status }
  ]);

  return {
    metadata_kind: "programmable_kas_utxo_metadata_area_v1",
    metadata_status: safeRecordKind ? "tracked_policy_metadata" : args.covenant_id ? "covenant_classification_metadata" : "native_kas_metadata",
    display_title: title,
    policy_summary: purpose,
    warning,
    warning_class: classified.warning_class || null,
    source_record_kind: safeRecordKind,
    fields: [...commonFields, ...programmableKasMetadataFields(policyFields)]
  };
}

function classifyCovenantUtxo(
  registry: CovenantTemplateRegistry,
  networkId: string,
  covenantId: string | null
): {
  classification: CovenantUtxoClassification;
  label: string;
  asset_kind: string;
  normal_send_eligible: boolean;
  token: boolean;
  warning: string | null;
  warning_class: string | null;
  registry_match: boolean;
  template_id: string | null;
  template_name: string | null;
  template_version: string | null;
  contract_type: string | null;
  proof_status: string | null;
} {
  const normalized = String(covenantId || "").trim().toLowerCase();

  if (!normalized) {
    const native = registry.classification_policy?.native_kas || {};
    return {
      classification: native.classification || "native_kas",
      label: "Native KAS",
      asset_kind: native.asset_kind || "native_kas",
      normal_send_eligible: native.normal_send_eligible !== false,
      token: native.token === true,
      warning: native.warning || null,
      warning_class: native.warning_class || null,
      registry_match: false,
      template_id: null,
      template_name: null,
      template_version: null,
      contract_type: null,
      proof_status: null
    };
  }

  const template = covenantRegistryTemplateForCovenantId(registry, networkId, normalized);
  if (template) {
    return {
      classification: template.classification || "unknown_covenanted_kas",
      label: template.template_name || "Registered covenant template",
      asset_kind: template.asset_kind || "kas_under_contract",
      normal_send_eligible: template.normal_send_eligible === true,
      token: template.token === true,
      warning: template.warning || null,
      warning_class: template.warning_class || null,
      registry_match: true,
      template_id: template.template_id || null,
      template_name: template.template_name || null,
      template_version: template.template_version || null,
      contract_type: template.contract_type || null,
      proof_status: template.proof_status || null
    };
  }

  const unknown = registry.classification_policy?.unknown_covenant || {};
  return {
    classification: unknown.classification || "unknown_covenanted_kas",
    label: "Unknown covenanted KAS",
    asset_kind: unknown.asset_kind || "kas_under_contract",
    normal_send_eligible: false,
    token: false,
    warning: unknown.warning || "Unknown covenant-bearing UTXO. Normal KAS send must not spend this output.",
    warning_class: unknown.warning_class || "unknown_covenant_normal_send_blocked",
    registry_match: false,
    template_id: null,
    template_name: null,
    template_version: null,
    contract_type: null,
    proof_status: null
  };
}

