function covenantInputOutpointKey(row: CovenantControlsBuildSourceRow): string | null {
  return row.outpoint.transaction_id && row.outpoint.index !== null
    ? `${row.outpoint.transaction_id}:${row.outpoint.index}`
    : row.outpoint.text;
}

function covenantIsCoinbaseReference(reference: any): boolean {
  const entry = covenantReferenceEntry(reference);
  return reference?.isCoinbase === true || entry?.isCoinbase === true || reference?.utxo?.isCoinbase === true || reference?.utxoEntry?.isCoinbase === true;
}

function covenantBuildSourceRow(reference: any, index: number): CovenantControlsBuildSourceRow {
  const covenant = covenantIdFromReference(reference);
  const amount_sompi = covenantAmountSompiFromReference(reference);
  const outpoint = covenantOutpointFromReference(reference);
  return {
    index,
    amount_sompi,
    amount_kas: sompiTextToKasText(amount_sompi),
    block_daa_score: covenantBlockDaaScoreFromReference(reference),
    outpoint,
    covenant_present: covenant.present,
    covenant_id: covenant.value,
    covenant_path: covenant.path,
    is_coinbase: covenantIsCoinbaseReference(reference)
  };
}

function selectCovenantControlsBuildSource(entries: any[], amountSompi: bigint, feeReserveSompi: bigint): { reference: any; row: CovenantControlsBuildSourceRow } | null {
  const requiredSompi = amountSompi + feeReserveSompi;
  const candidates = entries
    .map((entry, index) => ({ reference: entry, row: covenantBuildSourceRow(entry, index) }))
    .filter(({ row }) => {
      if (row.covenant_present) return false;
      if (row.is_coinbase) return false;
      if (!row.amount_sompi || !/^[0-9]+$/.test(row.amount_sompi)) return false;
      return BigInt(row.amount_sompi) > requiredSompi;
    })
    .sort((a, b) => {
      const aAmount = BigInt(a.row.amount_sompi || "0");
      const bAmount = BigInt(b.row.amount_sompi || "0");
      if (aAmount < bAmount) return -1;
      if (aAmount > bAmount) return 1;
      return a.row.index - b.row.index;
    });

  return candidates[0] || null;
}

function selectCovenantControlsReleaseSource(
  entries: any[],
  sourceOutpointKey: string,
  expectedCovenantId: string
): { reference: any; row: CovenantControlsBuildSourceRow } | null {
  const normalizedOutpoint = String(sourceOutpointKey || "").trim();
  const normalizedCovenantId = String(expectedCovenantId || "").trim().toLowerCase();

  if (!normalizedOutpoint || !normalizedCovenantId) return null;

  const candidates = entries.map((entry, index) => ({ reference: entry, row: covenantBuildSourceRow(entry, index) }));
  return candidates.find(({ row }) => {
    const outpointKey = covenantInputOutpointKey(row);
    const rowCovenantId = String(row.covenant_id || "").trim().toLowerCase();
    return outpointKey === normalizedOutpoint && row.covenant_present === true && rowCovenantId === normalizedCovenantId;
  }) || null;
}

function covenantControlsSummarizeTxOutput(output: any, index: number): any {
  const covenant = output?.covenant;
  return {
    index,
    value: output?.value !== undefined ? covenantPrintable(output.value) : null,
    scriptPublicKey: output?.scriptPublicKey && typeof output.scriptPublicKey.toJSON === "function" ? output.scriptPublicKey.toJSON() : null,
    covenant_present: !!covenant,
    covenant: covenant && typeof covenant.toJSON === "function" ? covenant.toJSON() : null
  };
}

function covenantControlsSummarizeTxInput(input: any, index: number): any {
  return {
    index,
    previousOutpoint: input?.previousOutpoint && typeof input.previousOutpoint.toJSON === "function" ? input.previousOutpoint.toJSON() : input?.previousOutpoint,
    signatureScript_present: typeof input?.signatureScript === "string" && input.signatureScript.length > 0,
    signatureScript_length: typeof input?.signatureScript === "string" ? input.signatureScript.length : null,
    sequence: input?.sequence !== undefined ? covenantPrintable(input.sequence) : null,
    sigOpCount: input?.sigOpCount ?? null,
    computeBudget: input?.computeBudget ?? null,
    utxo_present: !!input?.utxo
  };
}

function requirePositiveSompiInput(value: any, fieldName: string): bigint {
  const sompi = readSompi(value);
  if (sompi === null || sompi <= 0n) {
    throw new Error(`${fieldName}_must_be_positive_integer_sompi`);
  }
  return sompi;
}

function requireTransactionSafeJson(tx: any): string {
  if (!tx || typeof tx.serializeToSafeJSON !== "function") {
    throw new Error("transaction_serialize_to_safe_json_missing");
  }
  const safeJson = tx.serializeToSafeJSON();
  if (typeof safeJson !== "string" || !safeJson.trim()) {
    throw new Error("transaction_safe_json_empty");
  }
  return safeJson;
}

function covenantSha256Text(value: string): string {
  return createHash("sha256").update(String(value || ""), "utf8").digest("hex");
}

