function covenantControlsSubmitToken(): string {
  return randomUUID();
}

function covenantTxInputOutpointKey(input: any): string | null {
  const raw = input?.previousOutpoint && typeof input.previousOutpoint.toJSON === "function"
    ? input.previousOutpoint.toJSON()
    : input?.previousOutpoint;

  if (!raw) return null;
  if (typeof raw === "string") return raw;

  const transactionId = covenantPrintable(raw.transactionId ?? raw.transaction_id ?? raw.txid);
  const indexRaw = raw.index ?? raw.outputIndex ?? raw.output_index;
  const index = indexRaw === null || indexRaw === undefined ? null : Number(indexRaw);
  if (transactionId && Number.isInteger(index)) return `${transactionId}:${index}`;
  return null;
}

function covenantOutputCovenantId(output: any): string | null {
  const covenant = output?.covenant;
  if (!covenant) return null;
  if (typeof covenant.toJSON === "function") {
    const json = covenant.toJSON();
    return covenantPrintable(json?.covenantId ?? json?.covenant_id);
  }
  return covenantPrintable(covenant.covenantId ?? covenant.covenant_id);
}

function covenantOutputAddress(output: any, networkId: string): string | null {
  try {
    if (!output?.scriptPublicKey) return null;
    const addr = addressFromScriptPublicKey(output.scriptPublicKey, networkId);
    return addr ? addr.toString() : null;
  } catch {
    return null;
  }
}

function covenantOutputValueSompi(output: any): string | null {
  return output?.value !== undefined ? covenantPrintable(output.value) : null;
}

function covenantOutputScriptPublicKeyJsonSha256(output: any): string | null {
  const scriptPublicKey = output?.scriptPublicKey;
  if (!scriptPublicKey) return null;
  const json = typeof scriptPublicKey.toJSON === "function" ? scriptPublicKey.toJSON() : scriptPublicKey;
  try {
    return covenantSha256Text(JSON.stringify(json));
  } catch {
    return null;
  }
}

function covenantSignatureScriptIsPresentHex(input: any): boolean {
  const script = typeof input?.signatureScript === "string" ? input.signatureScript.trim() : "";
  return !!script && script.length % 2 === 0 && /^[0-9a-f]+$/i.test(script);
}

function readSignedCovenantSafeJsonFromBody(body: any): string {
  const candidates = [
    body?.signedTxSafeJson,
    body?.signed_tx_safe_json,
    body?.signedSafeJson,
    body?.signed_safe_json,
    Array.isArray(body?.signed_txs) ? body.signed_txs[0] : null
  ];

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim()) return candidate.trim();
  }

  throw new Error("signed_tx_safe_json_required");
}

function summarizeCovenantPostSubmitRows(entries: any[], networkId: string): CovenantControlsBuildSourceRow[] {
  return entries.map((entry: any, index: number) => covenantBuildSourceRow(entry, index)).map((row) => ({
    ...row,
    amount_kas: sompiTextToKasText(row.amount_sompi),
    covenant_id: row.covenant_id ? String(row.covenant_id).toLowerCase() : row.covenant_id
  }));
}

type OmaL1TokenStateRole = "controller" | "holder";

type OmaL1TokenStateEnvelopeProof = {
  role: OmaL1TokenStateRole;
  state_schema: string;
  canonical_json: string;
  canonical_json_sha256: string;
  canonical_json_byte_len: number;
  envelope_hex: string;
  envelope_hex_byte_len: number;
  decoded_fields: any;
  decode_round_trip_ok: boolean;
  redeem_script_hex: string;
  redeem_script_hex_sha256: string;
  redeem_script_hex_byte_len: number;
  output_script_form: "p2sh_state_envelope_commitment";
  script_public_key: InstanceType<typeof ScriptPublicKey>;
  script_public_key_json: any;
  p2sh_script_public_key_json_sha256: string | null;
  script_contains_state_envelope: boolean;
};

function omaStableJson(value: any): string {
  const normalize = (v: any): any => {
    if (v === null || v === undefined) return v === undefined ? null : null;
    if (typeof v === "bigint") return v.toString();
    if (Array.isArray(v)) return v.map(normalize);
    if (typeof v === "object") {
      const out: Record<string, any> = {};
      for (const key of Object.keys(v).sort()) {
        out[key] = normalize(v[key]);
      }
      return out;
    }
    return v;
  };
  return JSON.stringify(normalize(value));
}

function omaSha256Text(value: string): string {
  return createHash("sha256").update(String(value || ""), "utf8").digest("hex");
}

function omaReadNonnegativeRawInteger(value: any, fieldName: string): bigint {
  const text = String(value ?? "").trim();
  if (!/^\d+$/.test(text)) throw new Error(`${fieldName}_must_be_unsigned_integer_string`);
  return BigInt(text);
}

function omaReadUintNumber(value: any, fieldName: string, min: number, max: number): number {
  const text = String(value ?? "").trim();
  if (!/^\d+$/.test(text)) throw new Error(`${fieldName}_must_be_unsigned_integer`);
  const parsed = Number(text);
  if (!Number.isInteger(parsed) || parsed < min || parsed > max) throw new Error(`${fieldName}_out_of_range`);
  return parsed;
}

function omaSafeSymbol(value: any): string {
  const symbol = String(value || "").trim().toUpperCase();
  if (!/^[A-Z0-9]{2,16}$/.test(symbol)) throw new Error("token_symbol_invalid");
  return symbol;
}

function omaSafeText(value: any, fieldName: string, maxLen: number): string {
  const text = String(value || "").trim();
  if (!text) throw new Error(`${fieldName}_required`);
  if (text.length > maxLen) throw new Error(`${fieldName}_too_long`);
  return text;
}

function omaSafeOptionalText(value: any, maxLen: number): string | null {
  const text = String(value || "").trim();
  if (!text) return null;
  if (text.length > maxLen) throw new Error("optional_text_too_long");
  return text;
}

type OmaL1TokenEnvelopeFieldParams = {
  role: OmaL1TokenStateRole;
  tokenName: string;
  tokenSymbol: string;
  decimals: number;
  maxSupplyRaw: bigint;
  issuedSupplyRaw: bigint;
  holderAmountRaw: bigint;
  ownerIdentifier: string;
  issuerIdentifier: string;
  transferRule: string;
  policyHash: string | null;
};

function omaBuildL1TokenEnvelopeFields(params: OmaL1TokenEnvelopeFieldParams): any {
  const common = {
    magic: OMA_L1_TOKEN_STATE_MAGIC,
    standard_id: OMA_L1_TOKEN_STANDARD_ID,
    asset_covenant_id: "output.covenant.covenantId",
    token_name: params.tokenName,
    token_symbol: params.tokenSymbol,
    decimals: params.decimals,
    transfer_rule: params.transferRule,
    policy_hash: params.policyHash || null
  };

  if (params.role === "controller") {
    return {
      ...common,
      schema: OMA_L1_TOKEN_CONTROLLER_STATE_SCHEMA,
      role: "controller",
      issuer_identifier_type: "address",
      issuer_identifier: params.issuerIdentifier,
      max_supply_raw: params.maxSupplyRaw.toString(),
      issued_supply_raw: params.issuedSupplyRaw.toString(),
      minting_enabled: true,
      burning_enabled: false
    };
  }

  return {
    ...common,
    schema: OMA_L1_TOKEN_HOLDER_STATE_SCHEMA,
    role: "holder",
    owner_identifier_type: "address",
    owner_identifier: params.ownerIdentifier,
    amount_raw: params.holderAmountRaw.toString()
  };
}

function omaBuildL1TokenCompactControllerEnvelopeFields(params: OmaL1TokenEnvelopeFieldParams): any {
  const fields: any = {
    m: "OMA1",
    schema: OMA_L1_TOKEN_CONTROLLER_COMPACT_STATE_SCHEMA,
    role: "controller",
    a: "output.covenant.covenantId",
    t: params.tokenSymbol,
    d: params.decimals,
    i: params.issuerIdentifier,
    x: params.maxSupplyRaw.toString(),
    u: params.issuedSupplyRaw.toString(),
    r: params.transferRule
  };
  if (params.policyHash) fields.p = params.policyHash;
  return fields;
}

function omaBuildL1TokenControllerEnvelopeFields(params: OmaL1TokenEnvelopeFieldParams, stateSchema?: string): any {
  if (stateSchema === OMA_L1_TOKEN_CONTROLLER_COMPACT_STATE_SCHEMA) {
    return omaBuildL1TokenCompactControllerEnvelopeFields(params);
  }
  return omaBuildL1TokenEnvelopeFields(params);
}

type OmaL1TokenCompactHolderOwnerType = "address" | "script_hash" | "covenant_id";

type OmaL1TokenCompactHolderFieldParams = {
  tokenSymbol: string;
  decimals: number;
  holderAmountRaw: bigint;
  ownerIdentifierType: OmaL1TokenCompactHolderOwnerType;
  ownerIdentifier: string;
};

function omaNormalizeCompactHolderOwnerIdentifier(ownerType: OmaL1TokenCompactHolderOwnerType, ownerIdentifier: string): string {
  const value = String(ownerIdentifier || "").trim();
  if (ownerType === OMA_L1_TOKEN_HOLDER_OWNER_TYPE_ADDRESS) {
    if (!value) throw new Error("compact_holder_owner_address_required");
    return value;
  }
  const hex = value.toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(hex)) throw new Error("compact_holder_owner_identifier_64_hex_required");
  return hex;
}

function omaBuildL1TokenCompactHolderEnvelopeFields(params: OmaL1TokenCompactHolderFieldParams): any {
  const ownerType = params.ownerIdentifierType;
  if (![OMA_L1_TOKEN_HOLDER_OWNER_TYPE_ADDRESS, OMA_L1_TOKEN_HOLDER_OWNER_TYPE_SCRIPT_HASH, OMA_L1_TOKEN_HOLDER_OWNER_TYPE_COVENANT_ID].includes(ownerType)) {
    throw new Error("compact_holder_owner_type_unsupported");
  }

  return {
    m: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_MAGIC,
    schema: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA,
    role: "holder",
    a: "output.covenant.covenantId",
    t: params.tokenSymbol,
    d: params.decimals,
    ot: ownerType,
    oi: omaNormalizeCompactHolderOwnerIdentifier(ownerType, params.ownerIdentifier),
    q: params.holderAmountRaw.toString()
  };
}

function omaBuildL1CompactAddressHolderEnvelopeProof(params: {
  tokenSymbol: string;
  decimals: number;
  holderAmountRaw: bigint;
  ownerAddress: string;
  networkId: string;
}): OmaL1TokenStateEnvelopeProof & { owner_address: string; owner_address_version: string; owner_address_from_public_key: string; owner_public_key_sha256: string; p2sh_address: string | null } {
  const ownerAddressObject = new Address(params.ownerAddress);
  const ownerAddressVersion = String((ownerAddressObject as any).version || "");
  const ownerXOnlyPublicKey = XOnlyPublicKey.fromAddress(ownerAddressObject as any);
  const ownerXOnlyPublicKeyHex = ownerXOnlyPublicKey.toString();
  if (!/^[0-9a-f]{64}$/i.test(ownerXOnlyPublicKeyHex)) throw new Error("compact_holder_owner_public_key_invalid");
  const ownerAddressFromPublicKey = ownerXOnlyPublicKey.toAddress(params.networkId as any).toString();
  if (ownerAddressFromPublicKey !== ownerAddressObject.toString()) throw new Error("compact_holder_owner_public_key_address_mismatch");

  const fields = omaBuildL1TokenCompactHolderEnvelopeFields({
    tokenSymbol: params.tokenSymbol,
    decimals: params.decimals,
    holderAmountRaw: params.holderAmountRaw,
    ownerIdentifierType: OMA_L1_TOKEN_HOLDER_OWNER_TYPE_ADDRESS as OmaL1TokenCompactHolderOwnerType,
    ownerIdentifier: ownerAddressObject.toString()
  });
  const proof = omaBuildStateEnvelopeScriptPublicKey({
    role: "holder",
    ownerXOnlyPublicKey: ownerXOnlyPublicKeyHex,
    fields
  });
  const p2shAddress = addressFromScriptPublicKey(proof.script_public_key as any, params.networkId as any);
  return {
    ...proof,
    owner_address: ownerAddressObject.toString(),
    owner_address_version: ownerAddressVersion,
    owner_address_from_public_key: ownerAddressFromPublicKey,
    owner_public_key_sha256: covenantSha256Text(ownerXOnlyPublicKeyHex),
    p2sh_address: p2shAddress ? p2shAddress.toString() : null
  };
}

function omaBuildL1CompactScriptHashHolderEnvelopeProof(params: {
  tokenSymbol: string;
  decimals: number;
  holderAmountRaw: bigint;
  policyBodyRedeemScriptHex: string;
  networkId: string;
}): OmaL1TokenStateEnvelopeProof & { owner_identifier_type: "script_hash"; owner_identifier: string; p2sh_address: string | null } {
  const policyBodyHex = String(params.policyBodyRedeemScriptHex || "").trim().toLowerCase();
  if (!/^[0-9a-f]+$/.test(policyBodyHex) || policyBodyHex.length % 2 !== 0) throw new Error("compact_holder_policy_body_redeem_script_hex_invalid");
  const policyBodyHash = covenantSha256Text(policyBodyHex);
  const fields = omaBuildL1TokenCompactHolderEnvelopeFields({
    tokenSymbol: params.tokenSymbol,
    decimals: params.decimals,
    holderAmountRaw: params.holderAmountRaw,
    ownerIdentifierType: OMA_L1_TOKEN_HOLDER_OWNER_TYPE_SCRIPT_HASH as OmaL1TokenCompactHolderOwnerType,
    ownerIdentifier: policyBodyHash
  });
  const canonicalJson = omaStableJson(fields);
  const envelopeHex = Buffer.from(canonicalJson, "utf8").toString("hex");
  const decoded = JSON.parse(Buffer.from(envelopeHex, "hex").toString("utf8"));
  const decodeRoundTripOk = omaStableJson(decoded) === canonicalJson;
  const builder = ScriptBuilder.fromScript(policyBodyHex)
    .addOp(Opcodes.OpFalse)
    .addOp(Opcodes.OpIf)
    .addData(Buffer.from(canonicalJson, "utf8"))
    .addOp(Opcodes.OpEndIf);
  const scriptPublicKey = builder.createPayToScriptHashScript();
  const redeemScriptHex = builder.drain();
  const scriptPublicKeyJson = typeof scriptPublicKey.toJSON === "function" ? scriptPublicKey.toJSON() : null;
  const p2shAddress = addressFromScriptPublicKey(scriptPublicKey as any, params.networkId as any);
  return {
    role: "holder",
    state_schema: String(fields.schema || ""),
    canonical_json: canonicalJson,
    canonical_json_sha256: omaSha256Text(canonicalJson),
    canonical_json_byte_len: Buffer.byteLength(canonicalJson, "utf8"),
    envelope_hex: envelopeHex,
    envelope_hex_byte_len: envelopeHex.length / 2,
    decoded_fields: decoded,
    decode_round_trip_ok: decodeRoundTripOk,
    redeem_script_hex: redeemScriptHex,
    redeem_script_hex_sha256: omaSha256Text(redeemScriptHex),
    redeem_script_hex_byte_len: redeemScriptHex.length / 2,
    output_script_form: "p2sh_state_envelope_commitment",
    script_public_key: scriptPublicKey,
    script_public_key_json: scriptPublicKeyJson,
    p2sh_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey }),
    script_contains_state_envelope: redeemScriptHex.includes(envelopeHex),
    owner_identifier_type: "script_hash",
    owner_identifier: policyBodyHash,
    p2sh_address: p2shAddress ? p2shAddress.toString() : null
  };
}

function omaBuildL1AtomicDirectSwapCompactHolderInertProof(params: {
  tokenSymbol: string;
  decimals: number;
  holderAmountRaw: bigint;
  assetCovenantId: string;
  makerKasReceiveAddress: string;
  makerTokenRefundAddress: string;
  takerTokenReceiveAddress: string;
  kasPriceSompi: bigint;
  refundLockDaa: bigint;
  networkId: string;
}): any {
  const makerKasAddressObject = new Address(params.makerKasReceiveAddress);
  const makerTokenRefundAddressObject = new Address(params.makerTokenRefundAddress);
  const takerTokenReceiveAddressObject = new Address(params.takerTokenReceiveAddress);

  const makerKasScriptPublicKey = payToAddressScript(makerKasAddressObject as any);
  const makerKasScriptPublicKeyBytes = programmableKasScriptPublicKeyOutputBytesForSpk(makerKasScriptPublicKey as any);
  if (!makerKasScriptPublicKeyBytes) throw new Error("maker_kas_receive_script_public_key_unavailable");

  const makerRefundCompactHolder = omaBuildL1CompactAddressHolderEnvelopeProof({
    tokenSymbol: params.tokenSymbol,
    decimals: params.decimals,
    holderAmountRaw: params.holderAmountRaw,
    ownerAddress: makerTokenRefundAddressObject.toString(),
    networkId: params.networkId
  });
  const makerRefundCompactHolderSpkBytes = programmableKasScriptPublicKeyOutputBytesForSpk(makerRefundCompactHolder.script_public_key as any);
  if (!makerRefundCompactHolderSpkBytes) throw new Error("maker_refund_compact_holder_spk_unavailable");

  const takerCompactHolder = omaBuildL1CompactAddressHolderEnvelopeProof({
    tokenSymbol: params.tokenSymbol,
    decimals: params.decimals,
    holderAmountRaw: params.holderAmountRaw,
    ownerAddress: takerTokenReceiveAddressObject.toString(),
    networkId: params.networkId
  });
  const takerCompactHolderSpkBytes = programmableKasScriptPublicKeyOutputBytesForSpk(takerCompactHolder.script_public_key as any);
  if (!takerCompactHolderSpkBytes) throw new Error("taker_compact_holder_spk_unavailable");
  const takerNativeChangeScriptPublicKey = payToAddressScript(takerTokenReceiveAddressObject as any);
  const takerNativeChangeScriptPublicKeyBytes = programmableKasScriptPublicKeyOutputBytesForSpk(takerNativeChangeScriptPublicKey as any);
  if (!takerNativeChangeScriptPublicKeyBytes) throw new Error("taker_native_change_spk_unavailable");

  const makerRefundXOnlyPublicKey = XOnlyPublicKey.fromAddress(makerTokenRefundAddressObject as any);
  const makerRefundXOnlyPublicKeyHex = makerRefundXOnlyPublicKey.toString();
  if (!/^[0-9a-f]{64}$/i.test(makerRefundXOnlyPublicKeyHex)) throw new Error("maker_refund_public_key_invalid");
  const makerRefundAddressFromPublicKey = makerRefundXOnlyPublicKey.toAddress(params.networkId as any).toString();
  if (makerRefundAddressFromPublicKey !== makerTokenRefundAddressObject.toString()) throw new Error("maker_refund_public_key_address_mismatch");

  const policyBodyBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
    .addOp(Opcodes.OpIf)
    .addOp(Opcodes.OpTxOutputCount)
    .addI64(3n)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(0n)
    .addOp(Opcodes.OpTxOutputSpk)
    .addData(makerKasScriptPublicKeyBytes.bytes_hex)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(0n)
    .addOp(Opcodes.OpTxOutputAmount)
    .addI64(params.kasPriceSompi)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(1n)
    .addOp(Opcodes.OpTxOutputSpk)
    .addData(takerCompactHolderSpkBytes.bytes_hex)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(2n)
    .addOp(Opcodes.OpTxOutputSpk)
    .addData(takerNativeChangeScriptPublicKeyBytes.bytes_hex)
    .addOp(Opcodes.OpEqualVerify)
    .addOp(Opcodes.OpTrue)
    .addOp(Opcodes.OpElse)
    .addOp(Opcodes.OpTxOutputCount)
    .addI64(1n)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(0n)
    .addOp(Opcodes.OpTxOutputSpk)
    .addData(makerRefundCompactHolderSpkBytes.bytes_hex)
    .addOp(Opcodes.OpEqualVerify)
    .addData(makerRefundXOnlyPublicKeyHex)
    .addOp(Opcodes.OpCheckSig)
    .addOp(Opcodes.OpEndIf);

  const policyBodyScriptPublicKey = policyBodyBuilder.createPayToScriptHashScript();
  const policyBodyRedeemScriptHex = policyBodyBuilder.drain();
  const policyBodyRedeemScriptByteLen = policyBodyRedeemScriptHex.length / 2;
  const policyBodyHash = covenantSha256Text(policyBodyRedeemScriptHex);

  const swapLockedCompactHolder = omaBuildL1CompactScriptHashHolderEnvelopeProof({
    tokenSymbol: params.tokenSymbol,
    decimals: params.decimals,
    holderAmountRaw: params.holderAmountRaw,
    policyBodyRedeemScriptHex,
    networkId: params.networkId
  });

  const swapLockedOutput = new TransactionOutput(
    OMA_L1_TOKEN_TRANSFER_DEFAULT_HOLDER_CARRIER_SOMPI,
    swapLockedCompactHolder.script_public_key as any,
    new CovenantBinding(0, new Hash(params.assetCovenantId)) as any
  );

  return {
    proof_kind: "oma_l1_atomic_swap_owner_mode_compact_holder_proof_v1",
    proof_stage: "kcc20_owner_mode_4_compact_holder_inert_build_only_v1",
    token_standard_id: OMA_L1_TOKEN_STANDARD_ID,
    token_template_id: OMA_L1_TOKEN_TEMPLATE_ID,
    compact_holder_schema: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA,
    compact_holder_magic: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_MAGIC,
    supported_owner_identifier_types_for_plan: [
      OMA_L1_TOKEN_HOLDER_OWNER_TYPE_ADDRESS,
      OMA_L1_TOKEN_HOLDER_OWNER_TYPE_SCRIPT_HASH,
      OMA_L1_TOKEN_HOLDER_OWNER_TYPE_COVENANT_ID
    ],
    active_owner_mode_for_atomic_swap: OMA_L1_TOKEN_HOLDER_OWNER_TYPE_SCRIPT_HASH,
    asset_covenant_id: params.assetCovenantId,
    token_symbol: params.tokenSymbol,
    decimals: params.decimals,
    holder_amount_raw: params.holderAmountRaw.toString(),
    kas_price_sompi: params.kasPriceSompi.toString(),
    kas_price_kas: sompiTextToKasText(params.kasPriceSompi.toString()),
    refund_lock_daa: params.refundLockDaa.toString(),
    maker_kas_receive_address: makerKasAddressObject.toString(),
    maker_token_refund_address: makerTokenRefundAddressObject.toString(),
    taker_token_receive_address: takerTokenReceiveAddressObject.toString(),
    policy_body: {
      policy_body_kind: KCC20_ATOMIC_DIRECT_SWAP_POLICY_KIND_V4,
      policy_body_redeem_script_sha256: policyBodyHash,
      policy_body_redeem_script_byte_len: policyBodyRedeemScriptByteLen,
      policy_body_redeem_script_push_limit_bytes: OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      policy_body_redeem_script_pushable: policyBodyRedeemScriptByteLen <= OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      policy_body_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: policyBodyScriptPublicKey }),
      claim_selector_required: true,
      claim_path: {
        output_count: 3,
        output0_exact_kas_to_maker: true,
        output0_kas_sompi: params.kasPriceSompi.toString(),
        output0_maker_kas_script_public_key_bytes_sha256: covenantSha256Text(makerKasScriptPublicKeyBytes.bytes_hex),
        output1_taker_compact_holder_spk_bytes_sha256: covenantSha256Text(takerCompactHolderSpkBytes.bytes_hex),
        output2_taker_native_change_script_public_key_bytes_sha256: covenantSha256Text(takerNativeChangeScriptPublicKeyBytes.bytes_hex),
        output2_native_change_address: takerTokenReceiveAddressObject.toString(),
        native_change_output_allowed_by_policy: true,
        claim_path_leaves_truthy_stack_value: true,
        taker_token_receive_address: takerTokenReceiveAddressObject.toString()
      },
      refund_selector_required: true,
      refund_path: {
        lock_daa_required: false,
        refund_lock_daa: params.refundLockDaa.toString(),
        maker_cancel_anytime: true,
        maker_refund_signature_required: true,
        output_count: 1,
        output0_maker_refund_compact_holder_spk_bytes_sha256: covenantSha256Text(makerRefundCompactHolderSpkBytes.bytes_hex),
        maker_token_refund_address: makerTokenRefundAddressObject.toString()
      }
    },
    compact_holder_fields: {
      swap_locked_holder_decoded_fields: swapLockedCompactHolder.decoded_fields,
      taker_holder_decoded_fields: takerCompactHolder.decoded_fields,
      maker_refund_holder_decoded_fields: makerRefundCompactHolder.decoded_fields
    },
    compact_holder_sizes: {
      swap_locked_canonical_json_byte_len: swapLockedCompactHolder.canonical_json_byte_len,
      taker_canonical_json_byte_len: takerCompactHolder.canonical_json_byte_len,
      maker_refund_canonical_json_byte_len: makerRefundCompactHolder.canonical_json_byte_len,
      swap_locked_full_redeem_script_byte_len: swapLockedCompactHolder.redeem_script_hex_byte_len,
      taker_redeem_script_byte_len: takerCompactHolder.redeem_script_hex_byte_len,
      maker_refund_redeem_script_byte_len: makerRefundCompactHolder.redeem_script_hex_byte_len,
      p2sh_push_limit_bytes: OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      compact_holder_redeem_script_pushable: swapLockedCompactHolder.redeem_script_hex_byte_len <= OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES
    },
    swap_locked_holder: {
      owner_identifier_type: swapLockedCompactHolder.owner_identifier_type,
      owner_identifier_sha256: covenantSha256Text(swapLockedCompactHolder.owner_identifier),
      owner_identifier_matches_policy_body_sha256: swapLockedCompactHolder.owner_identifier === policyBodyHash,
      p2sh_address: swapLockedCompactHolder.p2sh_address,
      redeem_script_hex_sha256: swapLockedCompactHolder.redeem_script_hex_sha256,
      p2sh_script_public_key_json_sha256: swapLockedCompactHolder.p2sh_script_public_key_json_sha256,
      output_script_form: swapLockedCompactHolder.output_script_form,
      script_contains_state_envelope: swapLockedCompactHolder.script_contains_state_envelope,
      output_covenant_id: covenantOutputCovenantId(swapLockedOutput as any),
      output_covenant_id_matches_asset: covenantOutputCovenantId(swapLockedOutput as any) === params.assetCovenantId,
      output_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256(swapLockedOutput as any)
    },
    invariants: {
      existing_v1_holder_schema_unchanged: OMA_L1_TOKEN_HOLDER_STATE_SCHEMA === "oma_l1_token_state_v1",
      existing_holder_transfer_route_must_remain_address_owned: true,
      compact_holder_path_is_additive: true,
      no_submit_route_added: true,
      no_live_utxo_created: true,
      no_signing: true,
      no_broadcasting: true,
      no_minting: true,
      my_swaps_cancel_requires_refund_path: true,
      direct_fixed_recipient_atomic_swap_first: true,
      open_swap_dynamic_taker_claim_requires_later_proof: true
    },
    safety: {
      private_key_read: false,
      signing: "none",
      submit: "none",
      broadcasting: "none",
      minting: "none",
      wallet_mutation: "none",
      redeem_script_echoed: false,
      signature_script_echoed: false,
      signed_transaction_json_echoed: false,
      submit_token_echoed: false
    }
  };
}


function omaBuildL1AtomicOpenSwapPolicyBodyComponents(params: {
  tokenSymbol: string;
  decimals: number;
  holderAmountRaw: bigint;
  assetCovenantId: string;
  makerKasReceiveAddress: string;
  makerTokenRefundAddress: string;
  kasPriceSompi: bigint;
  networkId: string;
}): any {
  const makerKasAddressObject = new Address(params.makerKasReceiveAddress);
  const makerTokenRefundAddressObject = new Address(params.makerTokenRefundAddress);

  const makerKasScriptPublicKey = payToAddressScript(makerKasAddressObject as any);
  const makerKasScriptPublicKeyBytes = programmableKasScriptPublicKeyOutputBytesForSpk(makerKasScriptPublicKey as any);
  if (!makerKasScriptPublicKeyBytes) throw new Error("atomic_open_swap_maker_kas_script_public_key_unavailable");

  const makerRefundCompactHolder = omaBuildL1CompactAddressHolderEnvelopeProof({
    tokenSymbol: params.tokenSymbol,
    decimals: params.decimals,
    holderAmountRaw: params.holderAmountRaw,
    ownerAddress: makerTokenRefundAddressObject.toString(),
    networkId: params.networkId
  });
  const makerRefundCompactHolderSpkBytes = programmableKasScriptPublicKeyOutputBytesForSpk(makerRefundCompactHolder.script_public_key as any);
  if (!makerRefundCompactHolderSpkBytes) throw new Error("atomic_open_swap_maker_refund_compact_holder_spk_unavailable");

  const makerRefundXOnlyPublicKey = XOnlyPublicKey.fromAddress(makerTokenRefundAddressObject as any);
  const makerRefundXOnlyPublicKeyHex = makerRefundXOnlyPublicKey.toString();
  if (!/^[0-9a-f]{64}$/i.test(makerRefundXOnlyPublicKeyHex)) throw new Error("atomic_open_swap_maker_refund_public_key_invalid");
  const makerRefundAddressFromPublicKey = makerRefundXOnlyPublicKey.toAddress(params.networkId as any).toString();
  if (makerRefundAddressFromPublicKey !== makerTokenRefundAddressObject.toString()) throw new Error("atomic_open_swap_maker_refund_public_key_address_mismatch");

  const policyBodyBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
    .addOp(Opcodes.OpIf)
    .addOp(Opcodes.OpTxOutputCount)
    .addI64(3n)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(0n)
    .addOp(Opcodes.OpTxOutputSpk)
    .addData(makerKasScriptPublicKeyBytes.bytes_hex)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(0n)
    .addOp(Opcodes.OpTxOutputAmount)
    .addI64(params.kasPriceSompi)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(1n)
    .addOp(Opcodes.OpTxOutputSpk)
    .addOp(Opcodes.OpEqualVerify)
    .addOp(Opcodes.OpTrue)
    .addOp(Opcodes.OpElse)
    .addOp(Opcodes.OpTxOutputCount)
    .addI64(1n)
    .addOp(Opcodes.OpEqualVerify)
    .addI64(0n)
    .addOp(Opcodes.OpTxOutputSpk)
    .addData(makerRefundCompactHolderSpkBytes.bytes_hex)
    .addOp(Opcodes.OpEqualVerify)
    .addData(makerRefundXOnlyPublicKeyHex)
    .addOp(Opcodes.OpCheckSig)
    .addOp(Opcodes.OpEndIf);

  const policyBodyScriptPublicKey = policyBodyBuilder.createPayToScriptHashScript();
  const policyBodyRedeemScriptHex = policyBodyBuilder.drain();
  const policyBodyRedeemScriptByteLen = policyBodyRedeemScriptHex.length / 2;
  const policyBodyHash = covenantSha256Text(policyBodyRedeemScriptHex);

  return {
    maker_kas_address: makerKasAddressObject.toString(),
    maker_token_refund_address: makerTokenRefundAddressObject.toString(),
    maker_kas_script_public_key_bytes: makerKasScriptPublicKeyBytes,
    maker_refund_compact_holder: makerRefundCompactHolder,
    maker_refund_compact_holder_spk_bytes: makerRefundCompactHolderSpkBytes,
    maker_refund_xonly_public_key_hex: makerRefundXOnlyPublicKeyHex,
    policy_body_script_public_key: policyBodyScriptPublicKey,
    policy_body_redeem_script_hex: policyBodyRedeemScriptHex,
    policy_body_redeem_script_sha256: policyBodyHash,
    policy_body_redeem_script_byte_len: policyBodyRedeemScriptByteLen
  };
}

function omaBuildL1AtomicOpenSwapCompactHolderInertProof(params: {
  tokenSymbol: string;
  decimals: number;
  holderAmountRaw: bigint;
  assetCovenantId: string;
  makerKasReceiveAddress: string;
  makerTokenRefundAddress: string;
  kasPriceSompi: bigint;
  networkId: string;
}): any {
  const policy = omaBuildL1AtomicOpenSwapPolicyBodyComponents(params);

  const swapLockedCompactHolder = omaBuildL1CompactScriptHashHolderEnvelopeProof({
    tokenSymbol: params.tokenSymbol,
    decimals: params.decimals,
    holderAmountRaw: params.holderAmountRaw,
    policyBodyRedeemScriptHex: policy.policy_body_redeem_script_hex,
    networkId: params.networkId
  });

  const swapLockedOutput = new TransactionOutput(
    OMA_L1_TOKEN_TRANSFER_DEFAULT_HOLDER_CARRIER_SOMPI,
    swapLockedCompactHolder.script_public_key as any,
    new CovenantBinding(0, new Hash(params.assetCovenantId)) as any
  );

  return {
    proof_kind: "oma_l1_atomic_open_swap_owner_mode_compact_holder_proof_v1",
    proof_stage: "kcc20_open_1_dynamic_taker_compact_holder_inert_build_only_v1",
    token_standard_id: OMA_L1_TOKEN_STANDARD_ID,
    token_template_id: OMA_L1_TOKEN_TEMPLATE_ID,
    compact_holder_schema: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA,
    compact_holder_magic: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_MAGIC,
    active_owner_mode_for_atomic_swap: OMA_L1_TOKEN_HOLDER_OWNER_TYPE_SCRIPT_HASH,
    asset_covenant_id: params.assetCovenantId,
    token_symbol: params.tokenSymbol,
    decimals: params.decimals,
    holder_amount_raw: params.holderAmountRaw.toString(),
    kas_price_sompi: params.kasPriceSompi.toString(),
    kas_price_kas: sompiTextToKasText(params.kasPriceSompi.toString()),
    maker_kas_receive_address: policy.maker_kas_address,
    maker_token_refund_address: policy.maker_token_refund_address,
    policy_body: {
      policy_body_kind: KCC20_ATOMIC_OPEN_SWAP_POLICY_KIND_V1,
      policy_body_redeem_script_sha256: policy.policy_body_redeem_script_sha256,
      policy_body_redeem_script_byte_len: policy.policy_body_redeem_script_byte_len,
      policy_body_redeem_script_push_limit_bytes: OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      policy_body_redeem_script_pushable: policy.policy_body_redeem_script_byte_len <= OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      policy_body_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: policy.policy_body_script_public_key }),
      claim_selector_required: true,
      claim_path: {
        output_count: 3,
        output0_exact_kas_to_maker: true,
        output0_kas_sompi: params.kasPriceSompi.toString(),
        output0_maker_kas_script_public_key_bytes_sha256: covenantSha256Text(policy.maker_kas_script_public_key_bytes.bytes_hex),
        output1_exact_taker_spk_enforced: false,
        output1_dynamic_taker_spk_pushed_by_claim_signature_script: true,
        output1_dynamic_taker_spk_enforced_by_script: true,
        output1_dynamic_taker_holder_route_validated: true,
        output1_asset_covenant_id_enforced_by_route: true,
        output1_asset_covenant_id_enforced_by_script: false,
        output1_asset_covenant_id: params.assetCovenantId,
        output2_native_change_unconstrained_by_script: true,
        fixed_taker_token_receive_address_baked_into_policy: false,
        claim_path_leaves_truthy_stack_value: true
      },
      refund_selector_required: true,
      refund_path: {
        lock_daa_required: false,
        maker_cancel_anytime: true,
        maker_refund_signature_required: true,
        output_count: 1,
        output0_maker_refund_compact_holder_spk_bytes_sha256: covenantSha256Text(policy.maker_refund_compact_holder_spk_bytes.bytes_hex),
        maker_token_refund_address: policy.maker_token_refund_address
      }
    },
    compact_holder_fields: {
      swap_locked_holder_decoded_fields: swapLockedCompactHolder.decoded_fields,
      maker_refund_holder_decoded_fields: policy.maker_refund_compact_holder.decoded_fields
    },
    compact_holder_sizes: {
      swap_locked_canonical_json_byte_len: swapLockedCompactHolder.canonical_json_byte_len,
      maker_refund_canonical_json_byte_len: policy.maker_refund_compact_holder.canonical_json_byte_len,
      swap_locked_full_redeem_script_byte_len: swapLockedCompactHolder.redeem_script_hex_byte_len,
      maker_refund_redeem_script_byte_len: policy.maker_refund_compact_holder.redeem_script_hex_byte_len,
      p2sh_push_limit_bytes: OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      policy_body_redeem_script_pushable: policy.policy_body_redeem_script_byte_len <= OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      compact_holder_redeem_script_pushable: swapLockedCompactHolder.redeem_script_hex_byte_len <= OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES
    },
    swap_locked_holder: {
      owner_identifier_type: swapLockedCompactHolder.owner_identifier_type,
      owner_identifier_sha256: covenantSha256Text(swapLockedCompactHolder.owner_identifier),
      owner_identifier_matches_policy_body_sha256: swapLockedCompactHolder.owner_identifier === policy.policy_body_redeem_script_sha256,
      p2sh_address: swapLockedCompactHolder.p2sh_address,
      redeem_script_hex_sha256: swapLockedCompactHolder.redeem_script_hex_sha256,
      p2sh_script_public_key_json_sha256: swapLockedCompactHolder.p2sh_script_public_key_json_sha256,
      output_script_form: swapLockedCompactHolder.output_script_form,
      script_contains_state_envelope: swapLockedCompactHolder.script_contains_state_envelope,
      output_covenant_id: covenantOutputCovenantId(swapLockedOutput as any),
      output_covenant_id_matches_asset: covenantOutputCovenantId(swapLockedOutput as any) === params.assetCovenantId,
      output_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256(swapLockedOutput as any)
    },
    invariants: {
      existing_v1_holder_schema_unchanged: OMA_L1_TOKEN_HOLDER_STATE_SCHEMA === "oma_l1_token_state_v1",
      existing_holder_transfer_route_must_remain_address_owned: true,
      compact_holder_path_is_additive: true,
      dynamic_taker_receive_address_not_baked_into_maker_lock: true,
      no_submit_route_added: true,
      no_live_utxo_created: true,
      no_signing: true,
      no_broadcasting: true,
      no_minting: true
    },
    safety: {
      private_key_read: false,
      signing: "none",
      submit: "none",
      broadcasting: "none",
      minting: "none",
      wallet_mutation: "none",
      redeem_script_echoed: false,
      signature_script_echoed: false,
      signed_transaction_json_echoed: false,
      submit_token_echoed: false
    }
  };
}

function omaL1ControllerIssuedSupplyRawFromDecoded(decoded: any): string {
  return String((decoded && (decoded.issued_supply_raw ?? decoded.u)) ?? "");
}

function omaL1ControllerMaxSupplyRawFromDecoded(decoded: any): string {
  return String((decoded && (decoded.max_supply_raw ?? decoded.x)) ?? "");
}

function omaL1EnvelopeRedeemScriptPushable(proof: OmaL1TokenStateEnvelopeProof): boolean {
  return proof.redeem_script_hex_byte_len <= OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;
}

function omaL1EnvelopeOversizeProof(reason: string, proofs: Record<string, OmaL1TokenStateEnvelopeProof | null>): any {
  const result: any = {
    ok: false,
    reason,
    p2sh_redeem_script_push_limit_bytes: OMA_L1_TOKEN_P2SH_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
    signing_enabled: false,
    broadcasting_enabled: false,
    minting_enabled: false
  };
  for (const [key, proof] of Object.entries(proofs)) {
    result[key] = proof ? {
      state_schema: proof.state_schema,
      redeem_script_hex_byte_len: proof.redeem_script_hex_byte_len,
      redeem_script_pushable: omaL1EnvelopeRedeemScriptPushable(proof),
      canonical_json_byte_len: proof.canonical_json_byte_len
    } : null;
  }
  return result;
}

function omaBuildStateEnvelopeScriptPublicKey(params: {
  role: OmaL1TokenStateRole;
  ownerXOnlyPublicKey: string;
  fields: any;
}): OmaL1TokenStateEnvelopeProof {
  const canonicalJson = omaStableJson(params.fields);
  const envelopeHex = Buffer.from(canonicalJson, "utf8").toString("hex");
  const decoded = JSON.parse(Buffer.from(envelopeHex, "hex").toString("utf8"));
  const decodeRoundTripOk = omaStableJson(decoded) === canonicalJson;

  const builder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
    .addData(params.ownerXOnlyPublicKey)
    .addOp(Opcodes.OpCheckSig)
    .addOp(Opcodes.OpFalse)
    .addOp(Opcodes.OpIf)
    .addData(Buffer.from(canonicalJson, "utf8"))
    .addOp(Opcodes.OpEndIf);

  const scriptPublicKey = builder.createPayToScriptHashScript();
  const redeemScriptHex = builder.drain();
  const scriptPublicKeyJson = typeof scriptPublicKey.toJSON === "function" ? scriptPublicKey.toJSON() : null;

  return {
    role: params.role,
    state_schema: String(params.fields.schema || ""),
    canonical_json: canonicalJson,
    canonical_json_sha256: omaSha256Text(canonicalJson),
    canonical_json_byte_len: Buffer.byteLength(canonicalJson, "utf8"),
    envelope_hex: envelopeHex,
    envelope_hex_byte_len: envelopeHex.length / 2,
    decoded_fields: decoded,
    decode_round_trip_ok: decodeRoundTripOk,
    redeem_script_hex: redeemScriptHex,
    redeem_script_hex_sha256: omaSha256Text(redeemScriptHex),
    redeem_script_hex_byte_len: redeemScriptHex.length / 2,
    output_script_form: "p2sh_state_envelope_commitment",
    script_public_key: scriptPublicKey,
    script_public_key_json: scriptPublicKeyJson,
    p2sh_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey }),
    script_contains_state_envelope: redeemScriptHex.includes(envelopeHex)
  };
}

function omaL1EnvelopeProofPublic(proof: OmaL1TokenStateEnvelopeProof): any {
  return {
    role: proof.role,
    state_schema: proof.state_schema,
    canonical_json_sha256: proof.canonical_json_sha256,
    canonical_json_byte_len: proof.canonical_json_byte_len,
    envelope_hex_byte_len: proof.envelope_hex_byte_len,
    decoded_fields: proof.decoded_fields,
    decode_round_trip_ok: proof.decode_round_trip_ok,
    script_public_key_preview: {
      status: proof.script_contains_state_envelope ? "p2sh_state_envelope_committed" : "p2sh_state_envelope_not_found",
      output_script_form: proof.output_script_form,
      covenants_enabled_flag: true,
      script_contains_state_envelope: proof.script_contains_state_envelope,
      redeem_script_hex_sha256: proof.redeem_script_hex_sha256,
      redeem_script_hex_byte_len: proof.redeem_script_hex_byte_len,
      p2sh_script_public_key_json_sha256: proof.p2sh_script_public_key_json_sha256,
      script_public_key_json: proof.script_public_key_json
    }
  };
}

