    if (cached.wallet_id !== active.id || cached.fromAddress !== active.address0 || cached.network !== active.network || cached.networkId !== networkId) return res.status(409).json({ ok: false, reason: "oma_l1_change_ownership_submit_active_wallet_mismatch", broadcasting_enabled: false, minting_enabled: false });
