      tracking: { tracking_kind: "kcc20_atomic_swap_maker_lock_track_after_submit_v1", store_file: KCC20_ATOMIC_SWAP_LOCKS_FILE_NAME, record_status: trackedRecord.record_status, source_outpoint_key: trackedRecord.source_outpoint_key, covenant_id: trackedRecord.covenant_id, policy_body_redeem_script_sha256: trackedRecord.policy_body_redeem_script_sha256, swap_locked_holder_address: trackedRecord.swap_locked_holder_address },
