      tracking: { tracking_kind: "kcc20_atomic_swap_taker_claim_track_after_submit_v1", store_file: KCC20_ATOMIC_SWAP_LOCKS_FILE_NAME, record_status: updatedRecord.record_status, source_outpoint_key: updatedRecord.source_outpoint_key, claim_txid: updatedRecord.claim_txid, released_output_outpoint: updatedRecord.released_output_outpoint, oma_l1_taker_holder_tracked: takerClaimHolderTracking.tracked, oma_l1_taker_holder_outpoint: takerClaimHolderTracking.holder_outpoint },
