    const body = (req.body || {}) as any;
    const sourceOutpointKey = String(body.source_outpoint_key ?? body.sourceOutpointKey ?? body.offer_source_outpoint_key ?? body.offerSourceOutpointKey ?? "").trim();
    if (!/^[0-9a-f]{64}:\d+$/i.test(sourceOutpointKey)) {
      return res.status(400).json({ ok: false, reason: "kcc20_atomic_swap_maker_refund_source_outpoint_key_required", expected: "txid:index", signing_enabled: false, broadcasting_enabled: false, minting_enabled: false });
    }

