      tx.inputs[0].signatureScript = "";
      const sdkCalculatedFeeSompi = calculatedFee === undefined ? null : BigInt(covenantPrintable(calculatedFee) || "0");
      const sdkReportedComputeMass = BigInt(covenantPrintable(massBeforeUpdate) || "0");
