      const nodeStandardFeeFloorSompi = nodeStandardComputeMassFloor * OMA_L1_TOKEN_BURN_NODE_STANDARD_FEE_RATE_SOMPI_PER_MASS;
      const calculatedFeeSompi = sdkCalculatedFeeSompi === null ? null : (sdkCalculatedFeeSompi > nodeStandardFeeFloorSompi ? sdkCalculatedFeeSompi : nodeStandardFeeFloorSompi);
      refundBuildAttempts.push({ attempt: attemptNo, attempted_fee_reserve_sompi: attemptFeeReserveSompi.toString(), refund_output_value_sompi: refundOutputValueSompi.toString(), sdk_calculated_fee_sompi: sdkCalculatedFeeSompi === null ? null : sdkCalculatedFeeSompi.toString(), sdk_reported_compute_mass: sdkReportedComputeMass.toString(), observed_node_compute_mass_floor: KCC20_ATOMIC_SWAP_MAKER_REFUND_OBSERVED_COMPUTE_MASS_FLOOR.toString(), node_standard_compute_mass_floor: nodeStandardComputeMassFloor.toString(), node_standard_fee_floor_sompi: nodeStandardFeeFloorSompi.toString(), calculated_fee_sompi: calculatedFeeSompi === null ? null : calculatedFeeSompi.toString(), fee_mass_basis: "max_sdk_fee_and_observed_node_standard_compute_mass_floor", calculated_mass_before_update: covenantPrintable(massBeforeUpdate), storage_mass_after_update: tx.storageMass !== undefined ? covenantPrintable(tx.storageMass) : null, update_transaction_mass_ok: updateOk });
      if (!updateOk || calculatedFeeSompi === null || calculatedFeeSompi <= 0n) break;
