        seller_release_lockTime: "0",
        buyer_refund_input: "p2sh_escrow_refund_input",
        buyer_refund_rule: "buyer_signature_after_refund_lock_daa_and_one_output_to_buyer_refund_address",
        buyer_refund_output_count: 1,
